window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0131", [{"word":"grave","ipa_uk":"/ɡreɪv/","ipa_us":"/ɡreɪv/","definition_zh":"坟墓；墓穴；严重的；庄重的","definition_en":"a pit dug in the ground for a dead body; also, serious or solemn","core_image":"土里挖出的一个长方坑，上面立起一块刻字的石头；同一张脸收起笑意，眉间压下一块重量","scene":"清明清晨，山脚新挖的土坑旁摆着白花，人们静静站着不说话。The family stood silently beside the fresh grave on the hillside, white flowers in their hands.","sceneCN":"这里 grave 指「埋尸的土坑及地面标记」（第 1 个义项：埋葬死者所挖的墓穴）；句意为家人手捧白花，静静站在山坡上那座新坟旁。可辨识物件：新土、白花、山坡。","pos":[{"tag":"n.","zh":"坟墓；墓穴；埋葬处"},{"tag":"adj.","zh":"严重的；庄重的；低沉的"}],"collocations":[{"phrase":"grave danger","zh":"严重危险"},{"phrase":"grave concern","zh":"深切忧虑"},{"phrase":"grave risk","zh":"重大风险"},{"phrase":"beyond the grave","zh":"死后；在阴间"},{"phrase":"dig a grave","zh":"挖墓穴"},{"phrase":"grave accent","zh":"沉音符"}],"forms":[{"label":"复数","form":"graves"},{"label":"比较级（严重的）","form":"graver"},{"label":"最高级（严重的）","form":"gravest"},{"label":"副词","form":"gravely"},{"label":"名词（严重性）","form":"graveness"},{"label":"复合词（墓碑）","form":"gravestone"}],"derivatives":[{"word":"gravely","pos":"adv.","zh":"grave（严重）+ -ly（古英语 -līce，方式副词）→ 严重地；庄重地"},{"word":"graveness","pos":"n.","zh":"grave（严重）+ -ness（古英语 -nes，性质名词）→ 严重性；庄重"},{"word":"gravestone","pos":"n.","zh":"grave（坟墓）+ stone（古英语 stān，石头）→ 墓碑"},{"word":"graveyard","pos":"n.","zh":"grave（坟墓）+ yard（古英语 geard，围起的场地）→ 墓地；坟场"},{"word":"engrave","pos":"vt.","zh":"en-（使进入）+ grave（古英语 grafan，挖刻）→ 刻入；铭记"},{"word":"grave accent","pos":"n.","zh":"grave（沉重）+ accent（拉丁 accentus，声调）→ 沉音符"}],"senses":[{"no":"01","title":"A pit for a dead body","titleCN":"埋葬死者的墓穴","definition":"a hole dug in the ground in which a dead person is buried","definitionCN":"在地上挖出、用来埋葬死者的坑穴","example":"A plain wooden coffin was lowered into the grave.","exampleCN":"一口素木棺被放进墓穴。","why":"The burial noun began as the noun of the Old English verb grafan 'to dig', so a grave is literally the dug place.","whyCN":"坟墓义最初是古英语动词 grafan「挖」的名词形式，因此 grave 字面就是「被挖出来的地方」。"},{"no":"02","title":"The marked burial place","titleCN":"带标记的坟；安葬位置","definition":"the place where someone is buried, including the mound or stone that marks it","definitionCN":"某人被埋葬的地点，包括其上隆起的土堆或石碑","example":"They planted rosemary on her grave and visited it every spring.","exampleCN":"他们在她的坟上种了迷迭香，每年春天都去看看。","why":"Once a pit receives a marker, the marker and the pit are spoken of as a single place.","whyCN":"土坑一旦立起标记，标记与土坑在语言里就被当作同一个地点。"},{"no":"03","title":"Death itself","titleCN":"死亡（委婉说法）","definition":"death, especially in phrases that speak of passing beyond life","definitionCN":"死亡，尤用于指越过生命界限的委婉说法","example":"The letter reached us from beyond the grave.","exampleCN":"这封信像是从坟墓之外寄到我们手上的。","why":"Naming the place of the dead is a common way of naming death without saying the word.","whyCN":"以死者所在之处代指死亡，是英语里不说「死」字而说死亡的常见换称。"},{"no":"04","title":"Very serious","titleCN":"严重的；重大的","definition":"causing great worry, harm or loss; far from trivial","definitionCN":"引起极大忧虑、伤害或损失；绝非小事","example":"The report warns of a grave risk to low-lying coastal cities.","exampleCN":"报告警告低洼沿海城市面临严重风险。","why":"This adjective is a different word from the burial noun: it comes from Latin gravis 'heavy', and heavy matters are serious matters.","whyCN":"这个形容词与坟墓名词是两个词：它来自拉丁 gravis「重」，沉重的事自然就是严重的事。"},{"no":"05","title":"Solemn in manner","titleCN":"神情庄重的；严肃的","definition":"looking or sounding solemn, unsmiling and controlled","definitionCN":"神情或语气庄重、不露笑意且有克制","example":"Her grave expression silenced the room at once.","exampleCN":"她庄重的神情让屋里立刻安静下来。","why":"Latin gravis also described a person whose manner carried weight, and English kept that social sense.","whyCN":"拉丁 gravis 也形容举止有分量的人，英语保留了这个关乎举止的义项。"},{"no":"06","title":"Low in pitch","titleCN":"（声音）低沉的","definition":"deep and low in sound, as a grave tone or a grave note","definitionCN":"声音低沉，如低沉的语调或低音","example":"He answered in a grave, measured voice.","exampleCN":"他用低沉而有节制的嗓音回答。","why":"A heavy object falls low, so the 'heavy' word was extended to sounds that sit low.","whyCN":"重物往下落，于是「重」这个词被引申到位置偏低的低音上。"},{"no":"07","title":"A downward accent mark","titleCN":"沉音符（附加符号）","definition":"a mark sloping down to the right, written above a vowel in some languages","definitionCN":"向右下方倾斜、写在某些语言元音上方的符号","example":"The French word for father carries a grave accent over its first vowel.","exampleCN":"法语中「父亲」一词的第一个元音上带一个沉音符。","why":"The mark was called heavy because it was cut with a downward, weighted stroke, in contrast to the sharp acute.","whyCN":"这个符号被称为「重」，因为它以向下、带分量的笔势写成，与「尖」的锐音符相对。"},{"no":"08","title":"To carve or engrave","titleCN":"雕刻；凿刻（古旧用法）","definition":"to cut letters or a shape into wood or stone","definitionCN":"把文字或图形刻进木头或石头","example":"The names were graven into the stone by hand.","exampleCN":"这些名字是手工凿刻进石头里的。","why":"This verb is the same Old English grafan 'to dig' that gave the noun: cutting letters is digging into stone.","whyCN":"这个动词与产生名词的 grafan「挖」是同一个词：把字刻进石头，就是往石头里挖。"}],"etymology":{"intro":{"en":"Grave has two separate histories that meet in one spelling: the burial word is Old English, while the serious word came from Latin through French. Dates are approximate.","cn":"grave 的同一个拼写里汇合了两条互不相干的来历：坟墓义是古英语本族词，严肃义则经法语来自拉丁语。年代均为约数。"},"items":[{"era":"OLD ENGLISH GRAF","en":"The noun graf 'pit, trench, grave' was formed from the strong verb grafan 'to dig', which descends from Proto-Germanic graban.","cn":"名词 graf「坑、沟、墓」由强变化动词 grafan「挖」构成，后者源自原始日耳曼语 graban。"},{"era":"GERMANIC DIGGING FAMILY","en":"The same digging stock produced the English verb grave and the word engrave; Middle Dutch groeve later gave groove from the same Germanic root.","cn":"同一套「挖」的词根产生了英语动词 grave 与 engrave；中古荷兰语 groeve 后来从同一日耳曼词根给出 groove。"},{"era":"LATIN GRAVIS","en":"The adjective came from Latin gravis 'heavy, weighty, serious', the source also of gravity, gravitas, aggravate and grief.","cn":"形容词来自拉丁 gravis「重的、有分量的、严重的」，gravity、gravitas、aggravate 与 grief 也出自这个词。"},{"era":"OLD FRENCH GRAVE","en":"Old French carried the Latin adjective into English in the thirteenth century, first meaning 'weighty or worthy of respect'.","cn":"古法语在 13 世纪把这个拉丁形容词带入英语，最初意为「有分量的、值得敬重的」。"},{"era":"ACCENT SENSE","en":"Latin gravis named the 'heavy' accent mark, opposed to the 'sharp' acute, and that naming passed into English with the mark itself.","cn":"拉丁 gravis 把这种符号称为「重」符，与「尖」的锐音符相对，这一命名随符号一起进入英语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the root behind grafan is reconstructed as gherabh 'to dig, scratch', a reconstruction and not a recorded form; the step from 'heavy' to 'low pitch' is an inferred extension rather than a documented rule.","cn":"来源不确定（更深词源）：grafan 之前的词根被重构为 gherabh「挖、抓」，属重构形式而非有记录的形式；由「重」到「低音」是推断的延伸，并非有文献记载的规则。"}]},"similar":{"note":{"en":"Group one holds words that look as if they belong to grave but come from other roots; group two holds words for the same ground with different builders.","cn":"第一组是与 grave 形近却另有词源的词；第二组是同一片墓地、由不同方式造成的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"gravel","ipa":"/ˈɡræv.əl/","tag":"not related","definition":"From Old French gravele 'coarse sand', probably a diminutive of grave 'shore'; it has nothing to do with digging a grave.","definitionCN":"来自古法语 gravele「粗砂」，大概是 grave「岸」的指小形式；与挖墓毫无关系。"},{"word":"greave","ipa":"/ɡriːv/","tag":"armour word","definition":"A piece of armour for the shin, from Old French greve; it belongs to a different stock from the burial noun.","definitionCN":"护胫的甲片，来自古法语 greve；与坟墓名词并非同一来源。"},{"word":"gravy","ipa":"/ˈɡreɪ.vi/","tag":"meat juice","definition":"The juice from cooked meat, from Old French grané, probably tied to grain rather than to a grave.","definitionCN":"煮肉析出的肉汁，来自古法语 grané，大概与「谷粒」有关，而非与坟墓有关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tomb","ipa":"/tuːm/","tag":"built container","definition":"A chamber or monument for the dead, usually of stone; a grave may be only a dug hole.","definitionCN":"为死者建造的墓室或纪念建筑，通常为石制；grave 可以只是一个挖出的坑。"},{"word":"sepulcher","ipa":"/ˈsep.əl.kər/","tag":"Latin burying","definition":"From Latin sepelire 'to bury'; a formal word for a tomb, often an ornamental one.","definitionCN":"来自拉丁 sepelire「埋葬」；指坟墓的正式词，常带装饰性。"},{"word":"crypt","ipa":"/krɪpt/","tag":"hidden vault","definition":"From Greek kryptos 'hidden'; an underground vault beneath a church or tomb.","definitionCN":"来自希腊 kryptos「隐藏的」；指教堂或陵墓下方的地下墓室。"},{"word":"plot","ipa":"/plɒt/","tag":"small ground","definition":"A small measured piece of ground, especially one reserved for a burial.","definitionCN":"一小块划定的土地，尤指留作埋葬之用的地块。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real homonyms.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同形词。"},"normal":[{"en":"The burial noun and the serious adjective are homonyms: one digs, the other weighs.","cn":"坟墓名词与严肃形容词是同形异源词：一个在挖，一个在称重。"},{"en":"Old English grafan 'to dig' gives engrave, while Dutch groeve gives groove from the same Germanic root.","cn":"古英语 grafan「挖」产出 engrave，荷兰语 groeve 则从同一日耳曼词根产出 groove。"},{"en":"Fixed phrases mark the serious sense: grave danger, grave concern, grave risk.","cn":"固定搭配标出严肃义：严重危险、深切忧虑、重大风险。"},{"en":"The French grave accent is the 'heavy' mark, named against the 'sharp' acute.","cn":"法语沉音符是「重」符，与「尖」的锐音符相对得名。"},{"en":"A grave is a dug place; graven images are forms dug into stone.","cn":"grave 是被挖出的地方；graven images 是凿进石头里的形象。"}],"abstract":[{"en":"Picture a pit closing over with earth while a stone keeps the name above it.","cn":"想象一个土坑被土封住，而一块石头在上面替它留着名字。"},{"en":"Picture a smiling face where the smile is replaced by a weight between the brows.","cn":"想象一张笑脸，笑意被眉间的一块重量替换。"},{"en":"Picture a line sloping downward, like something heavy sliding off a table.","cn":"想象一条向右下倾斜的线，像重物从桌沿滑落。"}]},"examples":[{"en":"The village kept a small plot of ground as a grave for unknown travellers.","cn":"村里留了一小块地，作为无名旅人的坟墓。"},{"en":"Climate change is a grave threat to the low islands.","cn":"气候变化对这些低洼岛屿构成严重威胁。"},{"en":"He spoke in a grave voice and would not joke.","cn":"他用低沉的嗓音说话，也不肯开玩笑。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「grave（重）」——心口压上一块重石 → 严重、庄重；挖出的土坑 → 坟墓","word":"grave"},"root":"坟墓义：古英语 graf「坑、墓」，出自动词 grafan「挖」，源于原始日耳曼语 graban，更早词根为重构形式；形容词义另出拉丁 gravis「重」，经古法语入英语，两者同形异源。","sensesIntro":{"en":"Eight senses follow two histories under one spelling: the dug pit and its marker, death by association, then the Latin 'heavy' line in serious, solemn, low pitch and a downward mark, and finally the digging verb again in carving.","cn":"八个义项在一个拼写下走两条来历：先是被挖出的坑与地上标记，再由地点代指死亡；随后是拉丁「重」这条线，生出严重、庄重、低沉与向下符号；最后回到「挖」的动词义，用于雕刻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dug pit closed with earth, and a face made heavy and still.","cn":"核心意象：一个被土封住的土坑，以及一张被压得沉重而静止的脸。"},"chain":["DIG","PIT","BURIAL PLACE","DEATH","HEAVINESS","SOLEMN STILLNESS"],"branches":[{"senses":"01 · 02","en":"DUG PLACE: the pit and the stone above it are remembered as one spot.","cn":"挖出的地点：土坑与其上的石碑在记忆里是同一处。"},{"senses":"03","en":"DEATH BY PLACE: naming where the dead lie becomes a way of naming death.","cn":"以地点代死：说死者所在之处，就成了说死亡。"},{"senses":"04 · 05","en":"HEAVINESS OF MATTER: Latin 'heavy' turns into serious risk and a solemn face.","cn":"事情的沉重：拉丁「重」转为严重风险与庄重神情。"},{"senses":"06 · 07","en":"HEAVINESS IN SOUND AND MARK: low pitch and a downward stroke both carry the weight image.","cn":"声音与符号里的重：低音与向下笔画都带着重量意象。"},{"senses":"08","en":"DIGGING AGAIN: the old verb returns as the act of cutting letters into stone.","cn":"再次挖掘：古老动词回来，指把字刻进石头。"}]},"affixes":{"intro":{"en":"One spelling carries an Old English digging family and a Latin weight family, so the affix list separates the two stocks.","cn":"一个拼写承载着古英语「挖」与拉丁「重」两套词族，因此词缀表把两条来源分开。"},"latinIntro":{"en":"Latin gravis 'heavy' gives gravity, gravitas, aggravate and grief; the Old English digging stock gives grave and engrave, while Middle Dutch groeve contributes groove from the same Germanic root.","cn":"拉丁 gravis「重」衍生 gravity、gravitas、aggravate 与 grief；古英语「挖」的词族衍生 grave 与 engrave，中古荷兰语 groeve 则从同一日耳曼词根贡献 groove。"},"items":[{"word":"grave (n.)","structure":"Old English graf, noun of grafan","meaning":"a dug burial pit","meaningCN":"挖出的墓穴","example":"They dug a grave beyond the wall.","exampleCN":"他们在墙外挖了一个墓穴。"},{"word":"grave (adj.)","structure":"Latin gravis 'heavy, serious' through Old French","meaning":"serious; solemn","meaningCN":"严重的；庄重的","example":"A grave error cost them the season.","exampleCN":"一个严重错误让他们输掉了整个赛季。"},{"word":"grafan","structure":"Old English strong verb, class six","meaning":"to dig, carve","meaningCN":"挖；凿刻","example":"The old verb named both digging and carving.","exampleCN":"这个古动词既指挖土，也指凿刻。"},{"word":"engrave","structure":"en- 'into' + grave 'carve'","meaning":"to cut a design into a surface","meaningCN":"把图案刻进表面","example":"They engraved the date on the lid.","exampleCN":"他们把日期刻在盖子上。"},{"word":"groove","structure":"Middle Dutch groeve, same Germanic digging stock","meaning":"a long narrow channel","meaningCN":"长而窄的沟槽","example":"Rainwater ran along the groove in the stone.","exampleCN":"雨水沿着石头上的沟槽流走。"},{"word":"gravestone","structure":"grave (n.) + stone","meaning":"a stone marking a grave","meaningCN":"墓碑","example":"The oldest gravestone dates from the seventeenth century.","exampleCN":"最老的墓碑可追溯到十七世纪。"},{"word":"graveyard","structure":"grave (n.) + yard 'enclosed ground'","meaning":"a burial ground","meaningCN":"墓地；坟场","example":"A low wall surrounds the graveyard.","exampleCN":"一道矮墙围着墓地。"},{"word":"gravely","structure":"grave (adj.) + -ly","meaning":"in a serious manner","meaningCN":"严重地；庄重地","example":"She was gravely ill that winter.","exampleCN":"那年冬天她病得很重。"},{"word":"gravity","structure":"Latin gravitas 'weight', not the burial noun","meaning":"the force that draws bodies down","meaningCN":"重力","example":"Gravity pulled the stone into the well.","exampleCN":"重力把石头拽进井里。"}],"latinEntries":[{"word":"gravis","structure":"gravis, grave (adj., third declension)","meaning":"heavy; weighty; serious","meaningCN":"重的；有分量的；严重的"},{"word":"gravitas","structure":"gravitas, gravitatis (f., third declension)","meaning":"weight; dignity; seriousness","meaningCN":"重量；威严；庄重"}],"derivatives":[{"word":"gravely","pos":"adv.","zh":"grave（严重）+ -ly（古英语 -līce，方式副词）→ 严重地；庄重地"},{"word":"graveness","pos":"n.","zh":"grave（严重）+ -ness（古英语 -nes，性质名词）→ 严重性；庄重"},{"word":"gravestone","pos":"n.","zh":"grave（坟墓）+ stone（古英语 stān，石头）→ 墓碑"},{"word":"graveyard","pos":"n.","zh":"grave（坟墓）+ yard（古英语 geard，围起的场地）→ 墓地；坟场"},{"word":"engrave","pos":"vt.","zh":"en-（使进入）+ grave（古英语 grafan，挖刻）→ 刻入；铭记"},{"word":"grave accent","pos":"n.","zh":"grave（沉重）+ accent（拉丁 accentus，声调）→ 沉音符"}]}},{"word":"cemetery","ipa_uk":"/ˈsem.ə.tri/","ipa_us":"/ˈsem.ə.ter.i/","definition_zh":"公墓；墓地；墓葬区","definition_en":"a large area of ground, usually outside a town, where dead people are buried","core_image":"城外一片整齐的草地，成排墓碑像编号的睡床，路口一扇铁门把生者与死者隔开","scene":"城郊那片草地被矮墙围起，成排石碑在树影下向远处延伸。A low wall enclosed the cemetery, and rows of headstones ran out of sight beneath the trees.","sceneCN":"这里 cemetery 指「集中埋葬死者的大型墓园」（第 1 个义项：专设的公共墓地）；句意为矮墙围着公墓，一排排墓碑在树影下望不到头。可辨识物件：矮墙、草地、墓碑、树影。","pos":[{"tag":"n.","zh":"公墓；墓园；墓葬区"}],"collocations":[{"phrase":"military cemetery","zh":"军人公墓"},{"phrase":"pet cemetery","zh":"宠物公墓"},{"phrase":"cemetery wall","zh":"墓园围墙"},{"phrase":"cemetery plot","zh":"墓园地块"},{"phrase":"visit a cemetery","zh":"祭扫墓地"},{"phrase":"cemetery chapel","zh":"墓园礼拜堂"}],"forms":[{"label":"复数","form":"cemeteries"},{"label":"形容词","form":"cemeterial"},{"label":"相关名词（墓地）","form":"graveyard"},{"label":"相关名词（教堂墓地）","form":"churchyard"},{"label":"复合词（军人公墓）","form":"military cemetery"},{"label":"复合词（宠物公墓）","form":"pet cemetery"}],"derivatives":[{"word":"cemeterial","pos":"adj.","zh":"cemetery（墓园）+ -ial（拉丁 -ialis，形容词后缀）→ 墓园的；与墓地相关的"},{"word":"cemetery chapel","pos":"n.","zh":"cemetery + chapel（小教堂）→ 墓园礼拜堂"},{"word":"military cemetery","pos":"n.","zh":"military（军人的）+ cemetery → 军人公墓"},{"word":"pet cemetery","pos":"n.","zh":"pet（宠物）+ cemetery → 宠物公墓"},{"word":"garden cemetery","pos":"n.","zh":"garden（园林）+ cemetery → 园林式公墓"},{"word":"cemetery keeper","pos":"n.","zh":"cemetery + keeper（看守人）→ 墓园看守"}],"senses":[{"no":"01","title":"A public burial ground","titleCN":"公共墓园","definition":"a large area of land set apart for burying the dead","definitionCN":"划出专用于埋葬死者的大片土地","example":"The town opened a new cemetery beyond the ring road.","exampleCN":"小镇在环路之外开辟了一座新公墓。","why":"The word entered English as the name of a Christian burial ground, and the 'large public ground' sense grew from that.","whyCN":"这个词进入英语时指基督教墓地，「大型公共墓地」义即由此扩大而来。"},{"no":"02","title":"The cared-for grounds","titleCN":"受管理的墓园场地","definition":"the grounds themselves, with paths, lawns and trees kept in order","definitionCN":"指墓园这片场地本身，道路、草坪与树木都被打理整齐","example":"Gardeners mow the cemetery every fortnight in summer.","exampleCN":"夏天园丁每两周修剪一次墓园草地。","why":"Once a cemetery is a place rather than a single grave, its landscape becomes part of the meaning.","whyCN":"墓园一旦从单个坟墓变成一片地点，它的景观也就成了词义的一部分。"},{"no":"03","title":"A burial area outside a city","titleCN":"城郊墓葬区","definition":"an ancient or modern burial zone lying beyond the built-up area","definitionCN":"位于建成区之外的古代或现代埋葬区","example":"Archaeologists mapped the cemetery outside the old city wall.","exampleCN":"考古学家绘出了旧城墙外的墓葬区。","why":"Ancient burials were kept outside the walls for health and ritual reasons, so the word settled naturally on such zones.","whyCN":"古代出于卫生与礼制原因把墓葬置于城墙之外，因此这个词自然落在这些区域上。"},{"no":"04","title":"A military cemetery","titleCN":"军人公墓","definition":"a burial ground for soldiers, often maintained by a state","definitionCN":"安葬军人、常由国家维护的墓地","example":"Flags were placed on every stone in the military cemetery.","exampleCN":"军人公墓的每一块墓碑前都插上了旗帜。","why":"The 'outside the town' habit of the word fitted the large orderly grounds that states built for war dead.","whyCN":"这个词「位于城外」的用法，正好契合国家为阵亡者修建的大片整齐墓园。"},{"no":"05","title":"A burial ground not attached to a church","titleCN":"非教堂附属的墓地","definition":"a separate burial ground, as opposed to the churchyard beside a parish church","definitionCN":"独立墓地，与教区教堂旁的教堂墓地相对","example":"Dissenters were buried in a cemetery beyond the parish boundary.","exampleCN":"不从国教者被葬在教区边界之外的墓地。","why":"The Greek-derived word was taken up for grounds that were not church property, and the contrast with churchyard survives.","whyCN":"这个源自希腊语的词被用于非教会产业的墓地，与「教堂墓地」的对照沿用至今。"},{"no":"06","title":"A resting place for useless things","titleCN":"废弃物停放处（比喻）","definition":"a place where worn-out objects are left, as if they were dead","definitionCN":"把报废之物堆放其间，仿佛它们已经死去","example":"The lot behind the depot is a cemetery of rusting buses.","exampleCN":"车场后面的空地成了一座生锈公交车的坟场。","why":"The metaphor works because a cemetery is a place where things are laid out in rows and left.","whyCN":"这个比喻成立，因为墓园正是把东西成排摆好、然后不再过问的地方。"},{"no":"07","title":"A pet cemetery","titleCN":"宠物公墓","definition":"a burial ground reserved for animals kept as companions","definitionCN":"专为陪伴动物设置的埋葬地","example":"Thirty small stones mark the pet cemetery behind the farm.","exampleCN":"农场后面的宠物公墓立着三十块小石碑。","why":"The word extends to animals because companion animals are also laid out in marked rows and revisited.","whyCN":"这个词也延伸到动物，因为陪伴动物同样被成排安放、立碑并有人探访。"},{"no":"08","title":"A sleeping place, by the name's first sense","titleCN":"安睡之所（名称本义）","definition":"the literal sense of the Greek source, 'a place for sleeping'","definitionCN":"希腊语来源的字面义，即「供睡眠的地方」","example":"The Greek name calls the burial ground a sleeping place, not a place of punishment.","exampleCN":"这个希腊名称把墓地叫作安睡之处，而非受罚之地。","why":"Greek koimeterion was used for dormitories and for burial grounds alike, since death was pictured as sleep.","whyCN":"希腊 koimeterion 既用于宿舍也用于墓地，因为死亡被想象成睡眠。"}],"etymology":{"intro":{"en":"Cemetery comes from Greek through Latin and French, and its meaning 'sleeping place' explains both its spelling and its early Christian use. Dates are approximate.","cn":"cemetery 经拉丁语与法语来自希腊语，其「安睡之处」的本义既解释了拼写，也解释了早期基督教的用法。年代均为约数。"},"items":[{"era":"GREEK KOIMETERION","en":"Greek koimeterion meant 'sleeping room, dormitory', built on koiman 'to put to sleep', itself from keimai 'to lie down'.","cn":"希腊 koimeterion 意为「睡眠之室、宿舍」，由 koiman「使入睡」构成，后者又出自 keimai「躺卧」。"},{"era":"LATE LATIN COEMETERIUM","en":"Early Christians borrowed the word for the place where the dead 'sleep', and Latin coemeterium carried that sense.","cn":"早期基督徒借这个词指死者「安睡」之处，拉丁 coemeterium 沿用了这一含义。"},{"era":"OLD FRENCH CIMETIERE","en":"Old French cimetiere brought the word into English in the fourteenth century, spelled at first with a single medial t.","cn":"古法语 cimetiere 在 14 世纪把该词带入英语，早期拼写中间的 t 只有一个。"},{"era":"THE MEDIAL T","en":"The t in cemetery belongs to Greek -terion, not to Greek or Latin metron 'measure'; the word never meant 'measuring ground'.","cn":"cemetery 中间的 t 来自希腊语 -terion，与希腊语、拉丁语 metron「测量」无关；这个词从来没有「测量之地」的意思。"},{"era":"GARDEN CEMETERY","en":"In the nineteenth century large landscaped cemeteries outside cities made 'cemetery' the ordinary word for a public burial park.","cn":"19 世纪城郊出现大型园林式墓地，cemetery 由此成为公共墓园的常用词。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the Indo-European root behind keimai is reconstructed as kei 'to lie', a reconstruction rather than a recorded form, and the earliest Latin Christian spelling varies.","cn":"来源不确定（更深词源）：keimai 之前的印欧词根被重构为 kei「躺卧」，属重构形式而非有记录的形式；早期拉丁基督教文献中的拼写也各有不同。"}]},"similar":{"note":{"en":"Group one holds words that look like cemetery but come from another root; group two holds other names for ground set aside for the dead.","cn":"第一组是与 cemetery 形近却另有词源的词；第二组是其他指「专留给死者的土地」的名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"symmetry","ipa":"/ˈsɪm.ə.tri/","tag":"metron, not a tomb","definition":"From Greek syn 'together' plus metron 'measure'; its ending only looks like the -tery of cemetery.","definitionCN":"来自希腊 syn「一起」加 metron「测量」；词尾只是看起来像 cemetery 的 -tery。"},{"word":"seminary","ipa":"/ˈsem.ɪ.nər.i/","tag":"Latin seed plot","definition":"From Latin seminarium 'seed plot', from semen 'seed'; a school, not a burial ground.","definitionCN":"来自拉丁 seminarium「苗圃」，出自 semen「种子」；指学校，与墓地无关。"},{"word":"cenotaph","ipa":"/ˈsen.ə.tɑːf/","tag":"empty tomb","definition":"From Greek kenos 'empty' plus taphos 'tomb'; a monument for someone buried elsewhere.","definitionCN":"来自希腊 kenos「空」加 taphos「墓」；为葬在别处的人立的纪念墓。"},{"word":"cometary","ipa":"/ˈkɒm.ɪ.tər.i/","tag":"comet, not tomb","definition":"From Greek komē 'hair', the root of comet; it describes a comet's tail and shares no root with cemetery.","definitionCN":"来自希腊 komē「头发」，是 comet 的词根；形容彗尾，与 cemetery 没有共同词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"graveyard","ipa":"/ˈɡreɪv.jɑːd/","tag":"plain everyday word","definition":"The ordinary word for a burial ground, often a smaller one beside a church.","definitionCN":"墓地的日常用词，常指教堂旁较小的墓地。"},{"word":"necropolis","ipa":"/neˈkrɒp.əl.ɪs/","tag":"city of the dead","definition":"From Greek nekros 'dead' plus polis 'city'; a large ancient burial area.","definitionCN":"来自希腊 nekros「死者」加 polis「城」；指大型古代墓葬区。"},{"word":"memorial park","ipa":"/məˈmɔː.ri.əl pɑːk/","tag":"modern euphemism","definition":"A landscaped burial ground, named to avoid the word cemetery.","definitionCN":"园林式墓地，命名上避开 cemetery 一词。"},{"word":"burial ground","ipa":"/ˈber.i.əl ɡraʊnd/","tag":"neutral general term","definition":"Any ground used for burials, of any size or age.","definitionCN":"任何用于埋葬的土地，不分大小与年代。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Greek 'sleeping place', the medial t and the real landscape vocabulary of cemeteries.","cn":"正常联想：希腊语「安睡之处」、中间的 t，以及墓园真实的景观词汇。"},"normal":[{"en":"Greek koimeterion 'sleeping room' is the same image as a dormitory.","cn":"希腊 koimeterion「睡眠之室」与宿舍是同一个意象。"},{"en":"The medial t comes from Greek -terion, not from 'meter'.","cn":"中间的 t 来自希腊 -terion，不是来自 meter。"},{"en":"Real collocations: military cemetery, pet cemetery, cemetery wall.","cn":"真实搭配：军人公墓、宠物公墓、墓园围墙。"},{"en":"A cemetery is usually outside the town; a churchyard is beside the church.","cn":"cemetery 通常在城外；churchyard 在教堂旁。"},{"en":"The nineteenth-century garden cemetery gave the word its public-park sense.","cn":"19 世纪的园林式公墓赋予这个词公共墓园的义项。"}],"abstract":[{"en":"Picture rows of numbered beds in a walled garden where nobody wakes.","cn":"想象围墙花园里一排排编号的床，没有人醒来。"},{"en":"Picture a city map with a quiet district drawn outside the wall.","cn":"想象一张城市地图，墙外画着一片安静的街区。"},{"en":"Picture a gate that separates two kinds of ground by a single hinge.","cn":"想象一扇门，用一个铰链把两种土地分开。"}]},"examples":[{"en":"The cemetery lies beyond the river, away from the houses.","cn":"公墓在河对岸，远离民居。"},{"en":"Volunteers recorded every name in the old cemetery.","cn":"志愿者记下了老墓园里的每一个名字。"},{"en":"A cemetery of abandoned ships lined the shallow bay.","cn":"浅湾沿岸成了废弃船只的坟场。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cemetery」听似「睡埋特瑞」——一片睡着的墓园 → 公墓","word":"cemetery"},"root":"希腊 koimeterion「睡眠之室、宿舍」，出自动词 koiman「使入睡」与 keimai「躺卧」，经晚期拉丁 coemeterium、古法语 cimetiere 入英语；中间的 t 属希腊 -terion，与 metron「测量」无关。","sensesIntro":{"en":"Eight senses begin with the Greek image of a sleeping place and widen into managed grounds, ancient zones outside the walls, military and pet burial, the churchyard contrast, a metaphor for discarded things, and the name's literal sense.","cn":"八个义项从希腊「安睡之处」的意象出发，扩展为受管理的园区、城墙外的古代墓葬区、军人公墓与宠物公墓、与教堂墓地的对照、废弃物的比喻，最后回到名称本义。"},"semanticMap":{"core":{"en":"CORE IMAGE: a walled garden of numbered sleeping places outside a town.","cn":"核心意象：城外一座围墙花园，里面是一排排编号的安睡之处。"},"chain":["SLEEPING PLACE","WALLED GROUND","ROWS OF STONES","CITY OF THE DEAD","SEPARATE BURIAL","NEGLECTED GROUND"],"branches":[{"senses":"01 · 02","en":"MANAGED GROUND: the burial area is also a lawn, a path and a gate to be kept.","cn":"受管理的土地：墓地同时是要维护的草坪、小路与大门。"},{"senses":"03 · 04","en":"CITY OF THE DEAD: large zones outside the wall serve both ancient populations and war dead.","cn":"死者之城：墙外的大片区域既服务古代人群，也安葬阵亡者。"},{"senses":"05","en":"SEPARATE BURIAL: ground that is not church property gets a name of its own.","cn":"独立安葬：不属于教会的土地另有一个名称。"},{"senses":"06","en":"NEGLECTED GROUND: rows of dead objects borrow the burial image.","cn":"被弃之地：成排的死物借用了埋葬意象。"},{"senses":"07 · 08","en":"SLEEPING NAME: pets and the Greek literal sense both keep the 'sleep' image alive.","cn":"安睡之名：宠物公墓与希腊本义都让「睡眠」意象继续存活。"}]},"affixes":{"intro":{"en":"Cemetery is a Greek compound in origin, and its parts also build words for dormitories, and its Latin descendants name rooms and optical chambers.","cn":"cemetery 源自希腊复合词，其成分还构成指宿舍的词，拉丁后裔则用于命名房间与光学暗箱。"},"latinIntro":{"en":"Greek keimai 'to lie' underlies koimeterion; Latin camera 'vaulted room' is a different but useful neighbour for the -chamber words.","cn":"希腊 keimai「躺卧」是 koimeterion 的基底；拉丁 camera「拱顶房间」是理解 -chamber 类词的邻近线索。"},"items":[{"word":"koimeterion","structure":"Greek koiman 'put to sleep' + -terion 'place'","meaning":"a sleeping place","meaningCN":"安睡之所","example":"The Greek word named both dormitory and burial ground.","exampleCN":"这个希腊词既指宿舍，也指墓地。"},{"word":"koiman","structure":"Greek verb, 'to lull, put to sleep'","meaning":"to make someone sleep","meaningCN":"使入睡","example":"Death was described by the same verb as sleep.","exampleCN":"死亡用与睡眠相同的动词来描述。"},{"word":"keimai","structure":"Greek verb, 'to lie down'","meaning":"to lie, rest","meaningCN":"躺卧；安息","example":"The root pictures a body at rest.","exampleCN":"这个词根描绘一具安息的躯体。"},{"word":"cemetery","structure":"koimeterion through Latin and French","meaning":"a burial ground","meaningCN":"墓地；公墓","example":"The cemetery lies beyond the river.","exampleCN":"公墓在河对岸。"},{"word":"cemeterial","structure":"cemetery + -ial","meaning":"of or belonging to a cemetery","meaningCN":"墓园的","example":"Cemeterial records list the plot owners.","exampleCN":"墓园档案列有地块所有者。"},{"word":"cemetery wall","structure":"cemetery + wall","meaning":"the boundary wall of a burial ground","meaningCN":"墓园围墙","example":"Moss covers the cemetery wall.","exampleCN":"苔藓覆盖着墓园围墙。"},{"word":"military cemetery","structure":"military + cemetery","meaning":"a burial ground for soldiers","meaningCN":"军人公墓","example":"The military cemetery is mown twice a year.","exampleCN":"军人公墓每年修剪两次。"},{"word":"garden cemetery","structure":"garden + cemetery","meaning":"a landscaped public burial park","meaningCN":"园林式公墓","example":"The garden cemetery opened in 1837.","exampleCN":"这座园林式公墓于 1837 年启用。"},{"word":"pet cemetery","structure":"pet + cemetery","meaning":"a burial ground for companion animals","meaningCN":"宠物公墓","example":"Small stones fill the pet cemetery.","exampleCN":"小石碑布满宠物公墓。"}],"latinEntries":[{"word":"coemeterium","structure":"coemeterium, coemeterii (n., second declension; Late Latin)","meaning":"burial ground","meaningCN":"墓地"},{"word":"camera","structure":"camera, camerae (f., first declension)","meaning":"vaulted room, chamber","meaningCN":"拱顶房间；室"}],"derivatives":[{"word":"cemeterial","pos":"adj.","zh":"cemetery（墓园）+ -ial（拉丁 -ialis，形容词后缀）→ 墓园的；与墓地相关的"},{"word":"cemetery chapel","pos":"n.","zh":"cemetery + chapel（小教堂）→ 墓园礼拜堂"},{"word":"military cemetery","pos":"n.","zh":"military（军人的）+ cemetery → 军人公墓"},{"word":"pet cemetery","pos":"n.","zh":"pet（宠物）+ cemetery → 宠物公墓"},{"word":"garden cemetery","pos":"n.","zh":"garden（园林）+ cemetery → 园林式公墓"},{"word":"cemetery keeper","pos":"n.","zh":"cemetery + keeper（看守人）→ 墓园看守"}]}},{"word":"burial chamber","ipa_uk":"/ˈber.i.əl ˈtʃeɪm.bər/","ipa_us":"/ˈber.i.əl ˈtʃeɪm.bɚ/","definition_zh":"墓室；（陵墓内的）棺室","definition_en":"a room built underground or inside a tomb, where a body or coffin is placed","core_image":"石砌的小房间埋在地底，门口被整块石板封住，屋里只放一具棺与几件随身器物","scene":"石阶向下通向一间石砌小屋，门口被整块石板封住，屋里只摆着一具棺。Stone steps led down to a sealed burial chamber that held a single coffin.","sceneCN":"这里 burial chamber 指「墓穴内用来安放棺椁的石室」（第 1 个义项：墓中专设的置棺空间）；句意为石阶向下通向一间封住的墓室，里面只放着一具棺。可辨识物件：石阶、石板门、石室、棺。","pos":[{"tag":"n.","zh":"墓室；棺室；陵墓内室"}],"collocations":[{"phrase":"royal burial chamber","zh":"王室墓室"},{"phrase":"underground burial chamber","zh":"地下墓室"},{"phrase":"sealed burial chamber","zh":"封闭的墓室"},{"phrase":"rock-cut burial chamber","zh":"岩凿墓室"},{"phrase":"burial chamber entrance","zh":"墓室入口"},{"phrase":"family burial chamber","zh":"家族墓室"}],"forms":[{"label":"复数","form":"burial chambers"},{"label":"相关名词（埋葬）","form":"burial"},{"label":"相关名词（室墓）","form":"chamber tomb"},{"label":"相关名词（墓葬拱室）","form":"burial vault"},{"label":"相关名词（墓地）","form":"burial ground"},{"label":"相关名词（墓室入口）","form":"burial chamber entrance"}],"derivatives":[{"word":"burial","pos":"n.","zh":"bury（古英语 byrgan，埋葬）+ -al（拉丁 -alis 经法语，动作名词）→ 埋葬；葬礼"},{"word":"chambered","pos":"adj.","zh":"chamber（室）+ -ed（英语形容词后缀）→ 分成若干室的；有腔室的"},{"word":"chamber tomb","pos":"n.","zh":"chamber（室）+ tomb（墓）→ 室墓；石室墓"},{"word":"burial vault","pos":"n.","zh":"burial（埋葬）+ vault（拱顶墓穴）→ 墓葬拱室"},{"word":"burial site","pos":"n.","zh":"burial（埋葬）+ site（地点）→ 埋葬遗址"},{"word":"burial ground","pos":"n.","zh":"burial（埋葬）+ ground（土地）→ 墓地"},{"word":"burial chamber entrance","pos":"n.","zh":"burial chamber（墓室）+ entrance（入口）→ 墓室入口"}],"senses":[{"no":"01","title":"A room for a coffin","titleCN":"安放棺椁的石室","definition":"a room inside a tomb where a coffin or body is placed","definitionCN":"墓穴或陵墓内部用来放置棺木或遗体的空间","example":"The coffin was carried into the burial chamber before the slab was closed.","exampleCN":"石板封上之前，棺木被抬进墓室。","why":"The phrase simply joins the act of burying to the room that receives the body, so the name describes the room's function.","whyCN":"这个短语把「埋葬」这个动作与承接遗体的「房间」直接连在一起，名称说明的就是房间的用途。"},{"no":"02","title":"The underground part of a grave","titleCN":"墓穴的地下部分","definition":"the covered lower space dug beneath a grave, distinct from the shaft above","definitionCN":"坟墓下方被封住的空间，与上方的竖井部分相区别","example":"The shaft was filled with rubble, but the burial chamber beneath it stayed dry.","exampleCN":"竖井被碎石填满，但下面的墓室保持干燥。","why":"Once burials were cut as shafts with a side room, the room needed its own name.","whyCN":"当墓葬被挖成带侧室的竖井后，侧室就需要一个自己的名称。"},{"no":"03","title":"An inner room of a royal tomb","titleCN":"王陵内室","definition":"one of the inner rooms of a large royal or noble tomb","definitionCN":"大型王室或贵族陵墓内部的一个房间","example":"The royal burial chamber held a stone sarcophagus and a chest of ornaments.","exampleCN":"王室墓室里放着一具石棺和一只装首饰的箱子。","why":"Large tombs divide into several rooms, and the one that holds the principal body keeps the phrase.","whyCN":"大型陵墓分成若干房间，其中安放主要遗体的那一间保留了这个称呼。"},{"no":"04","title":"A room cut into rock","titleCN":"岩凿墓室","definition":"a chamber excavated directly into bedrock rather than built of masonry","definitionCN":"直接在基岩中凿出、而非用石块砌成的墓室","example":"Workers cut the rock-cut burial chamber from the cliff in a single season.","exampleCN":"工匠用一个季节就从崖壁上凿出了这间岩凿墓室。","why":"Rock-cut tombs reuse the phrase because the room, not the material, defines it.","whyCN":"岩凿墓沿用这个短语，因为定义它的是「室」这一空间，而非建筑材料。"},{"no":"05","title":"The archaeological unit","titleCN":"考古学中的墓室单元","definition":"the recorded room of a tomb as a distinct unit of excavation and study","definitionCN":"作为独立发掘与研究单元的墓葬房间","example":"Each burial chamber on the site was numbered and photographed in plan.","exampleCN":"遗址中的每一间墓室都被编号并拍摄了平面照片。","why":"Archaeology treats the room as a unit because its contents and walls can be recorded separately.","whyCN":"考古学把「室」当作单元，因为它的随葬品与四壁可以分别记录。"},{"no":"06","title":"A room for grave goods","titleCN":"随葬品存放室","definition":"a side room or recess holding objects buried with the dead","definitionCN":"存放随葬器物的侧室或壁龛","example":"The smaller burial chamber was stacked with jars and model boats.","exampleCN":"较小的那间墓室堆满了陶罐与模型船。","why":"Side chambers were often made for offerings rather than for the body, and the phrase covers both.","whyCN":"侧室常为放置供品而非安放遗体而建，这个短语两者都能指。"},{"no":"07","title":"A family vault","titleCN":"家族墓室","definition":"a chamber used by one family for several burials over time","definitionCN":"一个家族长期使用、先后安葬多人的墓室","example":"Three generations were laid in the same burial chamber beneath the chapel.","exampleCN":"三代人都被安放在礼拜堂下的同一间墓室里。","why":"When a room is reopened for later burials, the phrase shifts from a single event to a family institution.","whyCN":"当一间墓室为后续安葬反复开启，这个短语就从单次事件转为家族制度。"},{"no":"08","title":"A sealed space in metaphor","titleCN":"被封存的空间（比喻）","definition":"any closed space treated as if it held something preserved and hidden","definitionCN":"任何被当作封存、藏匿之处的封闭空间","example":"The archive is a burial chamber of forgotten files.","exampleCN":"那座档案库是一座封存被遗忘文件的墓室。","why":"The metaphor keeps two features of the literal room: it is closed, and what is inside is not meant to be disturbed.","whyCN":"这个比喻保留字面墓室的两个特征：它是封闭的，里面的东西不打算被打扰。"}],"etymology":{"intro":{"en":"Burial chamber joins an Old English burial word to a Latin-derived room word; the compound itself is a modern descriptive label. Dates are approximate.","cn":"burial chamber 把古英语的「埋葬」词与拉丁来源的「房间」词连在一起，这个复合词本身是近代的描述性称名。年代均为约数。"},"items":[{"era":"OLD ENGLISH BYRGAN","en":"Old English byrgan meant 'to bury, inter', from Proto-Germanic burjan 'to raise a mound', a word related to berg 'hill or mound'.","cn":"古英语 byrgan 意为「埋葬、安葬」，源自原始日耳曼语 burjan「堆起土丘」，与 berg「山丘、土堆」同族。"},{"era":"OLD ENGLISH BYRGELS","en":"The noun for a tomb was byrgels; Middle English reshaped it as buriel, and later speakers refashioned it as bury plus -al.","cn":"指坟墓的名词是 byrgels；中古英语把它改作 buriel，后来又说者按 bury 加 -al 重新构形。"},{"era":"GREEK KAMARA TO LATIN CAMERA","en":"Greek kamara 'vaulted cover' gave Latin camera 'vaulted room', which passed through Old French chambre into English chamber.","cn":"希腊 kamara「拱顶盖」产生拉丁 camera「拱顶房间」，再经古法语 chambre 进入英语 chamber。"},{"era":"THE COMPOUND","en":"English joins two existing nouns to name the room that receives a body; no single coining date is recorded for the phrase.","cn":"英语把两个已有名词连起来，指承接遗体的房间；这个短语没有单一可考的首创年代。"},{"era":"ARCHAEOLOGICAL USE","en":"From the nineteenth century excavated tombs were described room by room, and burial chamber became a standard unit of description.","cn":"从 19 世纪起，发掘的墓葬按房间逐一描述，burial chamber 成为标准的描述单元。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): the phrase has no recorded first citation, and whether byrgan came from a mound word or from a protecting word is disputed, so both accounts remain hypotheses.","cn":"来源不确定（首见年代与更深词源）：该短语没有可考的最早书证；byrgan 究竟出自「土丘」还是「保护」一词仍有争议，两种说法都只是假说。"}]},"similar":{"note":{"en":"Group one holds words that look like chamber or burial but come from elsewhere; group two holds other rooms and structures made for the dead.","cn":"第一组是与 chamber、burial 形近却另有来历的词；第二组是为死者造的其他房间与建筑。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"camera","ipa":"/ˈkæm.rə/","tag":"same Latin source, different sense","definition":"Latin camera 'vaulted room' also gave camera; chamber and camera are doublets, not unrelated words.","definitionCN":"拉丁 camera「拱顶房间」也产生 camera；chamber 与 camera 是同源异形词，并非无关。"},{"word":"camber","ipa":"/ˈkæm.bər/","tag":"curved, not a room","definition":"From Latin camur 'curved', describing a slight upward curve in a road or wing.","definitionCN":"来自拉丁 camur「弯曲的」，指路面或机翼的轻微上拱。"},{"word":"chamfer","ipa":"/ˈtʃæm.fər/","tag":"cut edge","definition":"From French chanfrein 'bevel', with no link to Latin camera or to a room.","definitionCN":"来自法语 chanfrein「斜切」，与拉丁 camera 或房间均无关联。"},{"word":"cemetery","ipa":"/ˈsem.ə.tri/","tag":"ground, not a room","definition":"A different burial word from Greek 'sleeping place'; it names the ground, not the inner room.","definitionCN":"另一个指墓地的词，来自希腊语「安睡之处」；它指整片土地，而非内部房间。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tomb","ipa":"/tuːm/","tag":"whole structure","definition":"The whole built structure for the dead, of which the chamber is one part.","definitionCN":"为死者建造的整体建筑，墓室只是其中一部分。"},{"word":"crypt","ipa":"/krɪpt/","tag":"hidden vault","definition":"An underground vault, especially beneath a church, from Greek kryptos 'hidden'.","definitionCN":"地下拱室，尤指教堂之下，来自希腊 kryptos「隐藏的」。"},{"word":"vault","ipa":"/vɔːlt/","tag":"arched space","definition":"An arched or domed burial space, named for its curved roof.","definitionCN":"拱形或穹顶的墓葬空间，以其弧状顶盖得名。"},{"word":"mausoleum","ipa":"/ˌmɔː.səˈliː.əm/","tag":"monumental tomb","definition":"A large monumental tomb building, from the name of Mausolus of Caria.","definitionCN":"大型纪念性陵墓建筑，得名于卡里亚的摩索拉斯。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real archaeology terms and the genuine doublet camera.","cn":"正常联想：真实构词成分、真实考古术语，以及真实存在的同源异形词 camera。"},"normal":[{"en":"Old English byrgan 'to bury' is related to berg 'hill', the image of a raised mound.","cn":"古英语 byrgan「埋葬」与 berg「山丘」同族，意象是堆起的土丘。"},{"en":"Chamber and camera are doublets from Latin camera 'vaulted room'.","cn":"chamber 与 camera 是拉丁 camera「拱顶房间」的同源异形词。"},{"en":"Real terms: rock-cut burial chamber, sealed burial chamber, royal burial chamber.","cn":"真实术语：岩凿墓室、封闭墓室、王室墓室。"},{"en":"The phrase names a function, not a material: brick, stone or bedrock all work.","cn":"这个短语命名的是功能而非材料：砖、石或基岩都可以。"},{"en":"Archaeology records the room as a unit with its own plan and contents.","cn":"考古学把墓室当作带有独立平面与随葬品的单元来记录。"}],"abstract":[{"en":"Picture a small stone room underground with a single door sealed by one slab.","cn":"想象地下一间石砌小屋，唯一的门被一块石板封住。"},{"en":"Picture a staircase descending into darkness, each step narrowing the way out.","cn":"想象一段向下走进黑暗的台阶，每一级都让退路更窄。"},{"en":"Picture a room whose furniture is a coffin and three jars, arranged for no living guest.","cn":"想象一间屋子，家具是一具棺与三只陶罐，为的不是活着的客人。"}]},"examples":[{"en":"The burial chamber was cut into the cliff and closed with a single slab.","cn":"墓室凿在崖壁里，用一块石板封住。"},{"en":"Conservators recorded the burial chamber before moving any object.","cn":"修复人员在移动任何器物之前先记录了墓室。"},{"en":"The burial chamber of the old house held letters nobody dared open.","cn":"老房子的封存之室里放着没人敢拆的信。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「burial（埋）＋chamber（房间）」——埋人的房间 → 墓室","word":"burial chamber"},"root":"burial 出古英语 byrgan「埋葬」（源自原始日耳曼语 burjan「堆起土丘」，与 berg「山丘」同族），经 byrgels、buriel 改形为 bury + -al；chamber 出希腊 kamara「拱顶盖」→ 拉丁 camera「拱顶房间」→ 古法语 chambre。","sensesIntro":{"en":"Eight senses follow the phrase from a functional room in a tomb to its underground part, royal inner room, rock-cut form, archaeological unit, grave-goods room, family vault, and finally any sealed space.","cn":"八个义项沿着这个短语展开：先是墓中承担功能的房间，再到其地下部分、王陵内室、岩凿形式、考古单元、随葬品室、家族墓室，最后是任何被封存的空间。"},"semanticMap":{"core":{"en":"CORE IMAGE: a small stone room underground whose door is sealed by one slab.","cn":"核心意象：地下一间石砌小屋，门被一块石板封住。"},"chain":["DIG","STONE ROOM","SEALED SLAB","COFFIN","GRAVE GOODS","FAMILY VAULT"],"branches":[{"senses":"01 · 02","en":"ROOM FOR THE BODY: the phrase names the space that receives the coffin, above or below the shaft.","cn":"安放遗体的房间：这个短语指承接棺木的空间，无论在竖井之上还是之下。"},{"senses":"03 · 04","en":"INNER ROOM: royal tombs and rock-cut tombs both need a named inner space.","cn":"内室：王陵与岩凿墓都需要一个有名目的内部空间。"},{"senses":"05","en":"RECORDED UNIT: excavation turns the room into a unit of plan and contents.","cn":"被记录的单元：发掘把房间变成平面与随葬品的记录单元。"},{"senses":"06 · 07","en":"GOODS AND FAMILY: side rooms hold offerings, and reopened rooms hold generations.","cn":"随葬与家族：侧室放供品，反复开启的墓室安放数代人。"},{"senses":"08","en":"SEALED SPACE: the metaphor keeps only the closed door and the undisturbed inside.","cn":"封存空间：比喻只保留关闭的门与不被扰动的内部。"}]},"affixes":{"intro":{"en":"The phrase is made of an Old English burial word and a Latin room word, so its affix list follows two families.","cn":"这个短语由古英语的「埋葬」词与拉丁语的「房间」词构成，词缀表因此沿两条词族展开。"},"latinIntro":{"en":"Latin camera 'vaulted room' also gives camera and camerarius; Old English byrgan gives bury, burial and burial ground.","cn":"拉丁 camera「拱顶房间」还产生 camera 与 camerarius；古英语 byrgan 产生 bury、burial 与 burial ground。"},"items":[{"word":"bury","structure":"Old English byrgan, strong verb","meaning":"to place a body in the ground","meaningCN":"埋葬","example":"They buried the box beneath the oak.","exampleCN":"他们把盒子埋在橡树下。"},{"word":"burial","structure":"bury + -al, reshaped from Old English byrgels","meaning":"the act or ceremony of burying","meaningCN":"埋葬；葬礼","example":"The burial took place at dawn.","exampleCN":"葬礼在黎明时举行。"},{"word":"-al","structure":"Latin -alis through French, noun-forming","meaning":"action or result","meaningCN":"动作或结果","example":"Arrival and refusal both use this suffix.","exampleCN":"arrival 与 refusal 都用这个后缀。"},{"word":"chamber","structure":"Greek kamara to Latin camera to Old French chambre","meaning":"a room, especially a private or enclosed one","meaningCN":"房间；室","example":"The council met in a side chamber.","exampleCN":"委员会在侧室开会。"},{"word":"camera","structure":"Latin camera 'vaulted room', same source as chamber","meaning":"an optical device for recording images","meaningCN":"照相机；摄影机","example":"The camera stood on a tripod.","exampleCN":"相机架在三脚架上。"},{"word":"camerarius","structure":"Latin camera + -arius 'person concerned with'","meaning":"a chamberlain, an officer of a household","meaningCN":"宫廷内侍；司库","example":"The camerarius kept the household accounts.","exampleCN":"内侍掌管家中账目。"},{"word":"chambered","structure":"chamber + -ed","meaning":"divided into chambers","meaningCN":"分成若干室的","example":"The chambered shell has five internal rooms.","exampleCN":"这种有室贝壳内部有五个小室。"},{"word":"chamber tomb","structure":"chamber + tomb","meaning":"a tomb built around one or more rooms","meaningCN":"室墓；石室墓","example":"The chamber tomb was cut into soft rock.","exampleCN":"这座室墓凿在软岩中。"},{"word":"burial vault","structure":"burial + vault","meaning":"an arched space for burials","meaningCN":"墓葬拱室","example":"The family used a burial vault beneath the aisle.","exampleCN":"这家人使用过道下的墓葬拱室。"}],"latinEntries":[{"word":"camera","structure":"camera, camerae (f., first declension)","meaning":"vaulted room, chamber","meaningCN":"拱顶房间；室"},{"word":"camerarius","structure":"camerarius, camerarii (m., second declension)","meaning":"chamberlain, household officer","meaningCN":"内侍；管家"}],"derivatives":[{"word":"burial","pos":"n.","zh":"bury（古英语 byrgan，埋葬）+ -al（拉丁 -alis 经法语，动作名词）→ 埋葬；葬礼"},{"word":"chambered","pos":"adj.","zh":"chamber（室）+ -ed（英语形容词后缀）→ 分成若干室的；有腔室的"},{"word":"chamber tomb","pos":"n.","zh":"chamber（室）+ tomb（墓）→ 室墓；石室墓"},{"word":"burial vault","pos":"n.","zh":"burial（埋葬）+ vault（拱顶墓穴）→ 墓葬拱室"},{"word":"burial site","pos":"n.","zh":"burial（埋葬）+ site（地点）→ 埋葬遗址"},{"word":"burial ground","pos":"n.","zh":"burial（埋葬）+ ground（土地）→ 墓地"},{"word":"burial chamber entrance","pos":"n.","zh":"burial chamber（墓室）+ entrance（入口）→ 墓室入口"}]}},{"word":"sarcophagus","ipa_uk":"/sɑːˈkɒf.ə.ɡəs/","ipa_us":"/sɑːrˈkɑː.fə.ɡəs/","definition_zh":"石棺；（比喻）封存危险物的巨型罩体","definition_en":"a stone coffin, especially one carved or decorated, used for an important burial","core_image":"一具雕满人像的长石箱停在墓室中央，盖板合上后，石头像要把里面的东西慢慢吞掉","scene":"墓室中央停着一具雕满人像的长石箱，盖板半开，里面空无一物。A carved stone sarcophagus stood at the centre of the chamber, its lid half open and the inside empty.","sceneCN":"这里 sarcophagus 指「雕刻精美的石制棺具」（第 1 个义项：用于重要墓葬的石棺）；句意为墓室中央立着一具雕花石棺，盖板半开，里面空空。可辨识物件：石棺、浮雕、半开的盖板、空墓室。","pos":[{"tag":"n.","zh":"石棺；雕饰石棺；（比喻）巨型封罩"}],"collocations":[{"phrase":"stone sarcophagus","zh":"石棺"},{"phrase":"carved sarcophagus","zh":"雕花石棺"},{"phrase":"marble sarcophagus","zh":"大理石石棺"},{"phrase":"sarcophagus lid","zh":"石棺盖"},{"phrase":"royal sarcophagus","zh":"王室石棺"},{"phrase":"lead sarcophagus","zh":"铅制棺具"}],"forms":[{"label":"复数（拉丁式）","form":"sarcophagi"},{"label":"复数（英语式）","form":"sarcophaguses"},{"label":"形容词","form":"sarcophagal"},{"label":"相关名词（石棺盖）","form":"sarcophagus lid"},{"label":"相关名词（石棺葬）","form":"sarcophagus burial"},{"label":"复合词（石制棺具）","form":"stone sarcophagus"}],"derivatives":[{"word":"sarcophagal","pos":"adj.","zh":"sarcophagus（石棺）+ -al（拉丁 -alis，形容词后缀）→ 石棺的；石棺状的"},{"word":"sarcophagy","pos":"n.","zh":"sarco-（希腊 sarx，肉）+ -phagy（希腊 -phagia，吃）→ 食肉；食尸"},{"word":"sarcophagous","pos":"adj.","zh":"sarco-（肉）+ -phagous（吃……的）→ 食肉的"},{"word":"sarcophagus lid","pos":"n.","zh":"sarcophagus（石棺）+ lid（盖）→ 石棺盖"},{"word":"sarcophagus burial","pos":"n.","zh":"sarcophagus（石棺）+ burial（埋葬）→ 石棺葬"},{"word":"stone sarcophagus","pos":"n.","zh":"stone（石）+ sarcophagus → 石制棺具"}],"senses":[{"no":"01","title":"A decorated stone coffin","titleCN":"雕饰石棺","definition":"a stone coffin, often carved with reliefs and inscriptions","definitionCN":"石制棺具，常带浮雕与铭文","example":"The marble sarcophagus was carved with scenes of the hunt.","exampleCN":"这具大理石石棺上雕着狩猎场景。","why":"The word moved from the name of a stone to the coffin cut from it, and decoration became typical of the grandest examples.","whyCN":"这个词从石头之名转到用它凿成的棺具，而最华贵的实例往往带雕刻。"},{"no":"02","title":"Any stone burial container","titleCN":"石制葬具（通称）","definition":"a rigid stone container for a body, whether plain or ornamented","definitionCN":"刚硬的石制遗体容器，不论素面或带纹饰","example":"A plain sarcophagus of local limestone held the priest's body.","exampleCN":"一具本地石灰岩的素面石棺安放着这位祭司的遗体。","why":"The material, not the decoration, keeps the name in place, so a plain box still counts.","whyCN":"留住名称的是材质而非纹饰，因此素面石箱也算在内。"},{"no":"03","title":"The flesh-eating stone of the name","titleCN":"名称所指的「食肉石」","definition":"the limestone once believed to consume a body placed inside it","definitionCN":"一种曾被认为能吞食棺中遗体的石灰岩","example":"Pliny describes a sarcophagus stone from Assos that was said to consume corpses.","exampleCN":"普林尼描述过阿索斯出产的一种石棺石，据说能腐蚀尸体。","why":"The original sense is a mineral claim, not a coffin, and the coffin was named after the stone.","whyCN":"本义是对一种石材的说法，并非棺具；棺具是以这种石头命名的。"},{"no":"04","title":"A coffin of another material","titleCN":"其他材质的棺具（引申）","definition":"a coffin shaped like a stone sarcophagus but made of lead, wood or metal","definitionCN":"外形仿石棺、但以铅、木或金属制成的棺具","example":"A lead sarcophagus was sealed inside the outer stone box.","exampleCN":"一具铅棺被密封在外层石箱里。","why":"Because the shape and function stayed the same, the word followed the form into other materials.","whyCN":"由于形状与功能未变，这个词随形制进入了其他材质。"},{"no":"05","title":"A protective shell over a reactor","titleCN":"反应堆外的巨型封罩（比喻）","definition":"a massive protective structure built over a damaged nuclear reactor","definitionCN":"建在受损核反应堆之上的巨型防护结构","example":"Engineers raised a steel sarcophagus over the ruined reactor.","exampleCN":"工程师在损毁的反应堆上架起一座钢制石棺式封罩。","why":"The metaphor borrows the coffin image: something dangerous is enclosed and kept from the world.","whyCN":"这个比喻借用了棺具意象：危险之物被包住，与世界隔开。"},{"no":"06","title":"Something that encloses and hides","titleCN":"吞没并封藏之物（比喻）","definition":"anything that encloses something so that it is hidden from view","definitionCN":"把某物包住、使其从视野中消失的任何东西","example":"The old station became a sarcophagus of rusted machinery.","exampleCN":"老车站成了一具封着锈蚀机械的石棺。","why":"The metaphor extends from the reactor shell to any enclosing structure that hides its contents.","whyCN":"比喻从反应堆封罩扩展到任何把内部藏起来的包围结构。"},{"no":"07","title":"A burial recorded by its stone box","titleCN":"以石棺记录的墓葬（考古术语）","definition":"an archaeological burial classified by the stone container used","definitionCN":"按所用石制容器分类的考古墓葬","example":"The cemetery's richest burial was a sarcophagus burial with three rings.","exampleCN":"这片墓地最丰富的墓葬是一座随葬三枚戒指的石棺葬。","why":"Archaeology names a burial type by its container, so the object gives its name to the whole grave.","whyCN":"考古学按容器给墓葬类型命名，于是器物之名成了整座墓的名称。"},{"no":"08","title":"A storage box shaped like a coffin","titleCN":"棺形储物石箱（引申）","definition":"a stone box of coffin shape used for storing or displaying objects","definitionCN":"棺形石箱，用于存放或陈列物件","example":"The museum keeps the broken statues in a stone sarcophagus.","exampleCN":"博物馆把破损雕像存放在一只石棺式石箱里。","why":"The shape survives even when the burial function is gone, which is how the word reaches museum storage.","whyCN":"即使埋葬功能消失，形状仍保留下来，词义因此进入博物馆库房。"}],"etymology":{"intro":{"en":"Sarcophagus is a Greek adjective meaning 'flesh-eating' that became the name of a stone and then of the coffin made from it. Dates are approximate.","cn":"sarcophagus 是一个意为「食肉的」希腊形容词，先成为一种石头的名称，再成为用它制成的棺具之名。年代均为约数。"},"items":[{"era":"GREEK SARX","en":"Greek sarx, genitive sarkos, meant 'flesh'; it also supplies sarcoma and sarcasm's older image of tearing flesh.","cn":"希腊 sarx（属格 sarkos）意为「肉」，也构成 sarcoma，并为 sarcasm 提供「撕肉」的旧意象。"},{"era":"GREEK PHAGEIN","en":"Greek phagein meant 'to eat'; the combining form -phagos 'eating' appears in many scientific words.","cn":"希腊 phagein 意为「吃」，组合形式 -phagos「吃……的」出现在许多科学词中。"},{"era":"GREEK SARKOPHAGOS","en":"Sarkophagos 'flesh-eating' was used of a limestone, sarkophagos lithos, said to consume bodies buried in it.","cn":"sarkophagos「食肉的」被用于一种石灰岩，即 sarkophagos lithos，据说会腐蚀葬在其中的尸体。"},{"era":"LATIN SARCOPHAGUS","en":"Latin sarcophagus named both the stone and the coffin; Pliny reports the stone of Assos and the belief attached to it.","cn":"拉丁 sarcophagus 既指这种石头也指棺具；普林尼记载了阿索斯的石头及附于其上的说法。"},{"era":"ENGLISH","en":"English adopted the word in the early seventeenth century for an ornate stone coffin, and later for any rigid stone container.","cn":"英语在 17 世纪初借入这个词，指雕饰石棺，后来泛指任何刚硬的石制容器。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (the stone's claim and the deeper root): whether the Assos limestone really consumed bodies is an ancient report that has not been demonstrated, and the pre-Greek origin of phagein is unsettled, so any reconstructed root is a reconstruction.","cn":"来源不确定（石材说法与更深词根）：阿索斯石灰岩是否真能腐蚀尸体只是古代记载，未获实证；phagein 的希腊语之前来源亦无定论，凡给出的词根均属重构形式。"}]},"similar":{"note":{"en":"Group one holds words whose Greek parts look like sarcophagus but carry another meaning; group two holds other containers for the dead.","cn":"第一组是希腊成分看似与 sarcophagus 相同、实际另有含义的词；第二组是其他安放死者的容器。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"sarcasm","ipa":"/ˈsɑː.kæz.əm/","tag":"flesh-tearing image, not a coffin","definition":"From Greek sarkazein 'to tear flesh', built on sarx; it shares the flesh root but never named a stone or coffin.","definitionCN":"来自希腊 sarkazein「撕肉」，由 sarx 构成；它与「肉」词根共享，却从未指石头或棺具。"},{"word":"sarcoma","ipa":"/sɑːˈkəʊ.mə/","tag":"flesh tumour","definition":"From Greek sarx plus -oma 'tumour'; a medical word from the same flesh root.","definitionCN":"来自希腊 sarx 加 -oma「肿瘤」；同出「肉」词根的医学术语。"},{"word":"esophagus","ipa":"/iˈsɒf.ə.ɡəs/","tag":"different first element","definition":"From Greek oisophagos, whose first part is uncertain; the -phagos ending is shared, the whole word is not.","definitionCN":"来自希腊 oisophagos，前半部分来源不确定；只共享 -phagos 词尾，整词并非同源。"},{"word":"sarcophile","ipa":"/ˈsɑː.kə.faɪl/","tag":"flesh-loving","definition":"Sarco- 'flesh' plus -phile 'loving'; it shares both parts but reverses the eating image.","definitionCN":"sarco-「肉」加 -phile「喜爱」；两部分都共享，却把「吃」的意象反了过来。"}]},{"heading":"NEAR MEANING","entries":[{"word":"coffin","ipa":"/ˈkɒf.ɪn/","tag":"general box","definition":"The general word for a box for a body, usually of wood.","definitionCN":"指盛放遗体的箱具的通用词，通常为木制。"},{"word":"casket","ipa":"/ˈkɑː.skɪt/","tag":"ornate box","definition":"A decorative box for a body, more common in American usage.","definitionCN":"装饰性遗体箱，在美式用法中更常见。"},{"word":"tomb","ipa":"/tuːm/","tag":"whole structure","definition":"The whole built grave, which may contain a sarcophagus.","definitionCN":"整体墓葬建筑，内部可能放有石棺。"},{"word":"vault","ipa":"/vɔːlt/","tag":"arched room","definition":"An arched burial room rather than the container itself.","definitionCN":"拱形墓葬房间，而非容器本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek parts, the Assos stone story and the modern reactor shell.","cn":"正常联想：真实的希腊成分、阿索斯石头的记载，以及现代反应堆封罩。"},"normal":[{"en":"Greek sarx 'flesh' plus phagein 'eat' gives 'flesh-eating'.","cn":"希腊 sarx「肉」加 phagein「吃」构成「食肉的」。"},{"en":"The name first belonged to a limestone said to consume bodies.","cn":"这个名字最初属于一种据说能腐蚀尸体的石灰岩。"},{"en":"The plural is usually sarcophagi in scholarly writing.","cn":"学术写作中复数通常作 sarcophagi。"},{"en":"The Chernobyl shelter is called a sarcophagus in news language.","cn":"新闻语言把切尔诺贝利的掩体称作石棺式封罩。"},{"en":"Real collocations: marble sarcophagus, carved sarcophagus, sarcophagus lid.","cn":"真实搭配：大理石石棺、雕花石棺、石棺盖。"}],"abstract":[{"en":"Picture a stone box that slowly eats what is laid inside it.","cn":"想象一只石箱，慢慢吃掉放进去的东西。"},{"en":"Picture a lid closing over a room and turning a person into a hidden object.","cn":"想象一块盖板合上，把一个人变成藏起来的物件。"},{"en":"Picture a huge steel shell over a broken machine, keeping its poison inside.","cn":"想象一只巨大的钢壳罩住坏掉的机器，把毒留在里面。"}]},"examples":[{"en":"The sarcophagus was carved with a procession of mourners.","cn":"石棺上雕着送葬者的行列。"},{"en":"A lead sarcophagus was found inside the stone box.","cn":"石箱内发现了一具铅制棺具。"},{"en":"The damaged reactor was covered by a concrete sarcophagus.","cn":"受损反应堆被一座混凝土封罩盖住。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「sarco（肉）＋phagus（吃）」——吃肉的石头 → 石棺","word":"sarcophagus"},"root":"希腊 sarkophagos「食肉的」= sarx（sarkos，肉）+ phagein（吃）；原指一种据说能腐蚀尸体的石灰岩，经拉丁 sarcophagus 入英语，转指石棺。","sensesIntro":{"en":"Eight senses move from the carved stone coffin to any stone container, back to the literal flesh-eating stone, sideways to other materials, then to the reactor shell and any enclosing structure, and finally to a burial type and a storage box.","cn":"八个义项从雕饰石棺到泛指石制容器，再回到字面的「食肉石」，横向扩展到其他材质，随后是反应堆封罩与任何包围结构，最后是墓葬类型与储物石箱。"},"semanticMap":{"core":{"en":"CORE IMAGE: a carved stone box whose closed lid seems to swallow what it holds.","cn":"核心意象：一只雕花石箱，盖板一合，仿佛把里面的东西吞了下去。"},"chain":["FLESH","EATING","FLESH-EATING STONE","STONE COFFIN","CARVED BOX","PROTECTIVE SHELL"],"branches":[{"senses":"01 · 02","en":"STONE CONTAINER: ornament or none, the word settles on the rigid box for a body.","cn":"石制容器：无论有无雕饰，这个词都落在安放遗体的刚硬箱体上。"},{"senses":"03","en":"FLESH-EATING STONE: the literal mineral claim is kept as the etymological sense.","cn":"食肉之石：字面的石材说法作为词源义保留。"},{"senses":"04","en":"OTHER MATERIALS: shape and function carry the name into lead and wood.","cn":"其他材质：形状与功能把名称带进铅与木。"},{"senses":"05 · 06","en":"PROTECTIVE SHELL: the coffin image becomes any enclosure that hides danger.","cn":"防护外壳：棺具意象转为任何藏起危险的包围体。"},{"senses":"07 · 08","en":"NAMED BY THE BOX: a burial type and a storage box are both called after the container.","cn":"以箱命名：墓葬类型与储物箱都以这个容器命名。"}]},"affixes":{"intro":{"en":"Sarcophagus is built from two productive Greek elements, and those elements also build medical and biological words.","cn":"sarcophagus 由两个能产的希腊成分构成，这两个成分还构成医学与生物学的词。"},"latinIntro":{"en":"Greek sarx 'flesh' gives sarcophagus, sarcoma and sarcasm; Greek phagein 'eat' gives -phagy and -phagous.","cn":"希腊 sarx「肉」产生 sarcophagus、sarcoma 与 sarcasm；希腊 phagein「吃」产生 -phagy 与 -phagous。"},"items":[{"word":"sarx","structure":"Greek noun, genitive sarkos, 'flesh'","meaning":"flesh","meaningCN":"肉","example":"Sarx is the first element of the word.","exampleCN":"sarx 是这个词的第一个成分。"},{"word":"sarkos","structure":"Greek genitive stem used in compounds","meaning":"of flesh","meaningCN":"肉的","example":"The stem appears before the eating element.","exampleCN":"这个词干出现在「吃」的成分之前。"},{"word":"phagein","structure":"Greek verb, 'to eat'","meaning":"to eat","meaningCN":"吃","example":"Phagein supplies the second half of the word.","exampleCN":"phagein 提供词的后半部分。"},{"word":"-phagos","structure":"Greek combining form, 'eating'","meaning":"eating, feeding on","meaningCN":"吃……的","example":"Sarkophagos literally reads 'flesh-eating'.","exampleCN":"sarkophagos 字面读作「食肉的」。"},{"word":"sarcophagus","structure":"sarkophagos through Latin","meaning":"a stone coffin","meaningCN":"石棺","example":"The sarcophagus stood in the centre.","exampleCN":"石棺立在中央。"},{"word":"sarcophagal","structure":"sarcophagus + -al","meaning":"of or like a sarcophagus","meaningCN":"石棺的；石棺状的","example":"The sarcophagal lid was carved in relief.","exampleCN":"石棺盖是浮雕的。"},{"word":"sarcophagy","structure":"sarco- 'flesh' + -phagy 'eating'","meaning":"the eating of flesh","meaningCN":"食肉；食尸","example":"Sarcophagy is rare outside technical writing.","exampleCN":"sarcophagy 在技术写作之外很少使用。"},{"word":"sarcophagous","structure":"sarco- 'flesh' + -phagous 'eating'","meaning":"flesh-eating","meaningCN":"食肉的","example":"A sarcophagous insect feeds on dead flesh.","exampleCN":"食肉昆虫以死肉为食。"},{"word":"sarcoma","structure":"sarx 'flesh' + -oma 'tumour'","meaning":"a tumour of connective tissue","meaningCN":"肉瘤","example":"Sarcoma is a medical term from the same root.","exampleCN":"sarcoma 是同根词的医学术语。"}],"latinEntries":[{"word":"sarcophagus","structure":"sarcophagus, sarcophagi (m., second declension; Latin from Greek)","meaning":"flesh-eating stone; a stone coffin","meaningCN":"食肉石；石棺"},{"word":"sarkophagos","structure":"sarkophagos (Greek adjective, 'flesh-eating')","meaning":"flesh-eating","meaningCN":"食肉的"}],"derivatives":[{"word":"sarcophagal","pos":"adj.","zh":"sarcophagus（石棺）+ -al（拉丁 -alis，形容词后缀）→ 石棺的；石棺状的"},{"word":"sarcophagy","pos":"n.","zh":"sarco-（希腊 sarx，肉）+ -phagy（希腊 -phagia，吃）→ 食肉；食尸"},{"word":"sarcophagous","pos":"adj.","zh":"sarco-（肉）+ -phagous（吃……的）→ 食肉的"},{"word":"sarcophagus lid","pos":"n.","zh":"sarcophagus（石棺）+ lid（盖）→ 石棺盖"},{"word":"sarcophagus burial","pos":"n.","zh":"sarcophagus（石棺）+ burial（埋葬）→ 石棺葬"},{"word":"stone sarcophagus","pos":"n.","zh":"stone（石）+ sarcophagus → 石制棺具"}]}},{"word":"mummy","ipa_uk":"/ˈmʌm.i/","ipa_us":"/ˈmʌm.i/","definition_zh":"木乃伊；干尸；（英式儿语）妈妈","definition_en":"a dead body preserved by embalming or by natural drying, especially one from ancient Egypt","core_image":"一具被布条层层缠住的遗体，皮肤干成皮革，眼睛的位置只剩两个深窝","scene":"展柜里的遗体被布条层层缠住，皮肤干成深褐色，标签写着出土地点。The mummy lay in the case, wrapped in layer upon layer of linen, its skin dried to a dark brown.","sceneCN":"这里 mummy 指「经防腐或自然干燥而保存下来的遗体」（第 1 个义项：人工或自然形成的干尸）；句意为展柜里一具木乃伊被层层亚麻布包裹，皮肤干成深褐色。可辨识物件：亚麻布、展柜、干枯的手。","pos":[{"tag":"n.","zh":"木乃伊；干尸；（英式儿语）妈妈"}],"collocations":[{"phrase":"Egyptian mummy","zh":"埃及木乃伊"},{"phrase":"mummy case","zh":"木乃伊棺匣"},{"phrase":"mummy cloth","zh":"木乃伊裹布"},{"phrase":"animal mummy","zh":"动物木乃伊"},{"phrase":"mummy brown","zh":"木乃伊棕（颜料）"},{"phrase":"unwrap a mummy","zh":"解开木乃伊裹布"}],"forms":[{"label":"复数","form":"mummies"},{"label":"动词（使成干尸）","form":"mummify"},{"label":"形容词（已成干尸的）","form":"mummified"},{"label":"名词（干尸制作）","form":"mummification"},{"label":"复合词（木乃伊棺匣）","form":"mummy case"},{"label":"复合词（木乃伊裹布）","form":"mummy cloth"}],"derivatives":[{"word":"mummify","pos":"vt./vi.","zh":"mummy（木乃伊）+ -fy（拉丁 -ficare，使成为）→ 使成木乃伊；干尸化"},{"word":"mummification","pos":"n.","zh":"mummify（使成木乃伊）+ -ation（拉丁 -atio，过程名词）→ 木乃伊化；干尸制作"},{"word":"mummified","pos":"adj.","zh":"mummify（使成木乃伊）+ -ed（已完成的）→ 已成干尸的"},{"word":"mummy case","pos":"n.","zh":"mummy（木乃伊）+ case（箱匣）→ 木乃伊棺匣"},{"word":"mummy cloth","pos":"n.","zh":"mummy（木乃伊）+ cloth（布）→ 木乃伊裹布"},{"word":"mummy brown","pos":"n.","zh":"mummy（木乃伊）+ brown（棕色）→ 木乃伊棕（颜料）"},{"word":"mummy portrait","pos":"n.","zh":"mummy（木乃伊）+ portrait（肖像）→ 木乃伊肖像"}],"senses":[{"no":"01","title":"An embalmed body","titleCN":"经防腐保存的遗体","definition":"a dead body preserved by embalming so that it does not decay","definitionCN":"经防腐处理、因而不腐坏的遗体","example":"The mummy was wrapped in linen and laid in a painted case.","exampleCN":"这具木乃伊用亚麻布包裹，安放在彩绘棺匣里。","why":"The word first named a medicinal substance from embalmed bodies, then the bodies themselves.","whyCN":"这个词最初指从防腐尸体中取得的一种药，随后才指尸体本身。"},{"no":"02","title":"An Egyptian mummy","titleCN":"埃及木乃伊","definition":"a body preserved by the Egyptian embalming tradition","definitionCN":"按埃及防腐传统保存下来的遗体","example":"The Egyptian mummy was scanned without opening its wrappings.","exampleCN":"这具埃及木乃伊未拆裹布就做了扫描。","why":"Egyptian examples were so famous that the word became almost a proper label for them.","whyCN":"埃及的实例过于著名，这个词几乎成了它们的专称。"},{"no":"03","title":"A naturally dried body","titleCN":"自然干尸","definition":"a body dried by sand, wind or cold before decay could proceed","definitionCN":"在腐坏开始前被沙、风或寒冷干燥保存的遗体","example":"The desert mummy was preserved by dry air rather than by resin.","exampleCN":"这具沙漠干尸靠干燥空气而非树脂保存下来。","why":"Once the body, not the method, defines the word, natural drying also counts.","whyCN":"一旦定义这个词的是遗体而非处理方法，自然干燥也算在内。"},{"no":"04","title":"An animal mummy","titleCN":"动物木乃伊","definition":"a preserved animal body, often a sacred or companion animal","definitionCN":"被保存下来的动物遗体，常为圣兽或陪伴动物","example":"Cat mummies were sold as offerings in the temple courts.","exampleCN":"猫木乃伊在神庙庭院里作为供品出售。","why":"The practice extended to animals, and the word followed without a separate term.","whyCN":"这种做法扩展到动物，词也随之延伸，并未另造新词。"},{"no":"05","title":"Mother, in British nursery speech","titleCN":"妈妈（英式儿语）","definition":"a child's word for mother, from a different nursery syllable","definitionCN":"儿童对母亲的称呼，来自另一个儿语词","example":"The child ran to her mummy at the gate.","exampleCN":"孩子跑向门口的妈妈。","why":"This homonym comes from the nursery word mum, not from Arabic mumiya, and the two histories never touch.","whyCN":"这个同形词来自儿语词 mum，而非阿拉伯语 mumiya，两条来历从未交汇。"},{"no":"06","title":"The bitumen drug of the old name","titleCN":"沥青药（旧义）","definition":"the medicinal substance formerly prepared from embalmed bodies or from bitumen","definitionCN":"旧时取自防腐尸体或沥青的药用物质","example":"Apothecaries sold mummy as a cure for bruises.","exampleCN":"旧时药剂师把木乃伊药当作治跌打的药出售。","why":"Arabic mumiya named bitumen, and the drug sense came before the body sense in English.","whyCN":"阿拉伯语 mumiya 指沥青，英语中「药」义先于「遗体」义出现。"},{"no":"07","title":"A dried-out, gaunt person","titleCN":"干瘪憔悴的人（比喻）","definition":"a living person who looks dried out and stiff","definitionCN":"看起来干枯僵硬的活人","example":"He came back from the desert a mummy of his former self.","exampleCN":"他从沙漠回来，成了昔日自己的干尸。","why":"The metaphor uses the mummy's dryness and stiffness, not its death.","whyCN":"这个比喻取的是木乃伊的干与僵，而非它的死亡。"},{"no":"08","title":"Mummy brown pigment","titleCN":"木乃伊棕（颜料）","definition":"a brown pigment formerly made from ground mummy remains","definitionCN":"旧时用研磨的木乃伊遗骸制成的棕色颜料","example":"Mummy brown was used for shadows until supplies ran out.","exampleCN":"木乃伊棕曾被用来画阴影，直到原料耗尽。","why":"The pigment trade named the colour after its source, and the colour outlived the practice.","whyCN":"颜料贸易以原料给颜色命名，而颜色比这种做法活得更久。"}],"etymology":{"intro":{"en":"Mummy began as the name of bitumen and a medicine, then shifted to the embalmed bodies that supplied it; English also has a separate nursery word mummy for mother. Dates are approximate.","cn":"mummy 先是沥青与一种药的名称，后转到提供这种药的防腐尸体上；英语另有一个指母亲的儿语同形词。年代均为约数。"},"items":[{"era":"PERSIAN MUM","en":"Persian mum meant 'wax', and the word passed into Arabic as the name of a bituminous substance.","cn":"波斯语 mum 意为「蜡」，这个词进入阿拉伯语后指一种沥青状物质。"},{"era":"ARABIC MUMIYA","en":"Arabic mumiya named bitumen, especially the pitch used in embalming, and also the preserved body that contained it.","cn":"阿拉伯语 mumiya 指沥青，尤指防腐所用的沥青，也指含有沥青的保存遗体。"},{"era":"MEDIEVAL LATIN MUMIA","en":"Medieval Latin mumia and Old French momie carried the word to Europe as a drug made from ground mummy.","cn":"中世纪拉丁 mumia 与古法语 momie 把这个词带到欧洲，指用研磨木乃伊制成的药。"},{"era":"ENGLISH BODY SENSE","en":"By the seventeenth century English mummy meant the embalmed body itself, and Egypt became its most famous source.","cn":"到 17 世纪，英语 mummy 已指防腐遗体本身，埃及则成为最著名的来源地。"},{"era":"THE MOTHER HOMONYM","en":"The nursery word mummy for mother comes from mum, a reduplicated infant sound, and is unrelated to the Arabic word.","cn":"指母亲的儿语 mummy 来自 mum，即婴儿重复的音节，与阿拉伯语词无关。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): why mummified flesh was called a wax word is not established, and the earliest English use of the body sense has no exact citation, so any earlier date offered is provisional.","cn":"来源不确定（更深词源与首见年代）：为何把防腐遗体用「蜡」词称呼，尚无定论；英语中遗体义的最早使用没有确切书证，凡给出的更早年代都是暂定的。"}]},"similar":{"note":{"en":"Group one holds words that look like mummy but belong to other roots; group two holds other ways of naming a preserved body.","cn":"第一组是与 mummy 形近却另有词源的词；第二组是其他指保存遗体的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mum","ipa":"/mʌm/","tag":"different nursery word","definition":"The short nursery word for mother; mummy is its diminutive, unrelated to the Arabic burial word.","definitionCN":"指母亲的儿语短词；mummy 是它的指小形式，与阿拉伯语埋葬词无关。"},{"word":"mumble","ipa":"/ˈmʌm.bəl/","tag":"different root","definition":"From Middle English momelen 'to speak indistinctly', probably imitative of closed lips.","definitionCN":"来自中古英语 momelen「含糊地说」，大概模仿闭唇的声音。"},{"word":"mummery","ipa":"/ˈmʌm.ər.i/","tag":"masking, not embalming","definition":"From Old French momerie 'masking, buffoonery', with a different origin and meaning.","definitionCN":"来自古法语 momerie「戴面具、滑稽表演」，来源与含义都不同。"},{"word":"mammoth","ipa":"/ˈmæm.əθ/","tag":"Russian fossil word","definition":"From Russian mamont, a name for a large extinct elephant; it looks like mummy but shares nothing.","definitionCN":"来自俄语 mamont，指已灭绝的大型象；看似与 mummy 相近，实则毫无关联。"}]},{"heading":"NEAR MEANING","entries":[{"word":"corpse","ipa":"/kɔːps/","tag":"plain word","definition":"The neutral word for a dead body, with no suggestion of preservation.","definitionCN":"指遗体的中性词，不含保存之意。"},{"word":"cadaver","ipa":"/kəˈdæv.ər/","tag":"medical word","definition":"A formal or medical word for a dead body, from Latin cadere 'to fall'.","definitionCN":"正式或医学用语，来自拉丁 cadere「倒下」。"},{"word":"embalmed body","ipa":"/ɪmˈbɑːmd ˈbɒd.i/","tag":"by treatment","definition":"A body preserved by injecting or coating with preservatives, whether or not wrapped.","definitionCN":"经注射或涂覆防腐剂保存的遗体，不论是否裹布。"},{"word":"relic","ipa":"/ˈrel.ɪk/","tag":"venerated remains","definition":"The remains or belongings of a holy person, kept for veneration.","definitionCN":"受尊崇者的遗骸或遗物，供人敬奉。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Arabic bitumen word, the linen wrappings and the unrelated mother word.","cn":"正常联想：阿拉伯语的沥青词、亚麻裹布，以及毫无关联的「妈妈」词。"},"normal":[{"en":"Arabic mumiya 'bitumen' is the source of the burial word.","cn":"阿拉伯语 mumiya「沥青」是埋葬义的来源。"},{"en":"The drug sense came before the body sense in English.","cn":"英语中药义先于遗体义出现。"},{"en":"Mummy for mother comes from mum, a nursery sound, and is unrelated.","cn":"指母亲的 mummy 来自儿语 mum，与前者无关。"},{"en":"Real compounds: mummy case, mummy cloth, mummy brown.","cn":"真实复合词：木乃伊棺匣、木乃伊裹布、木乃伊棕。"},{"en":"The plural is mummies, never mummys.","cn":"复数作 mummies，不写作 mummys。"}],"abstract":[{"en":"Picture a body wrapped so tightly that the person becomes a package.","cn":"想象一具被裹得极紧的遗体，人变成了一个包裹。"},{"en":"Picture a face dried to leather, with the eyes reduced to two hollows.","cn":"想象一张干成皮革的脸，眼睛只剩两个深窝。"},{"en":"Picture a jar of dark medicine ground from something nobody now wishes to name.","cn":"想象一罐深色药粉，研磨自如今没人愿意点名的东西。"}]},"examples":[{"en":"The museum scanned the mummy without removing the wrappings.","cn":"博物馆未拆裹布就对木乃伊做了扫描。"},{"en":"Animal mummies were kept in jars as temple offerings.","cn":"动物木乃伊被装在罐中作为神庙供品。"},{"en":"The paint was mixed with mummy brown, a pigment no longer made.","cn":"这颜料掺了木乃伊棕，一种如今不再生产的颜料。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「mummy」听似「妈咪」——裹得紧紧、像被妈妈抱住的干尸 → 木乃伊","word":"mummy"},"root":"阿拉伯语 mumiya「沥青」（源自波斯语 mum「蜡」），经中世纪拉丁 mumia、古法语 momie 入英语；先指药，后指防腐遗体。指母亲的 mummy 来自儿语 mum，同形异源。","sensesIntro":{"en":"Eight senses start from the embalmed body and its Egyptian and natural varieties, add animal mummies, then the unrelated mother word, the old bitumen drug, the gaunt-person metaphor and the pigment trade.","cn":"八个义项从防腐遗体出发，涵盖埃及与自然形成的类型，加入动物木乃伊，再转向无关的「妈妈」词、旧的沥青药、干瘪者的比喻与颜料贸易。"},"semanticMap":{"core":{"en":"CORE IMAGE: a body wrapped into a package, dried until the face becomes leather and hollows.","cn":"核心意象：一具被裹成包裹的遗体，干到脸成皮革、只剩眼窝。"},"chain":["BITUMEN","MEDICINE","EMBALMED BODY","LINEN WRAPPINGS","ANCIENT EGYPT","DRIED REMAINS"],"branches":[{"senses":"01 · 02","en":"EMBALMED BODY: the drug word settles on the bodies that supplied it, above all Egyptian ones.","cn":"防腐遗体：「药」词落到提供药的遗体上，尤以埃及者为代表。"},{"senses":"03 · 04","en":"DRYING WITHOUT RESIN: natural drying and animal burials widen the word beyond embalming.","cn":"不用树脂的干燥：自然干尸与动物墓葬把词扩展到防腐之外。"},{"senses":"05","en":"MOTHER HOMONYM: the nursery word shares spelling only.","cn":"「妈妈」同形词：儿语词只共享拼写。"},{"senses":"06 · 08","en":"MATERIAL TRADE: bitumen as medicine and ground remains as pigment both name a substance.","cn":"材料贸易：沥青作药、遗骸研磨作颜料，命名的都是物质。"},{"senses":"07","en":"DRY PERSON: the metaphor keeps dryness and stiffness, not death.","cn":"干枯的人：比喻取干燥与僵硬，而非死亡。"}]},"affixes":{"intro":{"en":"Mummy is a borrowed Arabic word, and its English family is built with Latin and Greek suffixes for making and processing.","cn":"mummy 是借入的阿拉伯语词，其英语词族用拉丁与希腊后缀构成「使成为」「处理过程」等义。"},"latinIntro":{"en":"Arabic mumiya 'bitumen' gives mummy and mummify; the Latin suffix -ficare 'to make' and -atio 'process' build the rest.","cn":"阿拉伯语 mumiya「沥青」产生 mummy 与 mummify；拉丁后缀 -ficare「使成为」与 -atio「过程」构成其余部分。"},"items":[{"word":"mum","structure":"Persian mum 'wax'","meaning":"wax; the source syllable of the Arabic word","meaningCN":"蜡；阿拉伯词的源音节","example":"Persian mum supplied the first syllable.","exampleCN":"波斯语 mum 提供了第一个音节。"},{"word":"mumiya","structure":"Arabic mumiya 'bitumen'","meaning":"bitumen; a bituminous medicine","meaningCN":"沥青；沥青药","example":"Mumiya named the substance before the body.","exampleCN":"mumiya 先指物质，后指遗体。"},{"word":"mummy","structure":"Arabic mumiya through Medieval Latin and French","meaning":"an embalmed or dried body","meaningCN":"木乃伊；干尸","example":"The mummy lay in a painted case.","exampleCN":"木乃伊躺在彩绘棺匣里。"},{"word":"mummify","structure":"mummy + -fy, from Latin -ficare 'to make'","meaning":"to preserve a body as a mummy","meaningCN":"使成木乃伊","example":"They mummified the body with resin and linen.","exampleCN":"他们用树脂与亚麻布把遗体制成木乃伊。"},{"word":"mummification","structure":"mummify + -ation, from Latin -atio","meaning":"the process of making a mummy","meaningCN":"木乃伊化；干尸制作","example":"Mummification took about seventy days.","exampleCN":"木乃伊制作约需七十天。"},{"word":"mummified","structure":"mummify + -ed","meaning":"preserved as a mummy","meaningCN":"已成干尸的","example":"The mummified hand was still wrapped.","exampleCN":"干尸的手仍被布包着。"},{"word":"mummy case","structure":"mummy + case","meaning":"the box that holds a mummy","meaningCN":"木乃伊棺匣","example":"The mummy case was painted blue.","exampleCN":"木乃伊棺匣漆成蓝色。"},{"word":"mummy cloth","structure":"mummy + cloth","meaning":"the linen wrappings of a mummy","meaningCN":"木乃伊裹布","example":"Mummy cloth was sold by the yard.","exampleCN":"木乃伊裹布曾按码出售。"},{"word":"mummy brown","structure":"mummy + brown","meaning":"a brown pigment made from mummy remains","meaningCN":"木乃伊棕","example":"Mummy brown darkened the shadows.","exampleCN":"木乃伊棕加深了阴影。"}],"latinEntries":[{"word":"mumia","structure":"mumia, mumiae (f., first declension; Medieval Latin)","meaning":"a medicinal preparation from embalmed bodies","meaningCN":"用防腐遗体制成的药"}],"derivatives":[{"word":"mummify","pos":"vt./vi.","zh":"mummy（木乃伊）+ -fy（拉丁 -ficare，使成为）→ 使成木乃伊；干尸化"},{"word":"mummification","pos":"n.","zh":"mummify（使成木乃伊）+ -ation（拉丁 -atio，过程名词）→ 木乃伊化；干尸制作"},{"word":"mummified","pos":"adj.","zh":"mummify（使成木乃伊）+ -ed（已完成的）→ 已成干尸的"},{"word":"mummy case","pos":"n.","zh":"mummy（木乃伊）+ case（箱匣）→ 木乃伊棺匣"},{"word":"mummy cloth","pos":"n.","zh":"mummy（木乃伊）+ cloth（布）→ 木乃伊裹布"},{"word":"mummy brown","pos":"n.","zh":"mummy（木乃伊）+ brown（棕色）→ 木乃伊棕（颜料）"},{"word":"mummy portrait","pos":"n.","zh":"mummy（木乃伊）+ portrait（肖像）→ 木乃伊肖像"}]}},{"word":"mummification","ipa_uk":"/ˌmʌm.ɪ.fɪˈkeɪ.ʃən/","ipa_us":"/ˌmʌm.ə.fəˈkeɪ.ʃən/","definition_zh":"木乃伊化；干尸制作；（医学）组织干性坏死","definition_en":"the process of preserving a body so that it dries and does not decay","core_image":"一具遗体被取出内脏、填进香料、裹上层层布条，再放进干燥的空气里慢慢失去水分","scene":"作坊里，工匠把香料填进遗体，再用布条一层层缠紧，最后把它放进干燥的沙室。In the workshop, embalmers filled the body with spices and wrapped it in linen, a mummification that took forty days.","sceneCN":"这里 mummification 指「使人或动物遗体干燥防腐、成为木乃伊的整套处理」（第 1 个义项：人工防腐制作）；句意为工匠用香料填充遗体、以亚麻布包裹，这套木乃伊化过程历时四十天。可辨识物件：香料罐、亚麻布、干燥室、石板台。","pos":[{"tag":"n.","zh":"木乃伊化；干尸制作；（医学）干性坏死"}],"collocations":[{"phrase":"artificial mummification","zh":"人工木乃伊化"},{"phrase":"natural mummification","zh":"自然干尸化"},{"phrase":"Egyptian mummification","zh":"埃及木乃伊制作"},{"phrase":"mummification process","zh":"干尸制作过程"},{"phrase":"dry mummification","zh":"干性坏死"},{"phrase":"mummification practices","zh":"木乃伊制作习俗"}],"forms":[{"label":"复数","form":"mummifications"},{"label":"动词（使成干尸）","form":"mummify"},{"label":"现在分词","form":"mummifying"},{"label":"过去式","form":"mummified"},{"label":"形容词（木乃伊形的）","form":"mummiform"},{"label":"相关名词（干尸制作过程）","form":"mummification process"}],"derivatives":[{"word":"mummify","pos":"vt./vi.","zh":"mummy（木乃伊）+ -fy（拉丁 -ficare，使成为）→ 使成干尸；干尸化"},{"word":"mummified","pos":"adj.","zh":"mummify（使成干尸）+ -ed（已完成的）→ 已成干尸的"},{"word":"mummiform","pos":"adj.","zh":"mummy（木乃伊）+ -form（拉丁 forma，形状）→ 木乃伊形的"},{"word":"natural mummification","pos":"n.","zh":"natural（自然的）+ mummification → 自然干尸化"},{"word":"artificial mummification","pos":"n.","zh":"artificial（人工的）+ mummification → 人工木乃伊化"},{"word":"mummification process","pos":"n.","zh":"mummification（干尸化）+ process（过程）→ 干尸制作过程"}],"senses":[{"no":"01","title":"Artificial preservation of a body","titleCN":"人工防腐制作","definition":"the deliberate treatment of a body so that it dries and resists decay","definitionCN":"有意识地处理遗体，使其干燥并抗腐坏","example":"The mummification began with the removal of the internal organs.","exampleCN":"木乃伊化从取出内脏开始。","why":"The noun names the whole process, and the process is defined by its aim rather than by one step.","whyCN":"这个名词指整套工序，而工序由目的而非某一步骤来定义。"},{"no":"02","title":"The Egyptian procedure","titleCN":"埃及式制作流程","definition":"the long Egyptian routine of drying, packing and wrapping a body","definitionCN":"埃及那套历时很长、包含干燥、填料与包裹的工序","example":"Egyptian mummification took about seventy days and involved several specialists.","exampleCN":"埃及的木乃伊制作约需七十天，要由若干专人协作。","why":"Egyptian practice is the best documented example, so the general noun often points to it by default.","whyCN":"埃及做法是文献最完整的实例，因此这个通名常默认指向它。"},{"no":"03","title":"Natural drying into a mummy","titleCN":"自然干尸化","definition":"preservation that happens without human treatment, through dry air, sand or cold","definitionCN":"未经人工处理，仅靠干燥空气、沙或寒冷形成的保存","example":"Natural mummification preserved the body in the dry cave air.","exampleCN":"自然干尸化让遗体在干燥的洞穴空气里保存下来。","why":"Because the outcome looks the same, the word covers natural processes as well as workshop ones.","whyCN":"由于结果看起来相同，这个词也涵盖自然过程，不只作坊工序。"},{"no":"04","title":"Dry gangrene in medicine","titleCN":"医学上的干性坏死","definition":"the drying and stiffening of dead tissue, especially in dry gangrene","definitionCN":"坏死组织变干变硬，尤见于干性坏疽","example":"Chronic mummification of the toe followed the loss of blood flow.","exampleCN":"血流中断之后，脚趾出现了慢性的干性坏死。","why":"Medicine borrowed the image of a dried, preserved part to describe tissue that dies and hardens.","whyCN":"医学借用了「干燥保存的部分」这一意象，用来描述坏死并变硬的组织。"},{"no":"05","title":"Preservation of an animal","titleCN":"动物木乃伊制作","definition":"the same treatment applied to a sacred or companion animal","definitionCN":"把同样的处理用于圣兽或陪伴动物","example":"Cat mummification supplied the temple with hundreds of offerings.","exampleCN":"猫的木乃伊制作曾为神庙提供数以百计的供品。","why":"The technique was applied to animals on a large scale, and the word follows the practice.","whyCN":"这套处理大规模用于动物，词也随之跟着做法走。"},{"no":"06","title":"A frozen institution, in metaphor","titleCN":"制度僵化（比喻）","definition":"the state of an organization that preserves old forms and stops changing","definitionCN":"机构保住旧形式、停止变化的状态","example":"Critics spoke of the mummification of the committee's rules.","exampleCN":"批评者谈到委员会规则的僵化封存。","why":"The metaphor keeps the idea of wrapping something so tightly that it cannot grow.","whyCN":"这个比喻保留「裹得太紧以致无法生长」的意思。"},{"no":"07","title":"A recorded burial practice","titleCN":"考古记录中的制作习俗","definition":"the set of methods recorded for a particular burial population","definitionCN":"针对某一墓葬人群所记录的一整套处理方法","example":"The survey compared mummification across three oases.","exampleCN":"这项调查比较了三处绿洲的木乃伊制作方式。","why":"Field surveys record practices rather than single bodies, which turns the word into a category of evidence.","whyCN":"田野调查记录的是做法而非单具遗体，于是这个词成了一种证据类别。"},{"no":"08","title":"The wrapping and resin routine","titleCN":"裹布与树脂工序","definition":"the specific steps of packing, coating and wrapping a body","definitionCN":"填料、涂覆与包裹遗体的具体步骤","example":"Resin was poured over the wrappings during mummification.","exampleCN":"木乃伊化过程中，树脂被浇在裹布上。","why":"When the word is used for the steps rather than the result, it focuses on resin, linen and packing.","whyCN":"当这个词指步骤而非结果时，重心就落在树脂、亚麻布与填料上。"}],"etymology":{"intro":{"en":"Mummification is an English formation from mummy plus the Latin-derived suffix of making, and the medical sense is a later metaphor. Dates are approximate.","cn":"mummification 是英语用 mummy 加拉丁来源的「使成为」后缀构成的新词，医学义是后来的比喻。年代均为约数。"},"items":[{"era":"ARABIC MUMIYA","en":"Arabic mumiya 'bitumen' reached Europe as the name of a medicinal substance and then of the preserved bodies that supplied it.","cn":"阿拉伯语 mumiya「沥青」传到欧洲，先指一种药，后指提供这种药的防腐遗体。"},{"era":"ENGLISH MUMMY","en":"English mummy named the body, and the verb mummify was formed from it on the model of Latin verbs in -ficare.","cn":"英语 mummy 指这种遗体，动词 mummify 仿照拉丁 -ficare 类动词由它构成。"},{"era":"LATIN FACERE","en":"Latin facere 'to make, do' supplied the suffix -fy, as in petrify and purify.","cn":"拉丁 facere「做、使」提供了 -fy 后缀，如 petrify 与 purify。"},{"era":"LATIN -ATIO","en":"The process noun ending -ation comes from Latin -atio, which names an action or its result.","cn":"表示过程的名词后缀 -ation 来自拉丁 -atio，指动作或其结果。"},{"era":"MEDICAL SENSE","en":"Nineteenth-century pathology applied the word to tissue that dries and hardens after losing its blood supply.","cn":"19 世纪的病理学把这个词用于失去血供后变干变硬的组织。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper root): the earliest English use of mummification is not exactly dated, and the pre-Latin root of facere is reconstructed as dhe 'to put, do', a reconstruction rather than a recorded form.","cn":"来源不确定（首见年代与更深词根）：mummification 在英语中的最早使用没有确切年代；facere 的拉丁语之前词根被重构为 dhe「放、做」，属重构形式而非有记录的形式。"}]},"similar":{"note":{"en":"Group one holds words built with the same making suffix but from other stems; group two holds other ways of keeping a body from decay.","cn":"第一组是同用「使成为」后缀、但词干各异的词；第二组是其他防止遗体腐坏的办法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"petrification","ipa":"/ˌpet.rɪ.fɪˈkeɪ.ʃən/","tag":"stone, not body","definition":"Petra 'stone' plus the same -fication; it turns wood or tissue into stone.","definitionCN":"petra「石头」加同一个 -fication；指把木头或组织变成石头。"},{"word":"putrefaction","ipa":"/ˌpjuː.trɪˈfæk.ʃən/","tag":"the opposite process","definition":"Puter 'rotten' plus the same suffix; it names decay, the very thing mummification prevents.","definitionCN":"puter「腐败」加同一后缀；指腐坏，正是木乃伊化要阻止的过程。"},{"word":"mummery","ipa":"/ˈmʌm.ər.i/","tag":"masking","definition":"From Old French momerie 'masking, buffoonery', unrelated to mummy.","definitionCN":"来自古法语 momerie「戴面具、滑稽表演」，与 mummy 无关。"},{"word":"mummiform","ipa":"/ˈmʌm.ɪ.fɔːm/","tag":"same stem, shape sense","definition":"Mummy plus -form 'shape'; it describes a coffin shaped like a wrapped body.","definitionCN":"mummy 加 -form「形状」；形容棺具做成裹尸的形状。"}]},{"heading":"NEAR MEANING","entries":[{"word":"embalming","ipa":"/ɪmˈbɑː.mɪŋ/","tag":"chemical preservation","definition":"Preservation by injecting or coating with preservatives; mummification usually adds drying.","definitionCN":"用注射或涂覆防腐剂保存；mummification 通常还包括干燥。"},{"word":"desiccation","ipa":"/ˌdes.ɪˈkeɪ.ʃən/","tag":"removal of water","definition":"The process of drying something out, which is one part of mummification.","definitionCN":"使某物干燥的过程，是木乃伊化的一环。"},{"word":"preservation","ipa":"/ˌprez.əˈveɪ.ʃən/","tag":"general word","definition":"Any keeping of an object from decay, including paper, food and tissue.","definitionCN":"任何防止物体腐坏的保存，包括纸张、食物与组织。"},{"word":"taxidermy","ipa":"/ˈtæk.sɪ.dɜː.mi/","tag":"animal skins","definition":"The mounting of animal skins for display, which keeps shape but not the body.","definitionCN":"把动物皮张装架展示，保留外形却不保留遗体。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real suffix chain -fy and -ation, the Egyptian routine and the medical metaphor.","cn":"正常联想：真实的 -fy 与 -ation 后缀链、埃及工序，以及医学比喻。"},"normal":[{"en":"mummy plus -fy gives the verb; mummify plus -ation gives the process noun.","cn":"mummy 加 -fy 构成动词；mummify 加 -ation 构成过程名词。"},{"en":"Latin facere 'to make' is the source of -fy, as in petrify.","cn":"拉丁 facere「使」是 -fy 的来源，如 petrify。"},{"en":"The Egyptian routine took about seventy days.","cn":"埃及工序约需七十天。"},{"en":"Natural mummification happens in dry caves, sand and cold air.","cn":"自然干尸化发生在干燥洞穴、沙地与寒冷空气中。"},{"en":"Dry gangrene is called mummification in medical writing.","cn":"医学写作把干性坏疽称作干性坏死。"}],"abstract":[{"en":"Picture a body packed with spice and wrapped until it becomes a sealed parcel.","cn":"想象一具遗体被填满香料、层层包裹，最终成为一个密封的包裹。"},{"en":"Picture water leaving a body so slowly that the shape stays but the softness goes.","cn":"想象水分极慢地离开遗体，形状还在，柔软却消失了。"},{"en":"Picture an institution wrapped in so many rules that it cannot move.","cn":"想象一个机构被层层规章裹住，动弹不得。"}]},"examples":[{"en":"Mummification removed moisture before decay could begin.","cn":"木乃伊化在腐坏开始前就去除了水分。"},{"en":"The museum studied natural mummification in the dry cave.","cn":"博物馆研究了干燥洞穴中的自然干尸化。"},{"en":"The report described the mummification of the old rules.","cn":"报告描述了旧规章的僵化封存。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「mummy（木乃伊）＋fication（做成）」——把人做成木乃伊 → 木乃伊化","word":"mummification"},"root":"英语由 mummy（阿拉伯语 mumiya「沥青」）加拉丁 facere「使做」衍生的 -fy，再加拉丁 -atio「过程」构成；指人工或自然的干尸化，医学引申为干性坏死。","sensesIntro":{"en":"Eight senses run from the workshop process and its Egyptian form through natural drying, medical dry gangrene, animal practice, institutional metaphor, recorded custom, and the specific wrapping routine.","cn":"八个义项从作坊工序与埃及形式出发，经过自然干燥、医学干性坏死、动物制作、制度僵化的比喻、考古记录的制作习俗，最后落在具体的裹布工序。"},"semanticMap":{"core":{"en":"CORE IMAGE: a body packed, wrapped and dried until it becomes a sealed parcel.","cn":"核心意象：一具被填料、包裹、干燥，最后成为密封包裹的遗体。"},"chain":["WET BODY","REMOVE ORGANS","SPICE AND RESIN","WRAP IN LINEN","DRY AIR","SEALED PARCEL"],"branches":[{"senses":"01 · 02","en":"WORKSHOP PROCESS: the deliberate routine and its Egyptian form are the central case.","cn":"作坊工序：有意的整套流程及其埃及形式是核心情形。"},{"senses":"03 · 08","en":"DRYING AND WRAPPING: natural drying and the resin-and-linen steps are two faces of the same aim.","cn":"干燥与包裹：自然干燥与树脂裹布是同一目的的两面。"},{"senses":"04","en":"MEDICAL IMAGE: dead tissue dries and hardens like a preserved part.","cn":"医学意象：坏死组织像被保存的部分一样变干变硬。"},{"senses":"05 · 07","en":"ANIMALS AND RECORDS: the practice extends to animals and becomes a recorded custom.","cn":"动物与记录：做法扩展到动物，并成为被记录的习俗。"},{"senses":"06","en":"FROZEN FORM: an institution wrapped so tightly that it cannot change.","cn":"凝固的形式：机构被裹得太紧，无法变化。"}]},"affixes":{"intro":{"en":"Mummification is an English compound built from a borrowed noun plus Latin making and process suffixes.","cn":"mummification 是英语复合词，由借入的名词加拉丁「使成为」与「过程」后缀构成。"},"latinIntro":{"en":"Latin facere 'to make' gives -fy and -fication; Latin -atio gives -ation, which names an action or result.","cn":"拉丁 facere「使」产生 -fy 与 -fication；拉丁 -atio 产生 -ation，指动作或结果。"},"items":[{"word":"mummy","structure":"Arabic mumiya 'bitumen' through Latin and French","meaning":"a preserved body","meaningCN":"木乃伊","example":"The mummy was wrapped in linen.","exampleCN":"木乃伊用亚麻布包裹。"},{"word":"-fy","structure":"Latin -ficare, from facere 'to make'","meaning":"to make or cause","meaningCN":"使成为","example":"Petrify and purify use the same suffix.","exampleCN":"petrify 与 purify 用同一后缀。"},{"word":"-fication","structure":"Latin -ficatio, from facere plus -atio","meaning":"the making of something","meaningCN":"造成……的过程","example":"Petrification names a making into stone.","exampleCN":"petrification 指变成石头的过程。"},{"word":"-ation","structure":"Latin -atio, action or result noun","meaning":"a process or its result","meaningCN":"过程或结果","example":"Preservation and formation both use it.","exampleCN":"preservation 与 formation 都用它。"},{"word":"mummify","structure":"mummy + -fy","meaning":"to preserve a body as a mummy","meaningCN":"使成干尸","example":"Embalmers mummified the body.","exampleCN":"防腐师把遗体制成干尸。"},{"word":"mummified","structure":"mummify + -ed","meaning":"preserved by mummification","meaningCN":"已成干尸的","example":"A mummified cat lay in the jar.","exampleCN":"罐中卧着一只干尸化的猫。"},{"word":"mummiform","structure":"mummy + -form 'shape'","meaning":"shaped like a wrapped body","meaningCN":"木乃伊形的","example":"The mummiform coffin has a carved face.","exampleCN":"这具木乃伊形棺有雕刻的面孔。"},{"word":"natural mummification","structure":"natural + mummification","meaning":"drying without human treatment","meaningCN":"自然干尸化","example":"Natural mummification kept the body intact.","exampleCN":"自然干尸化使遗体保持完整。"},{"word":"artificial mummification","structure":"artificial + mummification","meaning":"deliberate embalming and drying","meaningCN":"人工木乃伊化","example":"Artificial mummification used resin and linen.","exampleCN":"人工木乃伊化使用树脂与亚麻布。"}],"latinEntries":[{"word":"facere","structure":"facere, feci, factum (verb, third conjugation)","meaning":"to make, do","meaningCN":"做；使"},{"word":"mummificatio","structure":"mummificatio (f., third declension; New Latin)","meaning":"the making of a mummy","meaningCN":"木乃伊制作"}],"derivatives":[{"word":"mummify","pos":"vt./vi.","zh":"mummy（木乃伊）+ -fy（拉丁 -ficare，使成为）→ 使成干尸；干尸化"},{"word":"mummified","pos":"adj.","zh":"mummify（使成干尸）+ -ed（已完成的）→ 已成干尸的"},{"word":"mummiform","pos":"adj.","zh":"mummy（木乃伊）+ -form（拉丁 forma，形状）→ 木乃伊形的"},{"word":"natural mummification","pos":"n.","zh":"natural（自然的）+ mummification → 自然干尸化"},{"word":"artificial mummification","pos":"n.","zh":"artificial（人工的）+ mummification → 人工木乃伊化"},{"word":"mummification process","pos":"n.","zh":"mummification（干尸化）+ process（过程）→ 干尸制作过程"}]}},{"word":"preservation technique","ipa_uk":"/ˌprez.əˈveɪ.ʃən tekˈniːk/","ipa_us":"/ˌprez.ɚˈveɪ.ʃən tekˈniːk/","definition_zh":"保存技术；防腐与保护处理方法","definition_en":"a method used to keep an object, food or living material from decaying or being damaged","core_image":"一双戴手套的手把发黄的纸页放进恒湿柜，柜外的空气被挡在玻璃门外","scene":"修复室里，戴手套的手用一套保存技术处理发黄纸页，随后把柜门合上。In the conservation lab, gloved hands applied a preservation technique to a stack of yellowed pages before closing the cabinet.","sceneCN":"这里 preservation technique 指「防止物件腐坏受损的具体方法」（第 1 个义项：文物保存技术）；句意为修复室里戴手套的手用一套保存技术处理发黄纸页，随后合上柜门。可辨识物件：白手套、纸页、恒湿柜、温湿度表。","pos":[{"tag":"n.","zh":"保存技术；保护处理方法；防腐工艺"}],"collocations":[{"phrase":"food preservation technique","zh":"食品保存技术"},{"phrase":"digital preservation technique","zh":"数字保存技术"},{"phrase":"archival preservation technique","zh":"档案保存技术"},{"phrase":"traditional preservation technique","zh":"传统保存工艺"},{"phrase":"specimen preservation technique","zh":"标本保存技术"},{"phrase":"cold preservation technique","zh":"低温保存技术"}],"forms":[{"label":"复数","form":"preservation techniques"},{"label":"相关名词（保存）","form":"preservation"},{"label":"相关名词（防腐剂）","form":"preservative"},{"label":"相关形容词（技术的）","form":"technical"},{"label":"相关名词（技术员）","form":"technician"},{"label":"相关名词（修复实验室）","form":"preservation lab"}],"derivatives":[{"word":"preserve","pos":"vt.","zh":"拉丁 prae-（在前）+ servare（守住）经法语 → 预先护住；保存"},{"word":"preservation","pos":"n.","zh":"preserve（保存）+ -ation（拉丁 -atio，过程名词）→ 保存；保护"},{"word":"preservative","pos":"n./adj.","zh":"preserve（保存）+ -ative（拉丁 -ativus，起……作用的）→ 防腐剂；防腐的"},{"word":"technical","pos":"adj.","zh":"technique（技艺）+ -al（拉丁 -alis，形容词后缀）→ 技术的"},{"word":"technician","pos":"n.","zh":"technique（技艺）+ -ian（拉丁 -ianus，从事者）→ 技术员"},{"word":"preservationist","pos":"n.","zh":"preservation（保护）+ -ist（从事者）→ 文物保护者"},{"word":"preservation lab","pos":"n.","zh":"preservation（保存）+ lab（实验室）→ 修复实验室"}],"senses":[{"no":"01","title":"A method for relics and documents","titleCN":"文物与文献保存技术","definition":"a method used to keep fragile objects, paper or art from further damage","definitionCN":"使易损物件、纸张或艺术品不再继续损坏的方法","example":"Conservators used a low-oxygen preservation technique on the old map.","exampleCN":"修复人员对这幅旧地图采用了低氧保存技术。","why":"The phrase joins a general noun of keeping safe to a word for a practised method, so it names a repeatable procedure.","whyCN":"这个短语把泛指的「保住」与表示熟练方法的词连在一起，因此指可重复的操作程序。"},{"no":"02","title":"A method for food","titleCN":"食品保存技术","definition":"a method such as salting, drying, smoking or canning that keeps food edible","definitionCN":"腌制、干燥、熏制或罐装等使食物可久存的方法","example":"Salting was the cheapest preservation technique on the fishing coast.","exampleCN":"在渔村，盐渍是最便宜的食品保存技术。","why":"Food was the earliest domain of the phrase, because keeping food edible is a daily necessity.","whyCN":"食品是这个短语最早的领域，因为让食物不坏是日常必需。"},{"no":"03","title":"A method for biological specimens","titleCN":"生物标本保存技术","definition":"a method for fixing and storing plant or animal material for study","definitionCN":"固定并存放动植物材料以供研究的方法","example":"The herbarium adopted a drying preservation technique for its type specimens.","exampleCN":"标本馆对模式标本采用了干燥保存技术。","why":"Specimens must stay identifiable for centuries, so the method is chosen for stability rather than speed.","whyCN":"标本必须数百年仍可辨识，因此选方法时看重稳定而非速度。"},{"no":"04","title":"A method for archives","titleCN":"档案保护技术","definition":"a method for controlling light, humidity and acidity in stored records","definitionCN":"控制光照、湿度与酸度以存放档案的方法","example":"Deacidification is a standard preservation technique for nineteenth-century paper.","exampleCN":"脱酸是 19 世纪纸张的标准保存技术。","why":"Archives need the phrase because their problem is slow chemical damage rather than sudden breakage.","whyCN":"档案需要这个短语，因为其问题是缓慢的化学损伤，而非突然破损。"},{"no":"05","title":"Freeze-drying","titleCN":"冷冻干燥技术","definition":"a method that removes water from a frozen object while keeping its shape","definitionCN":"在冻结状态下除去水分、同时保持形状的方法","example":"Freeze-drying saved the waterlogged manuscripts after the flood.","exampleCN":"冷冻干燥技术救了洪水后泡水的手稿。","why":"A single method so effective that it is often named as the preservation technique for wet material.","whyCN":"这一方法极为有效，常被直接称作处理泡水材料的保存技术。"},{"no":"06","title":"A field method at a dig","titleCN":"考古现场的加固技术","definition":"a method used on site to stop excavated material from crumbling","definitionCN":"在发掘现场阻止出土材料碎裂的方法","example":"The team applied a consolidation preservation technique before lifting the mosaic.","exampleCN":"小组在起取马赛克之前先用了加固保存技术。","why":"Excavated material often fails as it dries, so the method has to be applied before the object is moved.","whyCN":"出土材料常因干燥而崩解，因此方法必须在物件移动之前施用。"},{"no":"07","title":"Digital preservation","titleCN":"数字保存技术","definition":"a method for keeping digital files readable as formats and machines change","definitionCN":"在格式与机器更替中保持数字文件可读的方法","example":"Migration is the usual preservation technique for obsolete file formats.","exampleCN":"格式迁移是应对过时文件格式的常用保存技术。","why":"The carrier decays faster than the content, so the method copies the pattern onto a fresh carrier.","whyCN":"载体的寿命短于内容，因此方法把格局复制到新的载体上。"},{"no":"08","title":"A general strategy of keeping things unchanged","titleCN":"维持原状的一般策略","definition":"any deliberate strategy that keeps a system or object in its present state","definitionCN":"任何有意让系统或物件保持现状的策略","example":"The committee treated the old rules as a preservation technique for institutional memory.","exampleCN":"委员会把旧规则当作保存机构记忆的一种办法。","why":"The abstract sense drops the physical object and keeps only the aim of preventing change.","whyCN":"抽象义丢掉实体对象，只留下「防止改变」这一目的。"}],"etymology":{"intro":{"en":"Preservation comes from Latin 'to keep before harm', while technique comes from Greek 'art, craft'; the phrase is a modern English join of the two. Dates are approximate.","cn":"preservation 来自拉丁语「在损害之前守住」，technique 来自希腊语「技艺」，这个短语是英语近代把两者拼合的结果。年代均为约数。"},"items":[{"era":"LATIN SERVARE","en":"Servare meant 'to keep, watch over, guard', and it also supplies conserve, observe and reserve.","cn":"servare 意为「看守、保存、守护」，也构成 conserve、observe 与 reserve。"},{"era":"LATIN PRAESERVARE","en":"Prae- 'before' plus servare made praeservare 'to keep safe beforehand', the direct source of preserve.","cn":"prae-「在前」加 servare 构成 praeservare「预先保住」，是 preserve 的直接来源。"},{"era":"OLD FRENCH PRESERVATION","en":"Old French preserved the Latin noun, and English preservation named the act of keeping something from harm or decay.","cn":"古法语保留了这一拉丁名词，英语 preservation 指使某物免受伤害或腐坏的动作。"},{"era":"GREEK TEKHNE","en":"Greek tekhnē meant 'art, craft, skill', and it stands behind technical, technique and technology.","cn":"希腊 tekhnē 意为「艺术、工艺、技能」，是 technical、technique 与 technology 的源头。"},{"era":"FRENCH TECHNIQUE","en":"French technique named a manner of doing something in the arts and sciences, and English adopted it in the nineteenth century.","cn":"法语 technique 指艺术与科学中的做事方式，英语在 19 世纪借入。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper roots and first date): the pre-Latin origin of servare is unsettled and tekhnē is often traced to a reconstructed root meaning 'to weave or fabricate', a reconstruction rather than a recorded form; the exact first use of the English phrase is unrecorded.","cn":"来源不确定（更深词根与首见年代）：servare 的拉丁语之前来源无定论；tekhnē 常被追溯到意为「编织、制作」的重构词根，属重构形式而非有记录的形式；这个英语短语的确切首见亦无记录。"}]},"similar":{"note":{"en":"Group one holds words that resemble preservation or technique but come from other stems; group two holds related practices with a different aim.","cn":"第一组是与 preservation、technique 形近却另有词干的词；第二组是目标不同的相关做法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"perseveration","ipa":"/pəˌsev.əˈreɪ.ʃən/","tag":"persisting, not preserving","definition":"From Latin perseverare 'to persist', built on severus 'strict'; it names repetition, not protection.","definitionCN":"来自拉丁 perseverare「坚持」，由 severus「严格」构成；指重复，不是保护。"},{"word":"prevention","ipa":"/prɪˈven.ʃən/","tag":"coming before, not keeping","definition":"From praevenire 'to come before'; it stops something from happening rather than keeping an object safe.","definitionCN":"来自 praevenire「先来」；指阻止事情发生，而非把物件保住。"},{"word":"technology","ipa":"/tekˈnɒl.ə.dʒi/","tag":"same root, different suffix","definition":"Tekhnē plus -logia 'study'; it names the study of crafts, while technique names the manner of doing.","definitionCN":"tekhnē 指技艺，-logia 指研究；technology 指技艺研究，technique 指做事方式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"conservation","ipa":"/ˌkɒn.səˈveɪ.ʃən/","tag":"careful use","definition":"Conservation stresses careful use and management, while preservation stresses keeping free from change.","definitionCN":"conservation 强调节制使用与管理，preservation 强调不使改变。"},{"word":"restoration","ipa":"/ˌres.təˈreɪ.ʃən/","tag":"putting back","definition":"Restoration aims to return an object to an earlier state, which goes beyond preservation.","definitionCN":"restoration 旨在把物件恢复到较早状态，超出了保存的范围。"},{"word":"curation","ipa":"/kjʊˈreɪ.ʃən/","tag":"selecting and caring","definition":"The work of selecting, organizing and caring for a collection.","definitionCN":"挑选、组织并照料藏品的工作。"},{"word":"storage","ipa":"/ˈstɔː.rɪdʒ/","tag":"keeping in place","definition":"The plain act of keeping something in a place, without the method's technical aim.","definitionCN":"把东西放在某处的普通行为，不含方法的技术目的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin and Greek parts and the working vocabulary of labs and archives.","cn":"正常联想：真实的拉丁与希腊成分，以及实验室与档案馆的工作词汇。"},"normal":[{"en":"Prae- 'before' plus servare 'keep' is the literal build of preserve.","cn":"prae-「在前」加 servare「守住」正是 preserve 的字面构成。"},{"en":"Greek tekhnē 'craft' is behind technique, technical and technology.","cn":"希腊 tekhnē「技艺」是 technique、technical 与 technology 的来源。"},{"en":"Real collocations: archival preservation technique, food preservation technique.","cn":"真实搭配：档案保存技术、食品保存技术。"},{"en":"Conservation manages use; preservation keeps free from change.","cn":"conservation 管理使用；preservation 使之不变。"},{"en":"Digital preservation is mostly migration from old formats.","cn":"数字保存主要是从旧格式迁移。"}],"abstract":[{"en":"Picture a gloved hand closing a glass door on a shelf of yellowed paper.","cn":"想象一只戴手套的手把玻璃门合上，里面是一排发黄的纸页。"},{"en":"Picture salt drawing water out of fish so that the fish keeps through winter.","cn":"想象盐把水分从鱼里吸出，鱼因此能过冬。"},{"en":"Picture a file being copied into a new format before the old machine dies.","cn":"想象在旧机器坏掉之前，把文件复制成新格式。"}]},"examples":[{"en":"The museum published its preservation technique for wet leather.","cn":"博物馆公布了处理湿皮革的保存技术。"},{"en":"Freeze-drying is a preservation technique for waterlogged paper.","cn":"冷冻干燥是处理泡水纸张的一种保存技术。"},{"en":"Migration remains the safest digital preservation technique.","cn":"格式迁移仍是最稳妥的数字保存技术。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pre（预先）＋serve（守住）＋technique（技巧）」——预先守住的技巧 → 保存技术","word":"preservation technique"},"root":"preservation 出拉丁 praeservare「预先保住」= prae-（在前）+ servare（看守、保存），经古法语入英语；technique 出希腊 tekhnē「技艺」，经拉丁与法语 technical 系统进入英语。","sensesIntro":{"en":"Eight senses begin with the lab method for relics, then move through food, specimens, archives, freeze-drying, field consolidation, digital migration, and finally any strategy that prevents change.","cn":"八个义项从实验室的文物方法出发，依次经过食品、标本、档案、冷冻干燥、现场加固、数字迁移，最后落到任何防止改变的办法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a gloved hand closing a stable box around something that must not change.","cn":"核心意象：一只戴手套的手把稳定的箱门合上，护住不容改变之物。"},"chain":["KEEP BEFORE HARM","STABLE BOX","REMOVE WATER","CONTROL AIR","MIGRATE FORMAT","PREVENT CHANGE"],"branches":[{"senses":"01 · 04","en":"STABLE ENVIRONMENT: relics and archives are kept by controlling light, air and acid.","cn":"稳定环境：文物与档案靠控制光、空气与酸度来保存。"},{"senses":"02 · 03","en":"REMOVE WHAT DECAYS: food and specimens are kept by drying, salting or fixing.","cn":"去掉会腐坏的部分：食品与标本靠干燥、盐渍或固定来保存。"},{"senses":"05","en":"FREEZE AND DRY: a single method rescues wet material by removing water in a frozen state.","cn":"冻住再干：一种方法在冻结状态下去水，救回泡水材料。"},{"senses":"06","en":"ON-SITE HOLD: consolidation keeps excavated material from crumbling before it is lifted.","cn":"现场固持：加固使出土材料在起取前不碎裂。"},{"senses":"07 · 08","en":"CHANGE OF CARRIER: digital migration and institutional strategy keep a pattern rather than an object.","cn":"载体的更替：数字迁移与制度策略保住的是格局而非实体。"}]},"affixes":{"intro":{"en":"The phrase combines a Latin keep-before verb with a Greek craft noun, so its word family follows both stocks.","cn":"这个短语把拉丁「预先守住」的动词与希腊「技艺」名词结合，其词族沿两条来源展开。"},"latinIntro":{"en":"Latin servare gives preserve, preservation, preservative, conserve and observe; Greek tekhnē gives technique, technical, technician and technology.","cn":"拉丁 servare 产生 preserve、preservation、preservative、conserve 与 observe；希腊 tekhnē 产生 technique、technical、technician 与 technology。"},"items":[{"word":"prae-","structure":"Latin prefix, 'before, in front'","meaning":"before","meaningCN":"在前；预先","example":"The prefix marks action taken ahead of harm.","exampleCN":"这个前缀标出在损害之前采取的行动。"},{"word":"servare","structure":"Latin verb, first conjugation","meaning":"to keep, guard","meaningCN":"看守；保存","example":"Servare is the root of preserve.","exampleCN":"servare 是 preserve 的词根。"},{"word":"preserve","structure":"prae- + servare through Old French","meaning":"to keep safe from harm","meaningCN":"预先保住；保存","example":"They preserved the fruit in sugar.","exampleCN":"他们用糖保存水果。"},{"word":"preservation","structure":"preserve + -ation","meaning":"the act of keeping safe","meaningCN":"保存；保护","example":"Preservation of paper requires stable humidity.","exampleCN":"纸张保存需要稳定湿度。"},{"word":"preservative","structure":"preserve + -ative","meaning":"a substance that keeps something from decay","meaningCN":"防腐剂","example":"Salt is an old preservative.","exampleCN":"盐是古老的防腐剂。"},{"word":"tekhnē","structure":"Greek noun, 'art, craft, skill'","meaning":"craft, skill","meaningCN":"技艺；技能","example":"Tekhne is the root of technique.","exampleCN":"tekhnē 是 technique 的词根。"},{"word":"technique","structure":"Greek tekhnē through French","meaning":"a practised manner of doing something","meaningCN":"技术；技巧","example":"The lab developed a new technique.","exampleCN":"实验室开发出一种新技术。"},{"word":"technical","structure":"tekhnē + Latin -alis","meaning":"belonging to a craft or its methods","meaningCN":"技术的","example":"The report is full of technical terms.","exampleCN":"这份报告满是技术术语。"},{"word":"technician","structure":"tekhnē + -ian 'person concerned with'","meaning":"a person skilled in a technique","meaningCN":"技术员","example":"A technician ran the scanner.","exampleCN":"一名技术员操作扫描仪。"},{"word":"technology","structure":"tekhnē + -logia 'study of'","meaning":"the study or system of crafts","meaningCN":"技术；工艺学","example":"Technology changed the storage method.","exampleCN":"技术改变了存储方式。"}],"latinEntries":[{"word":"servare","structure":"servare, servavi, servatum (verb, first conjugation)","meaning":"to keep, guard, preserve","meaningCN":"看守；保存"},{"word":"praeservare","structure":"praeservare, praeservavi, praeservatum (verb, first conjugation)","meaning":"to keep safe beforehand","meaningCN":"预先保住"},{"word":"technicus","structure":"technicus (adj., Late Latin from Greek tekhnikos)","meaning":"of a craft or art","meaningCN":"技艺的"}],"derivatives":[{"word":"preserve","pos":"vt.","zh":"拉丁 prae-（在前）+ servare（守住）经法语 → 预先护住；保存"},{"word":"preservation","pos":"n.","zh":"preserve（保存）+ -ation（拉丁 -atio，过程名词）→ 保存；保护"},{"word":"preservative","pos":"n./adj.","zh":"preserve（保存）+ -ative（拉丁 -ativus，起……作用的）→ 防腐剂；防腐的"},{"word":"technical","pos":"adj.","zh":"technique（技艺）+ -al（拉丁 -alis，形容词后缀）→ 技术的"},{"word":"technician","pos":"n.","zh":"technique（技艺）+ -ian（拉丁 -ianus，从事者）→ 技术员"},{"word":"preservationist","pos":"n.","zh":"preservation（保护）+ -ist（从事者）→ 文物保护者"},{"word":"preservation lab","pos":"n.","zh":"preservation（保存）+ lab（实验室）→ 修复实验室"}]}},{"word":"dating","ipa_uk":"/ˈdeɪ.tɪŋ/","ipa_us":"/ˈdeɪ.tɪŋ/","definition_zh":"年代测定；标注日期；约会","definition_en":"the process of establishing how old something is; also the act of marking a date or going out romantically","core_image":"一块木炭被放进仪器，屏幕上跳出一串年代数字；同一张日历上，两个人圈出周五晚上","scene":"实验室里，一块木炭被放进仪器做年代测定，屏幕跳出一串数字。In the laboratory, a piece of charcoal went into the instrument for dating, and a string of ages appeared on the screen.","sceneCN":"这里 dating 指「测定某物年代的过程」（第 1 个义项：年代测定）；句意为实验室里一块木炭被放入仪器做年代测定，屏幕上出现一串年代数据。可辨识物件：木炭样品、仪器、屏幕数字、记录表。","pos":[{"tag":"n.","zh":"年代测定；约会；日期标注"},{"tag":"v.","zh":"测定年代；标注日期；与人约会（date 的现在分词）"}],"collocations":[{"phrase":"radiocarbon dating","zh":"放射性碳测年"},{"phrase":"absolute dating","zh":"绝对年代测定"},{"phrase":"relative dating","zh":"相对年代判定"},{"phrase":"dating site","zh":"交友网站"},{"phrase":"dating method","zh":"测年方法"},{"phrase":"online dating","zh":"网络交友"}],"forms":[{"label":"复数","form":"datings"},{"label":"原形动词","form":"date"},{"label":"三单","form":"dates"},{"label":"过去式","form":"dated"},{"label":"过去分词","form":"dated"},{"label":"现在分词","form":"dating"}],"derivatives":[{"word":"dated","pos":"adj.","zh":"date（日期）+ -ed（已具备的）→ 标明日期的；过时的"},{"word":"datable","pos":"adj.","zh":"date（定年）+ -able（可……的，拉丁 -abilis）→ 可定年代的"},{"word":"undated","pos":"adj.","zh":"un-（不）+ dated（标明日期的）→ 未标日期的"},{"word":"dater","pos":"n.","zh":"date（标注日期）+ -er（施事后缀）→ 打日期戳的人或器具"},{"word":"dating technique","pos":"n.","zh":"dating（测年）+ technique（技术）→ 测年技术"},{"word":"dating method","pos":"n.","zh":"dating（测年）+ method（方法）→ 测年方法"},{"word":"radiocarbon dating","pos":"n.","zh":"radiocarbon（放射性碳）+ dating（测年）→ 放射性碳定年法"}],"senses":[{"no":"01","title":"Establishing the age of something","titleCN":"年代测定","definition":"the process of working out how old an object, event or layer is","definitionCN":"推算某件物体、某个事件或某个地层有多古老的过程","example":"Dating of the charcoal placed the fire in the ninth century.","exampleCN":"对木炭的测年把这场火定在九世纪。","why":"The noun is simply the action of the verb date in its 'assign an age' sense, so it names the procedure rather than the result.","whyCN":"这个名词就是动词 date「定年」义的动名词，命名的是程序而非结果。"},{"no":"02","title":"Radiometric methods as a group","titleCN":"放射性测年法（总称）","definition":"the family of methods that read ages from radioactive decay","definitionCN":"从放射性衰变读出年龄的一类方法","example":"Radiocarbon dating is only one branch of absolute dating.","exampleCN":"放射性碳测年只是绝对年代测定的一支。","why":"Once physics supplied clocks inside materials, 'dating' became the ordinary word for the whole family.","whyCN":"物理学在材料内部提供了时钟之后，dating 就成了这一整类方法的通名。"},{"no":"03","title":"Relative order without numbers","titleCN":"相对年代判定","definition":"placing finds in order, as lower layers are older, without giving a calendar age","definitionCN":"把出土物排出先后，如底层更早，但不给出日历年代","example":"Relative dating put the stone tools below the bronze ones.","exampleCN":"相对年代判定把石器放在青铜器之下。","why":"Ordering can be done without any clock, so the word covers sequence as well as measurement.","whyCN":"排先后不需要任何时钟，因此这个词既指测量也指排序。"},{"no":"04","title":"Marking a document with its date","titleCN":"给文件标注日期","definition":"writing the day, month and year on a letter or record","definitionCN":"在信件或记录上写下日、月与年","example":"Dating a letter correctly matters when the post is slow.","exampleCN":"邮路缓慢时，把信件的日期写对很重要。","why":"The oldest English sense comes from the practice of writing 'given at' and a day on a document.","whyCN":"最早的英语义来自在文件上写「签发于某日」的习惯。"},{"no":"05","title":"Assigning an age to an object","titleCN":"给物件定年代","definition":"estimating or deciding the period to which an object belongs","definitionCN":"估计或判定某件物品所属的时期","example":"The manuscript was dated by its handwriting rather than by its text.","exampleCN":"这份手稿是靠字迹而非内容来定年代的。","why":"Here the verb's object is the thing being placed in time, not the instrument used.","whyCN":"这里动词的宾语是被放进时间里的物件，而不是所用仪器。"},{"no":"06","title":"Going out with someone romantically","titleCN":"与人约会（社交行为）","definition":"spending time with someone in whom one has a romantic interest","definitionCN":"与有好感的人共度时光","example":"They had been dating for a year before they told their families.","exampleCN":"他们交往了一年才告诉家人。","why":"This sense grew in the nineteenth century from the older idea of an appointment or engagement.","whyCN":"这个义项在 19 世纪由较早的「约定、约见」义发展而来。"},{"no":"07","title":"A single romantic outing","titleCN":"一次约会","definition":"one occasion on which two people go out together romantically","definitionCN":"两个人以恋爱关系一起外出的一次活动","example":"Their first date was a walk along the river.","exampleCN":"他们的第一次约会是在河边散步。","why":"The countable noun names one occasion, while the activity sense names the ongoing practice.","whyCN":"可数名词指一次活动，而进行中的交往义指持续的做法。"},{"no":"08","title":"The culture of romantic meeting","titleCN":"交友风气；婚恋市场","definition":"the social world of meeting and assessing romantic partners","definitionCN":"结识与评估恋爱对象的社会场域","example":"Online dating changed the way people describe the search.","exampleCN":"网络交友改变了人们描述择偶方式的说法。","why":"The abstract use takes the practice and turns it into a social field with its own habits.","whyCN":"抽象用法把这种做法变成一个拥有自身习惯的社交场域。"}],"etymology":{"intro":{"en":"Dating goes back to Latin 'given', from the formula written on documents, and the romantic sense is a nineteenth-century extension. Dates are approximate.","cn":"dating 源自拉丁语「已给出」，来自写在文件上的套语；恋爱义则是 19 世纪的延伸。年代均为约数。"},"items":[{"era":"LATIN DARE","en":"Latin dare meant 'to give'; its neuter plural data 'things given' stands behind date and data alike.","cn":"拉丁 dare 意为「给」；其中性复数 data「已给出之物」同时是 date 与 data 的来源。"},{"era":"LATIN DATA","en":"Roman letters closed with a formula such as data Romae, 'given at Rome', followed by the day, and the word for the formula became the word for the day.","cn":"罗马书信以 data Romae「于罗马签发」之类的套语收尾，后接日期，指套语的词后来变成了指日期的词。"},{"era":"OLD FRENCH DATE","en":"Old French date named the day of a document, and English adopted it in the fourteenth century.","cn":"古法语 date 指文件上的日期，英语在 14 世纪借入。"},{"era":"ROMANTIC SENSE","en":"In the nineteenth century the word for an appointment extended to a social meeting with a romantic interest, and then to the ongoing practice.","cn":"19 世纪，指「约定」的词扩展到与心仪对象的社交会面，再扩展到持续交往。"},{"era":"SCIENTIFIC SENSE","en":"After radioactivity was discovered, 'dating' was applied to methods that read age from decay, above all radiocarbon dating from the late nineteen-forties.","cn":"放射性发现之后，dating 被用于从衰变读出年龄的方法，尤其是 40 年代后期的放射性碳测年。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates and deeper root): no exact first citation is recorded for the romantic sense or for the scientific sense, and the pre-Latin root behind dare is reconstructed as deh 'to give', a reconstruction rather than a recorded form.","cn":"来源不确定（首见年代与更深词根）：恋爱义与科学义都没有确切的最早书证；dare 之前的拉丁语词根被重构为 deh「给」，属重构形式而非有记录的形式。"}]},"similar":{"note":{"en":"Group one holds words from the same giving root with other uses; group two holds words for age, order and appointments that are not from dare.","cn":"第一组是同出「给」词根、用途不同的词；第二组是表年龄、次序与约见但并非出自 dare 的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"data","ipa":"/ˈdeɪ.tə/","tag":"same root, plural","definition":"The plural of Latin datum 'something given'; it names facts, not a day.","definitionCN":"拉丁 datum「已给出之物」的复数；指资料事实，不指日期。"},{"word":"dated","ipa":"/ˈdeɪ.tɪd/","tag":"same verb, adjective","definition":"The past participle of date, used for something marked with a date or something out of fashion.","definitionCN":"date 的过去分词，用于标明日期之物或过时之物。"},{"word":"dative","ipa":"/ˈdeɪ.tɪv/","tag":"same root, grammar","definition":"From Latin dativus, the case of the recipient, from dare 'to give'; it is a grammatical case, not a time.","definitionCN":"来自拉丁 dativus「给予格」，出自 dare「给」；这是语法格，与时间无关。"},{"word":"donation","ipa":"/dəʊˈneɪ.ʃən/","tag":"giving through a gift word","definition":"From Latin donare 'to give as a gift', related to dare through donum 'gift', but not from datum.","definitionCN":"来自拉丁 donare「赠予」，经 donum「礼物」与 dare 相关，但并非出自 datum。"}]},{"heading":"NEAR MEANING","entries":[{"word":"chronology","ipa":"/krəˈnɒl.ə.dʒi/","tag":"ordered time","definition":"The study or arrangement of events in time order, from Greek khronos 'time'.","definitionCN":"按时间顺序研究或排列事件，来自希腊 khronos「时间」。"},{"word":"age estimation","ipa":"/eɪdʒ ˌes.tɪˈmeɪ.ʃən/","tag":"guessing an age","definition":"A general phrase for estimating age, which may use no physical clock.","definitionCN":"估计年龄的泛称，可以完全不依赖物理时钟。"},{"word":"appointment","ipa":"/əˈpɔɪnt.mənt/","tag":"arranged meeting","definition":"An arranged meeting, from ad- 'to' plus punctum 'point'; it is not the source of the romantic sense.","definitionCN":"安排好的会面，来自 ad-「向」加 punctum「点」；并非恋爱义的来源。"},{"word":"courtship","ipa":"/ˈkɔːt.ʃɪp/","tag":"older word for romance","definition":"The older word for the period before marriage, with no sense of measuring age.","definitionCN":"指婚前相处阶段的较旧说法，不含量测年龄之义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin 'given' formula, the real radiometric vocabulary and the nineteenth-century social shift.","cn":"正常联想：拉丁「已给出」套语、真实的放射性测年词汇，以及 19 世纪的社会变化。"},"normal":[{"en":"Latin data Romae 'given at Rome' is the source of the document sense.","cn":"拉丁 data Romae「于罗马签发」是文件义来源。"},{"en":"The same data gives the plural noun data, meaning facts.","cn":"同一个 data 还构成指事实的复数名词 data。"},{"en":"Radiocarbon, potassium-argon and uranium-lead are all dating methods.","cn":"碳十四、钾氩与铀铅都是测年方法。"},{"en":"Relative dating needs no clock; it only orders layers.","cn":"相对年代判定不需时钟，只排地层次序。"},{"en":"The romantic sense grew out of 'appointment', not out of 'day of the month'.","cn":"恋爱义由「约定」发展而来，而非由「月内某日」发展而来。"}],"abstract":[{"en":"Picture a screen printing a number that turns a lump of charcoal into a date.","cn":"想象一块屏幕打印出一个数字，把一块木炭变成一个年代。"},{"en":"Picture a letter ending with a place and a day, so the day becomes the name of time.","cn":"想象一封信以地点与日期收尾，那个日期因此成了时间的名字。"},{"en":"Picture two calendars with one evening circled in red.","cn":"想象两本日历，同一个晚上被红笔圈出。"}]},"examples":[{"en":"The dating of the bones changed the story of the first settlement.","cn":"对骨骼的测年改写了最早定居的故事。"},{"en":"Relative dating placed the lower floor before the upper one.","cn":"相对年代判定把下层地面排在更早。"},{"en":"They met through online dating and married two years later.","cn":"他们通过网络交友认识，两年后结婚。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「date（日期）」——给东西定个日期 → 测年；和某人定个日子 → 约会","word":"dating"},"root":"拉丁 dare「给」→ 中性复数 data「已给出之物」，罗马书信套语 data Romae「于罗马签发」使 date 获得日期义，经古法语入英语；定年义为 20 世纪科学用法，恋爱义为 19 世纪由「约定」引申。","sensesIntro":{"en":"Eight senses divide into three strands: measuring age absolutely and relatively, writing or assigning dates, and the romantic practice that grew from 'appointment'.","cn":"八个义项分成三条线：绝对与相对的年代测定、日期的书写与判定，以及由「约定」发展来的恋爱交往。"},"semanticMap":{"core":{"en":"CORE IMAGE: a machine turning matter into a number, a letter ending with a day, and a calendar with an evening circled.","cn":"核心意象：一台机器把物质变成数字，一封以日期收尾的信，以及日历上被圈的夜晚。"},"chain":["GIVEN","WRITTEN DAY","DOCUMENT DATE","ORDER IN TIME","MEASURED AGE","ROMANTIC MEETING"],"branches":[{"senses":"01 · 02","en":"MEASURED AGE: physics supplies clocks, and the word names both single methods and the family.","cn":"被测出的年龄：物理学提供时钟，这个词既指单一方法也指整类。"},{"senses":"03","en":"ORDER WITHOUT CLOCK: layers can be put in sequence before any number is known.","cn":"不用时钟的次序：在任何数字之前，地层已可排序。"},{"senses":"04 · 05","en":"WRITTEN DATE: a day written on a document and a period assigned to an object share the same habit.","cn":"写下的日期：文件上的某日与物件所属的时期共享同一习惯。"},{"senses":"06 · 07","en":"SOCIAL MEETING: an appointment becomes an outing and then a practice.","cn":"社交会面：约定变成一次外出，再变成一种做法。"},{"senses":"08","en":"SOCIAL FIELD: the practice turns into a culture with its own vocabulary.","cn":"社交场域：做法变成有自己词汇的文化。"}]},"affixes":{"intro":{"en":"Dating is the noun of date, and the whole family grows from the Latin verb 'to give' plus English endings.","cn":"dating 是 date 的名词形式，整个词族由拉丁「给」动词加英语后缀生长而来。"},"latinIntro":{"en":"Latin dare gives date, datum, data and dative; the English ending -ing forms the action noun.","cn":"拉丁 dare 产生 date、datum、data 与 dative；英语后缀 -ing 构成动作名词。"},"items":[{"word":"dare","structure":"Latin verb, irregular: dare, dedi, datum","meaning":"to give","meaningCN":"给","example":"Dare is the source of date and data.","exampleCN":"dare 是 date 与 data 的来源。"},{"word":"datum","structure":"Latin datum, 'something given'","meaning":"a given fact or item","meaningCN":"给定的事实或数据项","example":"One datum supports the claim.","exampleCN":"一个数据项支持这一说法。"},{"word":"data","structure":"Latin data, plural of datum","meaning":"given facts","meaningCN":"资料；数据","example":"The data were recorded in a table.","exampleCN":"数据被记在表格里。"},{"word":"date","structure":"Latin data through Old French","meaning":"the day of the month","meaningCN":"日期","example":"The date is written at the top.","exampleCN":"日期写在顶部。"},{"word":"-ing","structure":"Old English -ung, action noun ending","meaning":"the act or process of","meaningCN":"……的动作或过程","example":"Dating names the action of dating.","exampleCN":"dating 指定年这一动作。"},{"word":"dated","structure":"date + -ed","meaning":"marked with a date; old-fashioned","meaningCN":"标明日期的；过时的","example":"The letter is dated May first.","exampleCN":"这封信标着五月一日。"},{"word":"datable","structure":"date + -able","meaning":"able to be given a date","meaningCN":"可定年代的","example":"The pottery is datable to the third century.","exampleCN":"这件陶器可定到三世纪。"},{"word":"undated","structure":"un- + dated","meaning":"with no date written","meaningCN":"未标日期的","example":"An undated photo hung on the wall.","exampleCN":"墙上挂着一张未标日期的照片。"},{"word":"dative","structure":"Latin dativus, from dare 'to give'","meaning":"the case of the recipient","meaningCN":"与格；给予格","example":"The dative marks who receives.","exampleCN":"与格标出接受者。"}],"latinEntries":[{"word":"dare","structure":"dare, dedi, datum (verb, irregular)","meaning":"to give","meaningCN":"给"},{"word":"datum","structure":"datum, dati (n., second declension)","meaning":"something given","meaningCN":"已给出之物"},{"word":"data","structure":"data (n., plural of datum)","meaning":"things given","meaningCN":"已给出之物（复数）"}],"derivatives":[{"word":"dated","pos":"adj.","zh":"date（日期）+ -ed（已具备的）→ 标明日期的；过时的"},{"word":"datable","pos":"adj.","zh":"date（定年）+ -able（可……的，拉丁 -abilis）→ 可定年代的"},{"word":"undated","pos":"adj.","zh":"un-（不）+ dated（标明日期的）→ 未标日期的"},{"word":"dater","pos":"n.","zh":"date（标注日期）+ -er（施事后缀）→ 打日期戳的人或器具"},{"word":"dating technique","pos":"n.","zh":"dating（测年）+ technique（技术）→ 测年技术"},{"word":"dating method","pos":"n.","zh":"dating（测年）+ method（方法）→ 测年方法"},{"word":"radiocarbon dating","pos":"n.","zh":"radiocarbon（放射性碳）+ dating（测年）→ 放射性碳定年法"}]}},{"word":"radiocarbon","ipa_uk":"/ˌreɪ.di.əʊˈkɑː.bən/","ipa_us":"/ˌreɪ.di.oʊˈkɑːr.bən/","definition_zh":"放射性碳；碳十四；放射性碳含量","definition_en":"a radioactive form of carbon, especially carbon-14, used to date organic remains","core_image":"高空云层里，宇宙射线撞上氮原子，生成一小撮会缓慢衰变的碳，随雨水落进草木与骨骼","scene":"高空云层中，宇宙射线撞上氮原子，生成会缓慢衰变的碳原子，随雨水落进草木。Cosmic rays strike nitrogen high in the atmosphere and produce radiocarbon that rains down into plants.","sceneCN":"这里 radiocarbon 指「具有放射性的碳同位素，主要是碳十四」（第 1 个义项：放射性碳）；句意为宇宙射线在高空撞击氮原子，生成随雨水落进植物的放射性碳。可辨识物件：高空云层、射线轨迹、草木、雨滴。","pos":[{"tag":"n.","zh":"放射性碳；碳十四；（口语）放射性碳测年"}],"collocations":[{"phrase":"radiocarbon dating","zh":"放射性碳测年"},{"phrase":"radiocarbon age","zh":"放射性碳年龄"},{"phrase":"radiocarbon reservoir","zh":"放射性碳储库"},{"phrase":"radiocarbon calibration","zh":"放射性碳校准"},{"phrase":"radiocarbon concentration","zh":"放射性碳浓度"},{"phrase":"atmospheric radiocarbon","zh":"大气放射性碳"}],"forms":[{"label":"复数（较少用）","form":"radiocarbons"},{"label":"定语形式","form":"radiocarbon"},{"label":"同位素名","form":"carbon-14"},{"label":"形容词（放射性碳的）","form":"radiocarbonic"},{"label":"相关形容词（放射性测量的）","form":"radiometric"},{"label":"相关名词（放射性碳年龄）","form":"radiocarbon age"}],"derivatives":[{"word":"radiocarbon dating","pos":"n.","zh":"radiocarbon（放射性碳）+ dating（测年）→ 放射性碳定年法"},{"word":"radiocarbon age","pos":"n.","zh":"radiocarbon + age（年龄）→ 放射性碳年龄"},{"word":"radiocarbon reservoir","pos":"n.","zh":"radiocarbon + reservoir（储库）→ 放射性碳储库"},{"word":"radiometric","pos":"adj.","zh":"radio-（放射）+ -metric（希腊 metron，测量）→ 放射性测量的"},{"word":"radiogenic","pos":"adj.","zh":"radio-（放射）+ -genic（希腊 -genēs，产生）→ 放射成因的"},{"word":"radiocarbon-calibrated","pos":"adj.","zh":"radiocarbon + calibrated（已校准的）→ 经放射性碳校准的"},{"word":"radiocarbonic","pos":"adj.","zh":"radiocarbon（放射性碳）+ -ic（形容词后缀）→ 放射性碳的（罕用）"}],"senses":[{"no":"01","title":"Radioactive carbon","titleCN":"放射性碳","definition":"carbon that is radioactive, especially the isotope carbon-14","definitionCN":"具有放射性的碳，尤指碳十四同位素","example":"Radiocarbon in the sample had decayed to half its original amount.","exampleCN":"样品中的放射性碳已衰变到原来的一半。","why":"The word joins the radiation prefix to the element name, so it names a kind of carbon rather than a method.","whyCN":"这个词把放射前缀与元素名连起来，命名的是碳的一种，而非方法。"},{"no":"02","title":"Carbon-14 by name","titleCN":"碳十四（专门名称）","definition":"the isotope with six protons and eight neutrons, written carbon-14","definitionCN":"含六个质子、八个中子的同位素，写作碳十四","example":"Radiocarbon is produced when cosmic rays hit nitrogen-14.","exampleCN":"宇宙射线撞击氮十四时产生放射性碳。","why":"In practice the word almost always means this one isotope, because it is the one useful for dating.","whyCN":"在实际使用中，这个词几乎总指这一种同位素，因为它正是可用于测年的那一种。"},{"no":"03","title":"Carbon made in the atmosphere","titleCN":"大气中生成的放射性碳","definition":"radiocarbon formed high in the air and mixed into the carbon cycle","definitionCN":"在高空生成、进入碳循环的放射性碳","example":"Atmospheric radiocarbon doubled during the nuclear tests of the nineteen-fifties.","exampleCN":"20 世纪 50 年代的核试验使大气放射性碳翻倍。","why":"The atmospheric source matters because it sets the baseline against which samples are compared.","whyCN":"大气来源之所以重要，是因为它构成比较样品时的基线。"},{"no":"04","title":"Carbon inside living things","titleCN":"生物体内的放射性碳","definition":"radiocarbon taken up by plants and passed along food chains","definitionCN":"被植物吸收、再沿食物链传递的放射性碳","example":"Living tissue carries radiocarbon in proportion to the air it grew in.","exampleCN":"活体组织携带的放射性碳与其生长时空气的比例相当。","why":"Because living things stop taking in new carbon at death, their radiocarbon becomes a clock.","whyCN":"由于生物死后不再摄入新的碳，其体内的放射性碳就成了时钟。"},{"no":"05","title":"The carbon measured in a sample","titleCN":"样品中用于测量的放射性碳","definition":"the residual radiocarbon in charcoal, bone or shell used for dating","definitionCN":"木炭、骨骼或贝壳中残留、用于测年的放射性碳","example":"The laboratory extracted radiocarbon from a gram of charred wood.","exampleCN":"实验室从一克炭化木材中提取了放射性碳。","why":"The word shifts from the substance in general to the portion that survives in a particular sample.","whyCN":"这个词从泛指的物质，转到某一具体样品中残留的那一部分。"},{"no":"06","title":"The decay of radiocarbon","titleCN":"放射性碳的衰变","definition":"the process by which carbon-14 turns into nitrogen-14 with a half-life of about five thousand seven hundred years","definitionCN":"碳十四以约五千七百年半衰期转变为氮十四的过程","example":"The slow decay of radiocarbon limits how far back the method can reach.","exampleCN":"放射性碳的缓慢衰变限制了这种方法能回溯多远。","why":"The decay rate is the physical fact that turns the isotope into a measurable clock.","whyCN":"衰变速率正是把这个同位素变成可测量时钟的物理事实。"},{"no":"07","title":"Radiocarbon concentration","titleCN":"放射性碳含量","definition":"the amount or activity of radiocarbon in a material, usually compared with a standard","definitionCN":"材料中放射性碳的数量或活度，通常与标准比较","example":"The radiocarbon concentration of the shell was too low to measure precisely.","exampleCN":"这枚贝壳的放射性碳含量太低，无法精确测量。","why":"Measurement works on concentration, so the word often names a quantity rather than a substance.","whyCN":"测量依据的是浓度，因此这个词常指一个量而非一种物质。"},{"no":"08","title":"Radiocarbon dating, by shorthand","titleCN":"放射性碳测年（口语简称）","definition":"the method of radiocarbon dating, named by its isotope in everyday speech","definitionCN":"日常口语中以同位素之名指放射性碳测年法","example":"The report says the bone was dated by radiocarbon.","exampleCN":"报告说这块骨头是用放射性碳测年的。","why":"Metonymy lets the substance stand for the method, though careful writing keeps the two apart.","whyCN":"转喻让物质代指方法，不过严谨的写作会把两者分开。"}],"etymology":{"intro":{"en":"Radiocarbon joins a Latin ray word to a Latin charcoal word, and its dating use comes from mid-twentieth-century physics. Dates are approximate.","cn":"radiocarbon 把拉丁语「射线」词与「炭」词连在一起，其测年用途来自 20 世纪中叶的物理学。年代均为约数。"},"items":[{"era":"LATIN RADIUS","en":"Latin radius meant 'ray, beam, spoke'; the prefix radio- was later used for radiation and for radio.","cn":"拉丁 radius 意为「射线、梁、辐条」；前缀 radio- 后来用于放射与无线电。"},{"era":"LATIN CARBO","en":"Latin carbo, carbonis meant 'charcoal, ember', and English carbon was named from it after the element was identified.","cn":"拉丁 carbo（属格 carbonis）意为「木炭、炭火」，元素被确认后英语 carbon 即由此命名。"},{"era":"CARBON-14","en":"Carbon-14 is a rare radioactive isotope of carbon, produced in the upper air by cosmic rays striking nitrogen.","cn":"碳十四是碳的一种稀少放射性同位素，由宇宙射线在高空撞击氮生成。"},{"era":"THE COMPOUND","en":"Radiocarbon was coined in the twentieth century to name radioactive carbon, with radio- meaning radioactive rather than 'ray'.","cn":"radiocarbon 是 20 世纪为指放射性碳而造的词，其中 radio- 意为「放射」而非字面的「射线」。"},{"era":"DATING USE","en":"Willard Libby's method of the late nineteen-forties made radiocarbon the best-known natural clock in archaeology.","cn":"威拉德·利比在 40 年代后期的方法，使放射性碳成为考古学中最著名的天然时钟。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first use): the compound has no single recorded coiner, and the half-life value has been refined several times, so older figures differ from the current convention.","cn":"来源不确定（首见使用）：这个复合词没有单一可考的首创者；半衰期数值也经过多次修正，较早的数字与现行惯例不同。"}]},"similar":{"note":{"en":"Group one holds words built with radio- or carbon but meaning something else; group two holds the technical names of the same isotope and its relatives.","cn":"第一组是同用 radio- 或 carbon、却另有所指的词；第二组是同一同位素及其亲属的技术名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"radium","ipa":"/ˈreɪ.di.əm/","tag":"same ray root, different element","definition":"From Latin radius 'ray'; radium is a metal, not a form of carbon.","definitionCN":"来自拉丁 radius「射线」；镭是金属，不是碳的一种形态。"},{"word":"radiograph","ipa":"/ˈreɪ.di.əʊ.ɡrɑːf/","tag":"ray picture","definition":"Radius plus Greek graphein 'to write'; it names an image made by rays.","definitionCN":"radius 加希腊 graphein「写」；指用射线形成的影像。"},{"word":"radiometric","ipa":"/ˌreɪ.di.əʊˈmet.rɪk/","tag":"measuring rays","definition":"Radio- plus metron 'measure'; it describes measurement of radiation, not carbon itself.","definitionCN":"radio- 加 metron「测量」；形容对放射性的测量，而非碳本身。"},{"word":"carbon","ipa":"/ˈkɑː.bən/","tag":"the base element","definition":"The element itself, from Latin carbo 'charcoal'; radiocarbon is one radioactive isotope of it.","definitionCN":"元素本身，来自拉丁 carbo「木炭」；radiocarbon 是其一种放射性同位素。"}]},{"heading":"NEAR MEANING","entries":[{"word":"carbon-14","ipa":"/ˈkɑː.bən fɔːˈtiːn/","tag":"technical name","definition":"The precise isotope name, preferred when the science must be unambiguous.","definitionCN":"精确的同位素名称，科学表述需明确时首选。"},{"word":"isotope","ipa":"/ˈaɪ.sə.təʊp/","tag":"family term","definition":"Any form of an element with a particular neutron number; radiocarbon is one.","definitionCN":"元素中具特定中子数的任一形式；放射性碳是其中一种。"},{"word":"radionuclide","ipa":"/ˌreɪ.di.əʊˈnjuː.klaɪd/","tag":"general term","definition":"Any radioactive nuclide, of which carbon-14 is a single example.","definitionCN":"任何放射性核素，碳十四只是其中一例。"},{"word":"cosmogenic nuclide","ipa":"/ˌkɒz.məˈdʒen.ɪk ˈnjuː.klaɪd/","tag":"how it is made","definition":"A nuclide produced by cosmic rays, the route by which natural radiocarbon forms.","definitionCN":"由宇宙射线产生的核素，正是天然放射性碳的形成途径。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two Latin elements, the cosmic-ray production and the real laboratory vocabulary.","cn":"正常联想：两个拉丁成分、宇宙射线生成过程，以及真实的实验室词汇。"},"normal":[{"en":"Latin radius 'ray' gives the radio- prefix; Latin carbo 'charcoal' gives carbon.","cn":"拉丁 radius「射线」给出 radio- 前缀；拉丁 carbo「木炭」给出 carbon。"},{"en":"Cosmic rays hit nitrogen-14, and the result is carbon-14.","cn":"宇宙射线撞击氮十四，产物是碳十四。"},{"en":"The half-life is about five thousand seven hundred years.","cn":"半衰期约为五千七百年。"},{"en":"Real compounds: radiocarbon age, radiocarbon calibration, radiocarbon reservoir.","cn":"真实复合词：放射性碳年龄、放射性碳校准、放射性碳储库。"},{"en":"Careful writing separates the isotope from the dating method named after it.","cn":"严谨写作会把同位素与以它命名的测年方法分开。"}],"abstract":[{"en":"Picture a spark in the sky turning air into a slow clock.","cn":"想象天空中一道火花把空气变成一只慢时钟。"},{"en":"Picture rain carrying that clock into leaves and bones.","cn":"想象雨水把这只时钟带进叶子与骨骼。"},{"en":"Picture a grey number falling by half, again and again, over thousands of years.","cn":"想象一个灰色数字一次次减半，持续数千年。"}]},"examples":[{"en":"Radiocarbon from the atmosphere enters plants through photosynthesis.","cn":"大气中的放射性碳通过光合作用进入植物。"},{"en":"The laboratory measured radiocarbon in the collagen of the bone.","cn":"实验室测量了骨骼胶原中的放射性碳。"},{"en":"The review compared radiocarbon with other natural clocks.","cn":"这篇综述把放射性碳与其他天然时钟做了比较。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「radio（放射）＋carbon（碳）」——会放射的碳 → 放射性碳","word":"radiocarbon"},"root":"radio- 出拉丁 radius「射线」，20 世纪转指放射；carbon 出拉丁 carbo「木炭、炭火」。radiocarbon 为 20 世纪新造词，指放射性碳，主要为碳十四。","sensesIntro":{"en":"Eight senses move from radioactive carbon and its isotope name through atmospheric and living carbon, the portion in a sample, decay, concentration, and the everyday shorthand for the dating method.","cn":"八个义项从放射性碳与其同位素名出发，经过大气与生物体内的碳、样品中的残留部分、衰变、含量，最后是日常口语中以它代指测年法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a spark in the sky making a slow clock that rains into living things.","cn":"核心意象：天空中一道火花造出一只慢时钟，随雨落进生物体内。"},"chain":["RAY","CHARCOAL","NITROGEN HIT","CARBON-14","LIVING UPTAKE","SLOW DECAY"],"branches":[{"senses":"01 · 02","en":"THE ISOTOPE: the word names radioactive carbon, above all carbon-14.","cn":"同位素：这个词指放射性碳，主要是碳十四。"},{"senses":"03 · 04","en":"FROM AIR TO LIFE: atmospheric production and plant uptake connect sky to tissue.","cn":"从空气到生命：大气生成与植物吸收把天空与组织连起来。"},{"senses":"05 · 07","en":"MEASURED PORTION: a sample's residual amount is what a laboratory actually reads.","cn":"被测部分：实验室真正读取的是样品中的残留量。"},{"senses":"06","en":"DECAY CLOCK: the half-life turns the isotope into a timekeeper.","cn":"衰变时钟：半衰期把同位素变成计时器。"},{"senses":"08","en":"NAME FOR THE METHOD: metonymy lets the isotope stand for the technique.","cn":"方法之名：转喻让同位素代指整套技术。"}]},"affixes":{"intro":{"en":"Radiocarbon is a modern compound of a Latin ray prefix and a Latin charcoal noun, and both parts build a wide technical family.","cn":"radiocarbon 是近代复合词，由拉丁「射线」前缀与「炭」名词构成，两部分都构成大量技术词。"},"latinIntro":{"en":"Latin radius gives radio-, radium and radiograph; Latin carbo gives carbon, carbonate and carboniferous.","cn":"拉丁 radius 产生 radio-、radium 与 radiograph；拉丁 carbo 产生 carbon、carbonate 与 carboniferous。"},"items":[{"word":"radius","structure":"Latin noun, 'ray, beam, spoke'","meaning":"ray, beam","meaningCN":"射线；梁；辐条","example":"Radius is the source of the radio- prefix.","exampleCN":"radius 是 radio- 前缀的来源。"},{"word":"radio-","structure":"Latin radius, modern prefix for radiation","meaning":"radiation; radioactive","meaningCN":"放射；放射性","example":"Radiocarbon uses radio- in its modern sense.","exampleCN":"radiocarbon 用的是 radio- 的现代义。"},{"word":"carbo","structure":"Latin noun, genitive carbonis, 'charcoal'","meaning":"charcoal, ember","meaningCN":"木炭；炭火","example":"Carbo named the element carbon.","exampleCN":"carbo 命名了元素碳。"},{"word":"carbon","structure":"Latin carbo through French","meaning":"the element with atomic number six","meaningCN":"碳","example":"Carbon forms the backbone of organic matter.","exampleCN":"碳构成有机物的骨架。"},{"word":"carbon-14","structure":"carbon + the mass number fourteen","meaning":"the radioactive isotope used for dating","meaningCN":"用于测年的放射性同位素碳十四","example":"Carbon-14 decays into nitrogen-14.","exampleCN":"碳十四衰变为氮十四。"},{"word":"radiocarbon","structure":"radio- + carbon","meaning":"radioactive carbon","meaningCN":"放射性碳","example":"Radiocarbon enters plants through the air.","exampleCN":"放射性碳经空气进入植物。"},{"word":"radiometric","structure":"radio- + Greek metron 'measure'","meaning":"relating to measurement of radiation","meaningCN":"放射性测量的","example":"Radiometric methods read decay.","exampleCN":"放射性测量方法读取衰变。"},{"word":"radiogenic","structure":"radio- + Greek -genes 'born of'","meaning":"produced by radioactivity","meaningCN":"放射成因的","example":"Radiogenic helium accumulates in rock.","exampleCN":"放射成因的氦在岩石中积累。"},{"word":"radiocarbon age","structure":"radiocarbon + age","meaning":"an age calculated from radiocarbon","meaningCN":"放射性碳年龄","example":"The radiocarbon age was about four thousand years.","exampleCN":"放射性碳年龄约为四千年。"}],"latinEntries":[{"word":"radius","structure":"radius, radii (m., second declension)","meaning":"ray, beam, spoke","meaningCN":"射线；梁；辐条"},{"word":"carbo","structure":"carbo, carbonis (m., third declension)","meaning":"charcoal, ember","meaningCN":"木炭；炭火"}],"derivatives":[{"word":"radiocarbon dating","pos":"n.","zh":"radiocarbon（放射性碳）+ dating（测年）→ 放射性碳定年法"},{"word":"radiocarbon age","pos":"n.","zh":"radiocarbon + age（年龄）→ 放射性碳年龄"},{"word":"radiocarbon reservoir","pos":"n.","zh":"radiocarbon + reservoir（储库）→ 放射性碳储库"},{"word":"radiometric","pos":"adj.","zh":"radio-（放射）+ -metric（希腊 metron，测量）→ 放射性测量的"},{"word":"radiogenic","pos":"adj.","zh":"radio-（放射）+ -genic（希腊 -genēs，产生）→ 放射成因的"},{"word":"radiocarbon-calibrated","pos":"adj.","zh":"radiocarbon + calibrated（已校准的）→ 经放射性碳校准的"},{"word":"radiocarbonic","pos":"adj.","zh":"radiocarbon（放射性碳）+ -ic（形容词后缀）→ 放射性碳的（罕用）"}]}},{"word":"radiocarbon dating","ipa_uk":"/ˌreɪ.di.əʊˈkɑː.bən ˈdeɪ.tɪŋ/","ipa_us":"/ˌreɪ.di.oʊˈkɑːr.bən ˈdeɪ.tɪŋ/","definition_zh":"放射性碳定年法；碳十四测年","definition_en":"a method of finding the age of organic material by measuring how much carbon-14 remains in it","core_image":"一小撮炭样被装进真空管，计数器数着还在衰变的碳原子，数字随后被换算成年代","scene":"发掘坑里，考古人员从烧焦的木梁上刮下一小撮炭样，装进小瓶送去测年。At the dig, the team scraped a little charcoal from a charred beam into a vial for radiocarbon dating.","sceneCN":"这里 radiocarbon dating 指「用放射性碳测定有机材料年代的方法」（第 1 个义项：放射性碳定年法）；句意为考古人员在发掘坑里从烧焦木梁上刮下炭样，装瓶送去做放射性碳测年。可辨识物件：炭化木梁、样品瓶、标签、发掘坑。","pos":[{"tag":"n.","zh":"放射性碳定年法；碳十四测年"}],"collocations":[{"phrase":"radiocarbon dating method","zh":"放射性碳测年法"},{"phrase":"radiocarbon dating laboratory","zh":"放射性碳测年实验室"},{"phrase":"radiocarbon dating result","zh":"放射性碳测年结果"},{"phrase":"calibrated radiocarbon dating","zh":"校准后的放射性碳测年"},{"phrase":"radiocarbon dating of bone","zh":"骨骼的放射性碳测年"},{"phrase":"radiocarbon dating range","zh":"放射性碳测年范围"}],"forms":[{"label":"复数","form":"radiocarbon datings"},{"label":"动词","form":"radiocarbon-date"},{"label":"三单","form":"radiocarbon-dates"},{"label":"过去式","form":"radiocarbon-dated"},{"label":"现在分词","form":"radiocarbon-dating"},{"label":"相关名词（放射性碳年代值）","form":"radiocarbon date"}],"derivatives":[{"word":"radiocarbon","pos":"n.","zh":"radio-（放射）+ carbon（碳）→ 用于测年的放射性碳"},{"word":"radiocarbon date","pos":"n.","zh":"radiocarbon + date（日期）→ 放射性碳年代值"},{"word":"radiometric dating","pos":"n.","zh":"radiometric（放射性测量的）+ dating（测年）→ 放射性测量定年法"},{"word":"calibrated","pos":"adj.","zh":"calibrate（校准）+ -ed（已完成的）→ 已校准的"},{"word":"calibration","pos":"n.","zh":"calibrate（校准）+ -ation（过程名词）→ 校准；校正曲线"},{"word":"AMS dating","pos":"n.","zh":"AMS（加速器质谱）+ dating（测年）→ 加速器质谱测年"},{"word":"radiocarbon-dated","pos":"adj.","zh":"radiocarbon + dated（已定年的）→ 经放射性碳定年的"},{"word":"radiocarbon dating lab","pos":"n.","zh":"radiocarbon dating + lab（实验室）→ 放射性碳测年实验室"}],"senses":[{"no":"01","title":"The method itself","titleCN":"方法总称","definition":"the technique of estimating the age of organic remains from their residual carbon-14","definitionCN":"根据残留碳十四估算有机遗存年代的技术","example":"Radiocarbon dating placed the charcoal at about four thousand years old.","exampleCN":"放射性碳测年把这批木炭定在约四千年前。","why":"The phrase joins the isotope to the act of dating, so it names a technique rather than a substance.","whyCN":"这个短语把同位素与「测年」这一动作连起来，命名的是技术而非物质。"},{"no":"02","title":"The decay clock","titleCN":"衰变计时原理","definition":"the principle that carbon-14 decays at a known rate once an organism stops taking it in","definitionCN":"生物停止摄入碳之后，碳十四按已知速率衰变的原理","example":"The principle behind radiocarbon dating is that the ratio of carbon-14 to carbon-12 falls after death.","exampleCN":"放射性碳测年的原理是：死亡之后，碳十四与碳十二的比例不断下降。","why":"The method works because death closes the intake and starts the clock.","whyCN":"方法之所以可行，是因为死亡切断了摄入，也就启动了时钟。"},{"no":"03","title":"Organic samples","titleCN":"适用的有机样品","definition":"the dating of charcoal, bone, shell, peat, wood and other once-living material","definitionCN":"对木炭、骨骼、贝壳、泥炭、木材等曾为活体的材料进行测年","example":"Radiocarbon dating of shell is complicated by the water the animal lived in.","exampleCN":"贝壳的放射性碳测年因动物所处水体而变得复杂。","why":"Only material that once exchanged carbon with the environment can carry the clock.","whyCN":"只有曾与环境交换碳的材料才带得动这只时钟。"},{"no":"04","title":"The practical age range","titleCN":"可测年代范围","definition":"the span within which enough carbon-14 survives to be measured, roughly the last fifty thousand years","definitionCN":"残留碳十四仍足以测量的时间跨度，大致为最近五万年","example":"Beyond the radiocarbon dating range, other methods must take over.","exampleCN":"超出放射性碳测年范围之外，就得改用其他方法。","why":"The half-life sets a ceiling: too little carbon-14 remains beyond that span.","whyCN":"半衰期设定了上限：超过这一跨度，残留的碳十四太少。"},{"no":"05","title":"Calibration to calendar years","titleCN":"校准为日历年代","definition":"the correction of raw radiocarbon ages using curves built from independently dated material","definitionCN":"用独立定年的材料所建曲线来校正原始放射性碳年龄","example":"Calibrated radiocarbon dating gave a calendar date two centuries later than the raw figure.","exampleCN":"校准后的放射性碳测年给出比原始数值晚两个世纪的日历年代。","why":"Atmospheric carbon-14 has not been constant, so raw ages must be corrected before they are read as calendar years.","whyCN":"大气碳十四并非恒定，因此原始年龄必须校正后才能读作日历年代。"},{"no":"06","title":"Measurement by accelerator","titleCN":"加速器质谱测定","definition":"the variant that counts carbon-14 atoms directly and so needs only milligrams of sample","definitionCN":"直接计数碳十四原子、因此只需毫克级样品的变体方法","example":"Accelerator mass spectrometry made radiocarbon dating possible on a single seed.","exampleCN":"加速器质谱使单粒种子也能做放射性碳测年。","why":"Counting atoms rather than decays shrank the sample and widened the method's reach.","whyCN":"计数原子而非衰变，缩小了样品需求，也扩大了方法的适用范围。"},{"no":"07","title":"Building a site chronology","titleCN":"建立遗址年代框架","definition":"the use of many dates to order phases of occupation at a site","definitionCN":"用多个年代数据排出遗址各阶段先后","example":"Radiocarbon dating of ten beams built a chronology for the whole village.","exampleCN":"对十根木梁的放射性碳测年建立了整个村落的年代序列。","why":"One date is a point; many dates make a framework, and that is how archaeology uses the method.","whyCN":"单个年代只是一个点，多个年代才构成框架，考古学正是这样使用该方法。"},{"no":"08","title":"Contamination and error control","titleCN":"污染与误差控制","definition":"the handling of sample contamination, reservoir effects and laboratory error","definitionCN":"处理样品污染、储库效应与实验室误差","example":"Radiocarbon dating of the bone failed because old carbon had entered the sample.","exampleCN":"这块骨骼的放射性碳测年失败，因为老碳进入了样品。","why":"A tiny amount of older carbon can move the result by centuries, so control is part of the method.","whyCN":"极少量更老的碳就能让结果移动几个世纪，因此控制是方法的一部分。"}],"etymology":{"intro":{"en":"Radiocarbon dating joins a twentieth-century isotope word to the older verb date; the method itself dates from the late nineteen-forties. Dates are approximate.","cn":"radiocarbon dating 把 20 世纪的同位素词与较早的动词 date 连在一起，方法本身形成于 40 年代后期。年代均为约数。"},"items":[{"era":"THE ISOTOPE WORD","en":"Radiocarbon was coined in the twentieth century from Latin radius 'ray' and Latin carbo 'charcoal', with radio- meaning radioactive.","cn":"radiocarbon 是 20 世纪用拉丁 radius「射线」与 carbo「木炭」造的词，其中 radio- 意为「放射」。"},{"era":"THE CLOCK IDEA","en":"Carbon-14 is produced in the air, taken up by living things, and begins to decay at death, which makes it a natural clock.","cn":"碳十四在大气中生成，被生物摄入，死亡后开始衰变，因此成为天然时钟。"},{"era":"LIBBY'S METHOD","en":"Willard Libby developed the dating method in the late nineteen-forties and received the Nobel Prize in chemistry in nineteen sixty.","cn":"威拉德·利比在 40 年代后期建立这一测年方法，并于 1960 年获诺贝尔化学奖。"},{"era":"HALF-LIFE VALUES","en":"The accepted half-life of carbon-14 is about five thousand seven hundred years, a figure refined from earlier estimates.","cn":"碳十四的公认半衰期约为五千七百年，这一数值由早期估计修正而来。"},{"era":"CALIBRATION CURVES","en":"Tree rings, corals and lake layers supplied independent ages, and calibration curves now convert raw results into calendar years.","cn":"树木年轮、珊瑚与湖底纹层提供了独立年代，校准曲线如今把原始结果换算为日历年代。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first use and constants): the exact first use of the full phrase is unrecorded, and half-life and calibration values have changed over time, so older published dates may differ from current ones.","cn":"来源不确定（首见使用与常数）：这个完整短语的最早使用没有记录；半衰期与校准数值随时间修改，因此较早发表的数据可能与现行值不同。"}]},"similar":{"note":{"en":"Group one holds names built from the same isotope or the same measuring prefix; group two holds other clocks used for the same purpose.","cn":"第一组是同用该同位素或同一测量前缀的名称；第二组是用于同一目的的其他时钟。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"radiocarbon","ipa":"/ˌreɪ.di.əʊˈkɑː.bən/","tag":"the isotope, not the method","definition":"The substance measured by the method; the phrase adds dating to name the technique.","definitionCN":"该方法所要测量的物质；短语加上 dating 才指技术。"},{"word":"radiometric dating","ipa":"/ˌreɪ.di.əʊˈmet.rɪk ˈdeɪ.tɪŋ/","tag":"umbrella term","definition":"Any dating based on radioactive decay, including potassium-argon and uranium-lead.","definitionCN":"任何依据放射性衰变的测年，包括钾氩与铀铅法。"},{"word":"thermoluminescence dating","ipa":"/ˌθɜː.mə.luː.mɪˈnes.əns ˈdeɪ.tɪŋ/","tag":"different clock","definition":"A method that reads stored energy in heated minerals and does not measure carbon.","definitionCN":"读取受热矿物中储存能量的方法，不测量碳。"},{"word":"dendrochronology","ipa":"/ˌden.drəʊ.krəˈnɒl.ə.dʒi/","tag":"tree-ring counting","definition":"Dating by counting tree rings, which also supplies calibration for radiocarbon results.","definitionCN":"靠数年轮定年，也为放射性碳结果提供校准。"}]},{"heading":"NEAR MEANING","entries":[{"word":"carbon dating","ipa":"/ˈkɑː.bən ˈdeɪ.tɪŋ/","tag":"everyday name","definition":"The common shorthand for radiocarbon dating, wider in tone and less precise in use.","definitionCN":"放射性碳测年的日常简称，语气更宽泛，使用也不够精确。"},{"word":"AMS dating","ipa":"/eɪ em es ˈdeɪ.tɪŋ/","tag":"small-sample variant","definition":"Dating by accelerator mass spectrometry, which counts atoms instead of decays.","definitionCN":"用加速器质谱测年，计数原子而非衰变。"},{"word":"absolute dating","ipa":"/ˈæb.sə.luːt ˈdeɪ.tɪŋ/","tag":"category","definition":"Any method that yields a calendar age rather than only an order.","definitionCN":"任何给出日历年代而非仅给次序的方法。"},{"word":"calibrated date","ipa":"/ˈkæl.ɪ.breɪ.tɪd deɪt/","tag":"corrected result","definition":"The calendar date obtained after correcting a raw radiocarbon age.","definitionCN":"校正原始放射性碳年龄后得到的日历年代。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real isotope, the real half-life and the working vocabulary of dating labs.","cn":"正常联想：真实的同位素、真实的半衰期，以及测年实验室的工作词汇。"},"normal":[{"en":"Carbon-14 is made in the air by cosmic rays and enters living things.","cn":"碳十四由宇宙射线在空中生成，并进入生物体。"},{"en":"Death starts the clock because intake stops.","cn":"死亡切断摄入，也就启动了时钟。"},{"en":"The half-life is about five thousand seven hundred years.","cn":"半衰期约为五千七百年。"},{"en":"Calibration curves turn raw ages into calendar years.","cn":"校准曲线把原始年龄换算为日历年代。"},{"en":"AMS counts atoms, so a single seed can be enough.","cn":"加速器质谱计数原子，因此一粒种子就够。"}],"abstract":[{"en":"Picture a sealed tube holding a gram of ash that is still ticking.","cn":"想象一只封口管里装着一克仍在滴答作响的灰。"},{"en":"Picture a calendar drawn behind a dial that always turns backwards.","cn":"想象一张日历画在一个永远向后转的刻度盘后面。"},{"en":"Picture a ruler that stops at fifty thousand years and hands over to another ruler.","cn":"想象一把在五万年处停止、交给另一把尺子的尺。"}]},"examples":[{"en":"Radiocarbon dating of the beam gave a date in the third millennium.","cn":"对木梁的放射性碳测年给出了第三千纪的年代。"},{"en":"Calibrated radiocarbon dating changed the sequence of the graves.","cn":"校准后的放射性碳测年改变了墓葬的次序。"},{"en":"Radiocarbon dating cannot reach beyond about fifty thousand years.","cn":"放射性碳测年无法回溯到约五万年以上。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「radiocarbon（放射性碳）＋dating（定日期）」——给碳定日期 → 碳十四测年","word":"radiocarbon dating"},"root":"radiocarbon 为 20 世纪新造词，由拉丁 radius「射线」与 carbo「木炭」构成；dating 出拉丁 dare「给」经 data「已给出之物」与古法语 date。方法由利比在 40 年代后期建立。","sensesIntro":{"en":"Eight senses follow the method from its name and principle through suitable samples, age range, calibration, accelerator measurement, site chronology and contamination control.","cn":"八个义项沿着方法展开：名称与原理、适用样品、年代范围、校准、加速器测定、遗址年代框架，以及污染控制。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sealed tube of ash still ticking, read against a calendar that turns backwards.","cn":"核心意象：一封装着仍在滴答的灰的管子，对照一张向后转的日历读数。"},"chain":["CARBON-14","LIVING UPTAKE","DEATH STOPS INTAKE","DECAY TICKS","COUNT ATOMS","CALENDAR DATE"],"branches":[{"senses":"01 · 02","en":"THE CLOCK: isotope plus decay rate equals a measurable age.","cn":"时钟：同位素加衰变速率等于可测年龄。"},{"senses":"03","en":"ONLY ONCE-LIVING: the sample must have exchanged carbon with the air.","cn":"只测曾活之物：样品必须曾与空气交换碳。"},{"senses":"04 · 06","en":"MEASUREMENT LIMITS: half-life sets the ceiling, and atom counting sets the sample size.","cn":"测量边界：半衰期设定上限，原子计数决定样品量。"},{"senses":"05 · 08","en":"CORRECTION: calibration and contamination control both adjust the raw number.","cn":"校正：校准与污染控制都在修正原始数字。"},{"senses":"07","en":"MANY DATES: a set of results becomes a site chronology.","cn":"多个年代：一组结果构成遗址年代序列。"}]},"affixes":{"intro":{"en":"The phrase is built from a modern isotope compound and an older dating noun, so its family spans both.","cn":"这个短语由近代同位素复合词与较早的测年名词构成，词族横跨两者。"},"latinIntro":{"en":"Latin radius gives radio-, radium and radiograph; Latin carbo gives carbon and carbon-14; Latin dare gives date and data.","cn":"拉丁 radius 产生 radio-、radium 与 radiograph；拉丁 carbo 产生 carbon 与 carbon-14；拉丁 dare 产生 date 与 data。"},"items":[{"word":"radiocarbon","structure":"radio- + carbon","meaning":"radioactive carbon, especially carbon-14","meaningCN":"放射性碳，尤指碳十四","example":"Radiocarbon is the clock of the method.","exampleCN":"放射性碳是这种方法所用的时钟。"},{"word":"carbon-14","structure":"carbon + mass number","meaning":"the isotope that decays after death","meaningCN":"死亡后衰变的同位素","example":"Carbon-14 has a half-life of about five thousand seven hundred years.","exampleCN":"碳十四的半衰期约为五千七百年。"},{"word":"dating","structure":"date + -ing","meaning":"the act of establishing an age","meaningCN":"测定年代的动作","example":"Dating of the site took two years.","exampleCN":"该遗址的测年用了两年。"},{"word":"date","structure":"Latin data through French","meaning":"a day or an assigned age","meaningCN":"日期；年代","example":"The date was corrected by calibration.","exampleCN":"年代经校准得到修正。"},{"word":"calibration","structure":"calibrate + -ation","meaning":"the correction of a raw age","meaningCN":"对原始年代的校正","example":"Calibration moved the result forward.","exampleCN":"校准把结果往后移了。"},{"word":"half-life","structure":"half + life","meaning":"the time for half a radioactive sample to decay","meaningCN":"放射性样品衰变一半所需的时间","example":"The half-life sets the useful range.","exampleCN":"半衰期决定可用范围。"},{"word":"radiometric","structure":"radio- + metron 'measure'","meaning":"relating to radiation measurement","meaningCN":"放射性测量的","example":"Radiometric dating is the wider family.","exampleCN":"放射性测量定年是更大的类别。"},{"word":"accelerator mass spectrometry","structure":"accelerator + mass + spectrometry","meaning":"a method that counts isotopes directly","meaningCN":"直接计数同位素的方法","example":"Accelerator mass spectrometry needs tiny samples.","exampleCN":"加速器质谱只需极小样品。"},{"word":"radiocarbon date","structure":"radiocarbon + date","meaning":"the age obtained from the isotope","meaningCN":"由同位素得到的年代","example":"The radiocarbon date was later calibrated.","exampleCN":"放射性碳年代随后经过校准。"}],"latinEntries":[{"word":"radius","structure":"radius, radii (m., second declension)","meaning":"ray, beam, spoke","meaningCN":"射线；梁；辐条"},{"word":"carbo","structure":"carbo, carbonis (m., third declension)","meaning":"charcoal, ember","meaningCN":"木炭；炭火"},{"word":"datum","structure":"datum, dati (n., second declension)","meaning":"something given","meaningCN":"已给出之物"}],"derivatives":[{"word":"radiocarbon","pos":"n.","zh":"radio-（放射）+ carbon（碳）→ 用于测年的放射性碳"},{"word":"radiocarbon date","pos":"n.","zh":"radiocarbon + date（日期）→ 放射性碳年代值"},{"word":"radiometric dating","pos":"n.","zh":"radiometric（放射性测量的）+ dating（测年）→ 放射性测量定年法"},{"word":"calibrated","pos":"adj.","zh":"calibrate（校准）+ -ed（已完成的）→ 已校准的"},{"word":"calibration","pos":"n.","zh":"calibrate（校准）+ -ation（过程名词）→ 校准；校正曲线"},{"word":"AMS dating","pos":"n.","zh":"AMS（加速器质谱）+ dating（测年）→ 加速器质谱测年"},{"word":"radiocarbon-dated","pos":"adj.","zh":"radiocarbon + dated（已定年的）→ 经放射性碳定年的"},{"word":"radiocarbon dating lab","pos":"n.","zh":"radiocarbon dating + lab（实验室）→ 放射性碳测年实验室"}]}},{"word":"carbon dating","ipa_uk":"/ˈkɑː.bən ˈdeɪ.tɪŋ/","ipa_us":"/ˈkɑːr.bən ˈdeɪ.tɪŋ/","definition_zh":"碳定年法；碳十四测年（通俗说法）","definition_en":"the everyday name for radiocarbon dating, or for dating by measuring carbon isotopes","core_image":"博物馆标签上写着「碳定年」，背面是实验室里一小瓶炭样的编号","scene":"展厅标签上写着这件木器经碳定年，旁边的说明牌补充了实验室编号。A label beside the wooden object explained the carbon dating, and a smaller card gave the laboratory number.","sceneCN":"这里 carbon dating 指「以碳同位素测定年代的通俗说法」（第 1 个义项：碳定年法）；句意为展签说明这件木器做过碳定年，旁边小牌给出实验室编号。可辨识物件：展签、木器、说明牌、实验室编号。","pos":[{"tag":"n.","zh":"碳定年法；碳十四测年（通俗名称）"}],"collocations":[{"phrase":"carbon dating result","zh":"碳定年结果"},{"phrase":"carbon dating method","zh":"碳定年方法"},{"phrase":"carbon dating laboratory","zh":"碳定年实验室"},{"phrase":"carbon dating of bone","zh":"骨骼碳定年"},{"phrase":"carbon dating range","zh":"碳定年范围"},{"phrase":"carbon dating calibration","zh":"碳定年校准"}],"forms":[{"label":"复数","form":"carbon datings"},{"label":"动词","form":"carbon-date"},{"label":"三单","form":"carbon-dates"},{"label":"过去式","form":"carbon-dated"},{"label":"现在分词","form":"carbon-dating"},{"label":"同义术语","form":"radiocarbon dating"}],"derivatives":[{"word":"radiocarbon dating","pos":"n.","zh":"radiocarbon（放射性碳）+ dating（测年）→ 放射性碳定年法（技术名称）"},{"word":"carbon date","pos":"n./v.","zh":"carbon（碳）+ date（日期）→ 碳定年结果；给……做碳定年"},{"word":"carbon-dated","pos":"adj.","zh":"carbon + dated（已定年的）→ 经碳定年的"},{"word":"carbon-14","pos":"n.","zh":"carbon（碳）+ 质量数 → 碳十四同位素"},{"word":"carbon dating lab","pos":"n.","zh":"carbon dating + lab（实验室）→ 碳定年实验室"}],"senses":[{"no":"01","title":"The everyday name for the method","titleCN":"通俗名称","definition":"the common name for radiocarbon dating in museums, media and classrooms","definitionCN":"博物馆、媒体与课堂里对放射性碳测年的通称","example":"The guide explained carbon dating before showing the bones.","exampleCN":"讲解员先解释了碳定年，再带大家看那些骨骼。","why":"The shorter name drops the radiation word, which makes it easier for general audiences but less exact.","whyCN":"较短的说法省去了「放射」一词，便于大众理解，却不够精确。"},{"no":"02","title":"A synonym in careful use","titleCN":"严谨语境中的同义替换","definition":"a term used interchangeably with radiocarbon dating when the carbon-14 method is clearly meant","definitionCN":"在明确指碳十四方法时可与「放射性碳定年法」互换的说法","example":"The paper uses carbon dating once in the abstract and the technical term thereafter.","exampleCN":"论文在摘要里用了一次碳定年，之后改用技术名称。","why":"Synonyms are safe only when context fixes the isotope, which careful writers ensure.","whyCN":"只有当上下文锁定同位素时同义替换才安全，严谨的作者会保证这一点。"},{"no":"03","title":"Dating organic remains","titleCN":"测定有机遗存","definition":"the dating of charcoal, bone, wood, peat and shell by their carbon","definitionCN":"以木炭、骨骼、木材、泥炭与贝壳中的碳进行测年","example":"Carbon dating of the peat layer put the fen at six thousand years.","exampleCN":"对泥炭层的碳定年把这片沼泽定在六千年前。","why":"The short name works here because the material itself makes the carbon clock obvious.","whyCN":"这里的短名之所以可用，是因为材料本身就让碳时钟不言自明。"},{"no":"04","title":"The resulting age figure","titleCN":"所得的年代数值","definition":"the age reported after the measurement, often called a carbon date","definitionCN":"测量后报告的年龄，常称作碳定年值","example":"The carbon dating was three thousand years, later corrected by calibration.","exampleCN":"碳定年结果是三千年，后来经校准修正。","why":"Metonymy lets the method's name stand for its output, as with many measuring techniques.","whyCN":"转喻让方法之名代指其产出，许多测量技术都如此。"},{"no":"05","title":"The laboratory routine, informally","titleCN":"实验室流程的通俗说法","definition":"the handling and measurement steps described in plain language","definitionCN":"用平实语言描述的取样与测量步骤","example":"The film showed carbon dating from sample scraping to counting.","exampleCN":"影片展示了从刮取样品到计数的碳定年全过程。","why":"Documentary language prefers the short name because it describes visible steps rather than physics.","whyCN":"纪录片语言偏好短名，因为它描述的是可见步骤，而非物理原理。"},{"no":"06","title":"The early method as a label","titleCN":"早期方法的通称","definition":"the name used for the method in its first decades, before calibration became standard","definitionCN":"在校准成为常规之前、方法最初几十年间的称法","example":"Early carbon dating gave dates that later calibration revised.","exampleCN":"早期的碳定年给出的年代后来被校准修正。","why":"Historical writing often keeps the old name because that is what the first reports used.","whyCN":"历史写作常用旧名，因为最早的报告就是这么写的。"},{"no":"07","title":"Calibration as part of the name","titleCN":"包含校准的说法","definition":"the practice of calling a corrected result carbon dating as well","definitionCN":"把校正后的结果同样称作碳定年的习惯","example":"The calibrated carbon dating placed the burial in the second century.","exampleCN":"校准后的碳定年把这处墓葬定在二世纪。","why":"Once correction is routine, the short name covers both raw and corrected figures.","whyCN":"一旦校正常规化，短名就同时涵盖原始数值与校正后的数值。"},{"no":"08","title":"A loose word for dating anything","titleCN":"泛指测定年代（口语）","definition":"an informal use for estimating the age of anything, sometimes without any carbon measurement","definitionCN":"口语中泛指估算任何事物的年代，有时根本未测碳","example":"The blog said they carbon dated the old fence by its nails.","exampleCN":"博客说他们靠钉子给旧栅栏做了碳定年。","why":"Looseness is the price of a short popular name, and technical writing avoids it.","whyCN":"宽松是通俗短名的代价，技术写作会避开这种用法。"}],"etymology":{"intro":{"en":"Carbon dating is a shortened form of radiocarbon dating, built from the element name and the older dating noun. Dates are approximate.","cn":"carbon dating 是 radiocarbon dating 的缩短形式，由元素名与较早的测年名词构成。年代均为约数。"},"items":[{"era":"LATIN CARBO","en":"Latin carbo, carbonis meant 'charcoal, ember'; English carbon named the element in the late eighteenth century.","cn":"拉丁 carbo（属格 carbonis）意为「木炭、炭火」；英语 carbon 在 18 世纪后期为元素命名。"},{"era":"CARBON-14","en":"Carbon-14 is the radioactive isotope that makes the clock work, produced in the air by cosmic rays.","cn":"碳十四是让时钟走动的放射性同位素，由宇宙射线在空中生成。"},{"era":"RADIOCARBON DATING","en":"The full technical name joined radiocarbon to dating when Libby's method spread in the late nineteen-forties and fifties.","cn":"利比的方法在 40 年代后期与 50 年代传播时，完整技术名称把 radiocarbon 与 dating 连在一起。"},{"era":"THE SHORT FORM","en":"Speakers shortened the phrase by dropping radio-, and carbon dating became the ordinary museum and newspaper term.","cn":"说者省去 radio- 缩短了这个短语，carbon dating 由此成为博物馆与报纸的常用词。"},{"era":"CALIBRATION ERA","en":"From the nineteen-sixties calibration curves changed raw figures into calendar years, and the short name covered both stages.","cn":"从 60 年代起，校准曲线把原始数值换算为日历年代，短名同时涵盖两个阶段。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first use and scope): the first recorded use of carbon dating is not precisely dated, and popular usage sometimes covers methods that measure no carbon at all.","cn":"来源不确定（首见使用与范围）：carbon dating 的最早记录没有确切年代；通俗用法有时会涵盖根本未测碳的方法。"}]},"similar":{"note":{"en":"Group one holds terms that look like carbon dating but name another method or another isotope; group two holds the precise names of the same method.","cn":"第一组是看似 carbon dating 却指另一方法或另一同位素的词；第二组是同一方法的精确名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"carbon copy","ipa":"/ˈkɑː.bən ˈkɒp.i/","tag":"paper, not time","definition":"A copy made with carbon paper; the word carbon here refers to the copying sheet, not the isotope.","definitionCN":"用复写纸做出的副本；这里的 carbon 指复写纸，不是同位素。"},{"word":"carbon footprint","ipa":"/ˈkɑː.bən ˈfʊt.prɪnt/","tag":"emissions","definition":"The measure of greenhouse gases released, with no sense of dating.","definitionCN":"释放温室气体的量度，与测年无关。"},{"word":"carboniferous","ipa":"/ˌkɑː.bəˈnɪf.ər.əs/","tag":"coal-bearing","definition":"From carbon plus Latin ferre 'to bear'; it names a geological period rich in coal.","definitionCN":"由 carbon 加拉丁 ferre「携带」构成；指富含煤的地质时期。"},{"word":"carbon-13","ipa":"/ˈkɑː.bən ˈθɜː.tiːn/","tag":"stable isotope","definition":"A stable isotope used in tracing, not the radioactive clock used in dating.","definitionCN":"用于示踪的稳定同位素，不是测年所用的放射性时钟。"}]},{"heading":"NEAR MEANING","entries":[{"word":"radiocarbon dating","ipa":"/ˌreɪ.di.əʊˈkɑː.bən ˈdeɪ.tɪŋ/","tag":"technical name","definition":"The precise name for the method, preferred in scientific writing.","definitionCN":"方法的精确名称，科学写作中首选。"},{"word":"carbon date","ipa":"/ˈkɑː.bən deɪt/","tag":"result noun","definition":"The age figure produced by the method, rather than the method itself.","definitionCN":"方法产出的年代数值，而非方法本身。"},{"word":"calibrated date","ipa":"/ˈkæl.ɪ.breɪ.tɪd deɪt/","tag":"corrected figure","definition":"The calendar age obtained after calibration, which the short name often leaves implicit.","definitionCN":"校准后得到的日历年代，短名常把这一层略去。"},{"word":"absolute dating","ipa":"/ˈæb.sə.luːt ˈdeɪ.tɪŋ/","tag":"wider category","definition":"The general class of methods that give a calendar age, of which carbon dating is one.","definitionCN":"给出日历年代的方法大类，carbon dating 是其中一种。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the element word, the shortened technical phrase and the museum label.","cn":"正常联想：元素词、缩短的技术短语，以及博物馆展签。"},"normal":[{"en":"Carbon is from Latin carbo 'charcoal'.","cn":"carbon 来自拉丁 carbo「木炭」。"},{"en":"Carbon dating is radiocarbon dating with radio- dropped.","cn":"carbon dating 就是省去 radio- 的 radiocarbon dating。"},{"en":"Carbon-14 is the isotope that supplies the clock.","cn":"碳十四是提供时钟的同位素。"},{"en":"Real collocations: carbon dating result, carbon dating laboratory.","cn":"真实搭配：碳定年结果、碳定年实验室。"},{"en":"Technical writing prefers the longer name.","cn":"技术写作偏好较长的名称。"}],"abstract":[{"en":"Picture a museum label that says carbon dated and leaves the physics offstage.","cn":"想象一张博物馆展签写着「经碳定年」，把物理过程留在幕后。"},{"en":"Picture a short word covering both the raw number and its correction.","cn":"想象一个短词同时覆盖原始数字与它的校正。"},{"en":"Picture a newspaper using the short name for a method it never explains.","cn":"想象报纸用一个短名指某种它从不解释的方法。"}]},"examples":[{"en":"Carbon dating put the wooden bowl in the first century.","cn":"碳定年把这只木碗定在一世纪。"},{"en":"The museum label says carbon dated but gives no laboratory.","cn":"展签写着「经碳定年」，却没有给出实验室。"},{"en":"Popular articles use carbon dating where the journal says radiocarbon dating.","cn":"通俗文章用 carbon dating，而期刊写 radiocarbon dating。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「carbon（碳）＋dating（定日期）」——给含碳的东西定日期 → 碳定年","word":"carbon dating"},"root":"carbon 出拉丁 carbo「木炭、炭火」；dating 出拉丁 dare「给」经 data 与古法语 date。carbon dating 为 radiocarbon dating 的缩短形式。","sensesIntro":{"en":"Eight senses run from the popular name and its synonym status through organic samples, the resulting age, the lab routine, the early label, calibrated use and loose metaphorical use.","cn":"八个义项从通俗名称与其同义地位出发，经过有机样品、所得年代、实验室流程、早期称法、校准用法，最后到宽松的比喻用法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a short museum label standing in front of a laboratory number.","cn":"核心意象：一张简短展签，背后是一个实验室编号。"},"chain":["CHARCOAL","CARBON-14","SHORT NAME","ORGANIC SAMPLE","AGE FIGURE","CALIBRATION"],"branches":[{"senses":"01 · 02","en":"SHORT NAME: the popular form and its careful synonym both name the same method.","cn":"短名：通俗形式与严谨同义都指同一方法。"},{"senses":"03 · 05","en":"SAMPLE AND ROUTINE: organic material and the lab steps are what the name actually covers.","cn":"样品与流程：这个名称实际涵盖有机材料与实验步骤。"},{"senses":"04 · 07","en":"AGE FIGURE: the output and its corrected version are both called carbon dating.","cn":"年代数值：产出与校正后的版本都被称作碳定年。"},{"senses":"06","en":"OLD LABEL: historical writing keeps the name used before calibration.","cn":"旧称：历史写作沿用校准之前的名称。"},{"senses":"08","en":"LOOSE USE: popular speech can stretch the name beyond any carbon measurement.","cn":"宽松用法：通俗说法可把名称伸展到根本未测碳的场合。"}]},"affixes":{"intro":{"en":"Carbon dating is a clipped compound, so its parts are the element name and the dating noun.","cn":"carbon dating 是截短的复合词，其成分是元素名与测年名词。"},"latinIntro":{"en":"Latin carbo gives carbon and carbon-14; Latin dare gives date, data and dating.","cn":"拉丁 carbo 产生 carbon 与 carbon-14；拉丁 dare 产生 date、data 与 dating。"},"items":[{"word":"carbo","structure":"Latin noun, genitive carbonis, 'charcoal'","meaning":"charcoal, ember","meaningCN":"木炭；炭火","example":"Carbo named the element.","exampleCN":"carbo 为元素命名。"},{"word":"carbon","structure":"Latin carbo through French","meaning":"the element with atomic number six","meaningCN":"碳","example":"Carbon supplies the clock in the method.","exampleCN":"碳在这种方法中提供时钟。"},{"word":"carbon-14","structure":"carbon + mass number","meaning":"the radioactive isotope used for dating","meaningCN":"用于测年的放射性同位素","example":"Carbon-14 decays after death.","exampleCN":"碳十四在死亡后衰变。"},{"word":"date","structure":"Latin data through French","meaning":"a day or an assigned age","meaningCN":"日期；年代","example":"The date came from the laboratory.","exampleCN":"年代来自实验室。"},{"word":"dating","structure":"date + -ing","meaning":"the act of establishing an age","meaningCN":"测定年代的动作","example":"Carbon dating is the short name for dating.","exampleCN":"碳定年是测年的短名。"},{"word":"carbon-date","structure":"carbon + date, as a verb","meaning":"to establish the age of something by carbon","meaningCN":"用碳给某物定年","example":"They carbon-dated the beam.","exampleCN":"他们给木梁做了碳定年。"},{"word":"carbon-dated","structure":"carbon + dated","meaning":"having been dated by carbon","meaningCN":"经碳定年的","example":"A carbon-dated bowl stood in the case.","exampleCN":"展柜里放着一只经碳定年的碗。"},{"word":"radiocarbon dating","structure":"radiocarbon + dating","meaning":"the full technical name","meaningCN":"完整技术名称","example":"Radiocarbon dating is the precise term.","exampleCN":"radiocarbon dating 是精确术语。"},{"word":"calibrated date","structure":"calibrated + date","meaning":"a corrected calendar age","meaningCN":"校正后的日历年代","example":"The calibrated date is the one to quote.","exampleCN":"应引用的是校准后的年代。"}],"latinEntries":[{"word":"carbo","structure":"carbo, carbonis (m., third declension)","meaning":"charcoal, ember","meaningCN":"木炭；炭火"},{"word":"datum","structure":"datum, dati (n., second declension)","meaning":"something given","meaningCN":"已给出之物"}],"derivatives":[{"word":"radiocarbon dating","pos":"n.","zh":"radiocarbon（放射性碳）+ dating（测年）→ 放射性碳定年法（技术名称）"},{"word":"carbon date","pos":"n./v.","zh":"carbon（碳）+ date（日期）→ 碳定年结果；给……做碳定年"},{"word":"carbon-dated","pos":"adj.","zh":"carbon + dated（已定年的）→ 经碳定年的"},{"word":"carbon-14","pos":"n.","zh":"carbon（碳）+ 质量数 → 碳十四同位素"},{"word":"carbon dating lab","pos":"n.","zh":"carbon dating + lab（实验室）→ 碳定年实验室"}]}},{"word":"primitive","ipa_uk":"/ˈprɪm.ə.tɪv/","ipa_us":"/ˈprɪm.ə.tɪv/","definition_zh":"原始的；早期的；简陋的；基本的","definition_en":"belonging to an early stage of development; simple or basic rather than advanced","core_image":"一根削尖的树枝与一块打制的石片，旁边摆着一台精密仪器，两者对照出「最初的样子」","scene":"展柜里，削尖的树枝与打制石片被标为最初阶段，旁边是一台精密仪器。A primitive toolkit of sharpened sticks and knapped stone lay beside a precision instrument.","sceneCN":"这里 primitive 指「属于最早阶段的、未加工的」（第 1 个义项：原始的、早期的）；句意为展柜里一套削尖树枝与打制石片的原始工具放在精密仪器旁边。可辨识物件：树枝、石片、展柜、仪器。","pos":[{"tag":"adj.","zh":"原始的；早期的；简陋的；基本的；原始派的"},{"tag":"n.","zh":"原始派画家；原初事物"}],"collocations":[{"phrase":"primitive tools","zh":"原始工具"},{"phrase":"primitive conditions","zh":"简陋条件"},{"phrase":"primitive society","zh":"原始社会"},{"phrase":"primitive cell","zh":"原初细胞"},{"phrase":"primitive art","zh":"原始派艺术"},{"phrase":"primitive notion","zh":"初始概念"}],"forms":[{"label":"比较级","form":"more primitive"},{"label":"最高级","form":"most primitive"},{"label":"副词","form":"primitively"},{"label":"名词（原始性）","form":"primitiveness"},{"label":"名词（原始主义）","form":"primitivism"},{"label":"名词（原始主义者）","form":"primitivist"}],"derivatives":[{"word":"primitively","pos":"adv.","zh":"primitive（原始的）+ -ly（古英语 -līce，方式副词）→ 原始地；简陋地"},{"word":"primitiveness","pos":"n.","zh":"primitive（原始的）+ -ness（古英语 -nes，性质名词）→ 原始性；简陋"},{"word":"primitivism","pos":"n.","zh":"primitive（原始的）+ -ism（拉丁 -ismus，主义）→ 原始主义"},{"word":"primitive art","pos":"n.","zh":"primitive（原始的）+ art（艺术）→ 原始派艺术"},{"word":"primitivist","pos":"n.","zh":"primitive（原始的）+ -ist（主义者）→ 原始主义者"}],"senses":[{"no":"01","title":"Belonging to the earliest stage","titleCN":"属于最早阶段的","definition":"belonging to an early stage of development, before refinement","definitionCN":"属于发展的早期阶段，尚未精细化","example":"Primitive tools were made by striking one stone against another.","exampleCN":"原始工具是把一块石头往另一块上打制而成的。","why":"The word is built on Latin primus 'first', so its core sense is simply 'of the first stage'.","whyCN":"这个词由拉丁 primus「第一」构成，核心义就是「属于第一阶段」。"},{"no":"02","title":"Simple and rough","titleCN":"简陋的；粗糙的","definition":"simple to the point of being uncomfortable or inadequate","definitionCN":"简单到令人不适或不够用的程度","example":"The camp had only primitive washing facilities.","exampleCN":"营地只有极为简陋的洗浴设施。","why":"Because early stages lack refinement, 'first' easily slides into 'rough' when applied to living conditions.","whyCN":"由于早期阶段缺少打磨，「第一」用于生活条件时很容易滑向「粗糙」。"},{"no":"03","title":"A dated word for peoples","titleCN":"未开化的（旧用法，含贬义）","definition":"an old and now discredited label for peoples considered less advanced","definitionCN":"旧时对被视为不发达民族的一种标签，如今已被否定且含贬义","example":"Nineteenth-century writers used primitive in ways that modern anthropology rejects.","exampleCN":"19 世纪作者使用 primitive 的方式，现代人类学已予否定。","why":"The label assumed a single ladder of progress, and the word inherited that assumption.","whyCN":"这个标签预设了一条单一的进步阶梯，词义也继承了这一预设。"},{"no":"04","title":"Undeveloped in biology","titleCN":"生物学上未分化的","definition":"in an early or undifferentiated form, as a cell or tissue","definitionCN":"处于早期或未分化状态，如细胞或组织","example":"The embryo's primitive streak marks the first axis of the body.","exampleCN":"胚胎的原条标出身体的第一条轴线。","why":"Biology uses 'first-stage' literally: the structure appears before its later specializations.","whyCN":"生物学把「第一阶段」用得很实：该结构出现在后来的特化之前。"},{"no":"05","title":"Taken as basic in logic","titleCN":"逻辑与数学中的初始的","definition":"accepted without definition, as a starting notion in a system","definitionCN":"在系统中作为起点而不加定义地接受","example":"Point and line are primitive notions in that geometry.","exampleCN":"在那套几何里，点与线是初始概念。","why":"A primitive notion is one you cannot derive, so the word keeps its 'first' sense exactly.","whyCN":"初始概念是无法推导的东西，因此这个词精确保留了「第一」义。"},{"no":"06","title":"Art outside the academic tradition","titleCN":"原始派艺术","definition":"art by self-taught makers or from traditions outside formal training","definitionCN":"自学作者或学院传统之外的艺术","example":"The exhibition placed primitive art beside trained portraiture.","exampleCN":"展览把原始派艺术与受过训练的人像画并置。","why":"Collectors used the word for work they saw as untrained, and the label survived in art history.","whyCN":"收藏家用这个词指他们眼中未受训练的作品，这个标签在艺术史中保留下来。"},{"no":"07","title":"A self-taught painter's style","titleCN":"自学画风","definition":"a style marked by flat perspective and strong outline","definitionCN":"以平面透视与强烈轮廓为特征的风格","example":"The primitive painter filled the canvas with flat houses and bright roofs.","exampleCN":"这位自学画家在画布上排满平面房屋和鲜艳屋顶。","why":"The style sense comes from the makers rather than the period, so a modern untrained painter can still be called primitive.","whyCN":"风格义来自作者而非年代，因此现代的自学画家仍可被称为原始派。"},{"no":"08","title":"A root word in linguistics","titleCN":"语言学中的词根词","definition":"a word that is not derived from another word in the same language","definitionCN":"在同一语言中不由别的词派生的词","example":"Hand is a primitive word, while handful is derived.","exampleCN":"「手」是词根词，而由它加后缀构成的「一把之量」是派生词。","why":"Linguistics borrows the 'first' sense: the word stands at the base of a derivational family.","whyCN":"语言学借用了「第一」义：这个词位于一个派生词族的基底。"}],"etymology":{"intro":{"en":"Primitive comes from Latin primus 'first' through the derived adjective primitivus and French. Dates are approximate.","cn":"primitive 来自拉丁 primus「第一」，经派生形容词 primitivus 与法语进入英语。年代均为约数。"},"items":[{"era":"LATIN PRIMUS","en":"Primus meant 'first'; it also gives prime, primary, primate and primal, so the family is large.","cn":"primus 意为「第一」，也产生 prime、primary、primate 与 primal，因此词族很大。"},{"era":"LATIN PRIMITIVUS","en":"Primitivus meant 'first of its kind, earliest', built from primus plus the adjective ending -ivus.","cn":"primitivus 意为「同类中最早的」，由 primus 加形容词词尾 -ivus 构成。"},{"era":"OLD FRENCH PRIMITIF","en":"Old French primitif carried the adjective into English in the fifteenth century, first in religious language.","cn":"古法语 primitif 在 15 世纪把这个形容词带入英语，最初用于宗教语言。"},{"era":"ART AND ANTHROPOLOGY","en":"From the nineteenth century the word was used for art outside academic training and for peoples judged less advanced, a use now rejected.","cn":"从 19 世纪起，这个词被用于学院训练之外的艺术，也被用于被判定为不发达的民族，后者如今已被否定。"},{"era":"TECHNICAL SENSES","en":"Biology and logic kept the literal 'first' sense: a primitive structure or notion is one that comes before the rest.","cn":"生物学与逻辑学保留了字面的「第一」义：初始结构或初始概念都先于其余部分。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper root and first date): the Indo-European root behind primus is reconstructed as per 'forward, before', a reconstruction and not a recorded form; the fifteenth-century English date is approximate.","cn":"来源不确定（更深词根与首见年代）：primus 之前的印欧词根被重构为 per「向前、在前」，属重构形式而非有记录的形式；英语 15 世纪的首见年代为约数。"}]},"similar":{"note":{"en":"Group one holds words from the same Latin 'first' root with different ranks; group two holds near meanings that describe stage or finish.","cn":"第一组是同出拉丁「第一」词根、但等级不同的词；第二组是描述阶段或完成度的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"prime","ipa":"/praɪm/","tag":"same root, rank","definition":"From Latin primus 'first'; it means first in importance or the best period, not earliest in time.","definitionCN":"来自拉丁 primus「第一」；指地位首要或全盛期，而非时间上最早。"},{"word":"primary","ipa":"/ˈpraɪ.mər.i/","tag":"same root, order","definition":"From Latin primarius 'of the first rank'; it means first in order or basic.","definitionCN":"来自拉丁 primarius「居首的」；指次序第一或基础性的。"},{"word":"primate","ipa":"/ˈpraɪ.meɪt/","tag":"same root, rank","definition":"From Latin primas 'of the first rank'; the animal order was named as the 'first' order by Linnaeus.","definitionCN":"来自拉丁 primas「居首位的」；动物目名是林奈把它列为「第一」目而来。"},{"word":"primal","ipa":"/ˈpraɪ.məl/","tag":"same root, earliest","definition":"From primus plus -al; it stresses what is earliest and most instinctive.","definitionCN":"由 primus 加 -al 构成；强调最早、最本能的部分。"}]},{"heading":"NEAR MEANING","entries":[{"word":"early","ipa":"/ˈɜː.li/","tag":"time only","definition":"Simply first in time, with no judgment about refinement.","definitionCN":"仅指时间上早，不含精细程度的判断。"},{"word":"crude","ipa":"/kruːd/","tag":"rough quality","definition":"Rough and unrefined, often implying poor workmanship rather than an early stage.","definitionCN":"粗糙未加工，常指做工差，而非发展阶段早。"},{"word":"basic","ipa":"/ˈbeɪ.sɪk/","tag":"foundation","definition":"Serving as a foundation, with no suggestion of being outdated.","definitionCN":"作为基础的，不含过时之意。"},{"word":"undeveloped","ipa":"/ˌʌn.dɪˈvel.əpt/","tag":"not grown","definition":"Not yet grown or elaborated, used of land, ideas or organisms.","definitionCN":"尚未成长或展开，用于土地、想法或生物。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real primus family and the scientific senses that keep 'first' literally.","cn":"正常联想：真实的 primus 词族，以及保留字面「第一」的科学义项。"},"normal":[{"en":"Latin primus 'first' gives prime, primary, primate and primal.","cn":"拉丁 primus「第一」产生 prime、primary、primate 与 primal。"},{"en":"The comparative is more primitive, not primitiver.","cn":"比较级是 more primitive，不写作 primitiver。"},{"en":"Biology keeps 'first' literally in primitive streak and primitive cell.","cn":"生物学在「原条」「原初细胞」中保留字面的「第一」。"},{"en":"Logic uses primitive notion for a starting idea taken without definition.","cn":"逻辑学用 primitive notion 指不加定义的初始概念。"},{"en":"The anthropological label is now avoided in careful writing.","cn":"人类学的旧标签如今在严谨写作中已被避免。"}],"abstract":[{"en":"Picture a sharpened stick lying beside a polished instrument.","cn":"想象一根削尖的树枝躺在一台光亮的仪器旁。"},{"en":"Picture a drawing with a flat sky and a bright roof, made by someone who never trained.","cn":"想象一幅天空扁平的画，屋顶鲜亮，出自从未受过训练的人之手。"},{"en":"Picture a first step on a staircase whose top you cannot yet see.","cn":"想象楼梯的第一级，顶端还看不见。"}]},"examples":[{"en":"The primitive plough was no more than a pointed branch.","cn":"原始犁不过是一根削尖的树枝。"},{"en":"The village had primitive drainage and no running water.","cn":"这个村子排水简陋，也没有自来水。"},{"en":"Point and line are primitive notions in the system.","cn":"点与线在该系统中是初始概念。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pri（第一）＋mitive」——排在第一、最早的样子 → 原始的","word":"primitive"},"root":"拉丁 primus「第一」+ 形容词词尾 -ivus 构成 primitivus「同类中最早的」，经古法语 primitif 入英语；primus 之前的印欧词根为重构形式。","sensesIntro":{"en":"Eight senses start from the literal first stage, then move to rough conditions, the discredited label for peoples, undifferentiated biology, logic that takes its starting notions without definition, art outside training, a self-taught style and a root word.","cn":"八个义项从字面的第一阶段出发，随后是简陋条件、已被否定的民族标签、未分化的生物结构、不加定义的逻辑起点、学院外的艺术、自学画风与词根词。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sharpened stick beside a precision instrument, the first step before the polished one.","cn":"核心意象：削尖树枝与精密仪器并置，光洁之前的第一级台阶。"},"chain":["FIRST","EARLY STAGE","UNREFINED","UNDIFFERENTIATED","TAKEN AS BASIC","OUTSIDE TRAINING"],"branches":[{"senses":"01 · 02","en":"FIRST STAGE: what comes earliest is also what lacks finish.","cn":"第一阶段：最先出现的也往往最缺打磨。"},{"senses":"03","en":"REJECTED LABEL: the old word for peoples rested on a false ladder.","cn":"被否定的标签：旧时对民族的称法建立在虚假的阶梯上。"},{"senses":"04 · 05","en":"LITERAL FIRST: biology and logic keep the sense of what comes before the rest.","cn":"字面的第一：生物学与逻辑学保留「先于其余」之义。"},{"senses":"06 · 07","en":"UNTAUGHT ART: makers outside training are named by their distance from the academy.","cn":"未受训的艺术：学院之外的作者以其距离学院而得名。"},{"senses":"08","en":"ROOT WORD: the base of a derivational family is 'first' again.","cn":"词根词：派生词族的基底又回到了「第一」。"}]},"affixes":{"intro":{"en":"Primitive belongs to the large Latin primus family, and its prefixes and suffixes show how 'first' branches into rank, time and foundation.","cn":"primitive 属于庞大的拉丁 primus 词族，其词缀显示「第一」如何分出等级、时间与基础三层。"},"latinIntro":{"en":"Latin primus 'first' gives primitivus, primarius, primas and primal; the English endings -ly, -ness and -ism build the rest.","cn":"拉丁 primus「第一」产生 primitivus、primarius、primas 与 primal；英语后缀 -ly、-ness 与 -ism 构成其余部分。"},"items":[{"word":"primus","structure":"Latin adjective, 'first'","meaning":"first","meaningCN":"第一","example":"Primus is the root of the whole family.","exampleCN":"primus 是整个词族的词根。"},{"word":"primitivus","structure":"primus + -ivus, 'first of its kind'","meaning":"earliest, first","meaningCN":"最早的；最初的","example":"The Latin adjective passed through French.","exampleCN":"这个拉丁形容词经法语传来。"},{"word":"-ivus","structure":"Latin adjective ending","meaning":"tending to, belonging to","meaningCN":"属于……的","example":"The ending forms primitivus.","exampleCN":"这个词尾构成 primitivus。"},{"word":"primitive","structure":"primitivus through Old French","meaning":"belonging to the earliest stage","meaningCN":"属于最早阶段的","example":"A primitive tool needs no finishing.","exampleCN":"原始工具无需精加工。"},{"word":"primitively","structure":"primitive + -ly","meaning":"in a primitive manner","meaningCN":"原始地；简陋地","example":"The room was primitively furnished.","exampleCN":"这个房间陈设简陋。"},{"word":"primitiveness","structure":"primitive + -ness","meaning":"the quality of being primitive","meaningCN":"原始性；简陋","example":"The primitiveness of the camp surprised them.","exampleCN":"营地的简陋让他们吃惊。"},{"word":"primitivism","structure":"primitive + -ism","meaning":"a movement favouring 'primitive' forms","meaningCN":"原始主义","example":"Primitivism shaped early modern painting.","exampleCN":"原始主义影响了早期现代绘画。"},{"word":"prime","structure":"Latin primus","meaning":"first in rank or the best period","meaningCN":"首要的；全盛期","example":"He was in his prime.","exampleCN":"他正当壮年。"},{"word":"primary","structure":"Latin primarius","meaning":"first in order or basic","meaningCN":"初级的；主要的","example":"Primary education comes first.","exampleCN":"初等教育排在最先。"},{"word":"primate","structure":"Latin primas 'first rank'","meaning":"the first order of mammals","meaningCN":"灵长类；首席主教","example":"The primate is our closest relative among mammals.","exampleCN":"灵长类是哺乳动物中与我们最近的亲属。"}],"latinEntries":[{"word":"primus","structure":"primus, prima, primum (adj., first and second declension)","meaning":"first","meaningCN":"第一"},{"word":"primitivus","structure":"primitivus, primitiva, primitivum (adj., first and second declension)","meaning":"first of its kind, earliest","meaningCN":"同类中最早的"}],"derivatives":[{"word":"primitively","pos":"adv.","zh":"primitive（原始的）+ -ly（古英语 -līce，方式副词）→ 原始地；简陋地"},{"word":"primitiveness","pos":"n.","zh":"primitive（原始的）+ -ness（古英语 -nes，性质名词）→ 原始性；简陋"},{"word":"primitivism","pos":"n.","zh":"primitive（原始的）+ -ism（拉丁 -ismus，主义）→ 原始主义"},{"word":"primitive art","pos":"n.","zh":"primitive（原始的）+ art（艺术）→ 原始派艺术"},{"word":"primitivist","pos":"n.","zh":"primitive（原始的）+ -ist（主义者）→ 原始主义者"}]}},{"word":"ancient settlement","ipa_uk":"/ˈeɪn.ʃənt ˈset.əl.mənt/","ipa_us":"/ˈeɪn.ʃənt ˈset.əl.mənt/","definition_zh":"古代聚落；古代定居点","definition_en":"a place where people lived together in the distant past, studied through its remains","core_image":"河谷台地上，一圈石墙围着十几座土坯房，中央有一口井，墙外是荒地","scene":"河谷台地上，一圈石墙围着十几座土坯房，中央有一口井。A low stone wall enclosed the ancient settlement, and a well stood among a dozen mud-brick houses.","sceneCN":"这里 ancient settlement 指「古代人群长期共同居住的聚落」（第 1 个义项：古代聚落）；句意为低矮石墙围着一片古代聚落，十几座土坯房中间有一口井。可辨识物件：石墙、土坯房、水井、台地。","pos":[{"tag":"n.","zh":"古代聚落；古代定居点"}],"collocations":[{"phrase":"ancient settlement site","zh":"古代聚落遗址"},{"phrase":"abandoned ancient settlement","zh":"废弃的古代聚落"},{"phrase":"ancient settlement pattern","zh":"古代聚落形态"},{"phrase":"excavate an ancient settlement","zh":"发掘古代聚落"},{"phrase":"ancient settlement mound","zh":"古代聚落土丘"},{"phrase":"ancient settlement remains","zh":"古代聚落遗存"}],"forms":[{"label":"复数","form":"ancient settlements"},{"label":"相关形容词","form":"ancient"},{"label":"相关名词（聚落）","form":"settlement"},{"label":"相关名词（定居者）","form":"settler"},{"label":"相关名词（古遗址）","form":"ancient site"},{"label":"相关名词（古代聚落土丘）","form":"ancient settlement mound"}],"derivatives":[{"word":"settlement","pos":"n.","zh":"settle（定居）+ -ment（拉丁 -mentum，结果名词）→ 聚落；定居点"},{"word":"settler","pos":"n.","zh":"settle（定居）+ -er（施事后缀）→ 定居者"},{"word":"settled","pos":"adj.","zh":"settle（安顿）+ -ed（已完成的）→ 已定居的；安定的"},{"word":"anciently","pos":"adv.","zh":"ancient（古代的）+ -ly（方式副词）→ 在古代"},{"word":"ancientness","pos":"n.","zh":"ancient（古代的）+ -ness（性质名词）→ 古老；年代久远"},{"word":"ancient site","pos":"n.","zh":"ancient（古代的）+ site（地点）→ 古遗址"},{"word":"ancient settlement mound","pos":"n.","zh":"ancient settlement + mound（土丘）→ 古代聚落土丘"}],"senses":[{"no":"01","title":"A settlement of the distant past","titleCN":"古代聚落","definition":"a place where a group lived together long ago, known mainly from its remains","definitionCN":"很久以前一群人共同居住之处，主要凭遗存得知","example":"The ancient settlement stood on a terrace above the river.","exampleCN":"这座古代聚落位于河流上方的台地上。","why":"The phrase joins an adjective of distance to a noun of dwelling, so it names a lived-in place known through remains.","whyCN":"这个短语把表示年代久远的形容词与表居住的名词连起来，指凭遗存得知的居住地。"},{"no":"02","title":"A prehistoric settlement","titleCN":"史前聚落","definition":"a settlement from before written records, dated by material remains","definitionCN":"文字记录出现之前的聚落，靠物质遗存定年","example":"Huts and hearths mark the prehistoric ancient settlement.","exampleCN":"茅屋与灶址标出了这处史前聚落。","why":"Where no texts exist, 'ancient' can reach back into prehistory, and the phrase carries no fixed date.","whyCN":"在没有文字的地方，「古代」可以一直伸进史前，这个短语也不含固定年代界限。"},{"no":"03","title":"An early farming village","titleCN":"早期农业村落","definition":"a village of the first farming communities, with houses, stores and fields","definitionCN":"最初农业社群形成的村落，有房屋、粮仓与田地","example":"Grain pits show that the ancient settlement kept surplus seed.","exampleCN":"粮坑说明这处古代聚落储存了余种。","why":"Farming tied people to one place, and the phrase often names the villages that resulted.","whyCN":"农业把人绑在一处，这个短语常指由此形成的村落。"},{"no":"04","title":"A large settlement with urban features","titleCN":"具有城市特征的较大聚落","definition":"a settlement large enough to have walls, planning or specialized quarters","definitionCN":"大到拥有城墙、规划或专门区域的聚落","example":"The ancient settlement had a wall, a well and a row of workshops.","exampleCN":"这处古代聚落有城墙、水井和一排作坊。","why":"Size and planning push the phrase from village toward town, though 'settlement' avoids claiming city status.","whyCN":"规模与规划把这个短语从村落推向城镇，不过 settlement 一词避免了宣称城市地位。"},{"no":"05","title":"An archaeological site","titleCN":"考古遗址","definition":"the excavated or surveyed place treated as a unit of research","definitionCN":"作为研究单元进行发掘或调查的地点","example":"The ancient settlement was mapped before any trench was opened.","exampleCN":"在开挖探沟之前，这处古代聚落先做了测绘。","why":"Archaeology speaks of sites rather than towns because the legal and research unit is the place itself.","whyCN":"考古学说「遗址」而不说「城镇」，因为法律与研究的单元就是这片地点本身。"},{"no":"06","title":"A chosen location for living","titleCN":"古代选址的定居点","definition":"a place selected in the past for water, defence or trade, seen as a location","definitionCN":"历史上因水源、防御或贸易而选定的地点","example":"The ancient settlement sits where two valleys meet.","exampleCN":"这处古代聚落位于两条谷地交汇处。","why":"Location is part of the meaning: the phrase often explains why people built there.","whyCN":"位置是词义的一部分：这个短语常用来说明人们为何在那里营建。"},{"no":"07","title":"The remains and layout of such a place","titleCN":"古代聚落的遗存与布局","definition":"the houses, walls, paths and stores of such a place taken together","definitionCN":"此类地点的房屋、墙体、道路与仓库的整体","example":"The ancient settlement's layout follows a single long street.","exampleCN":"这处古代聚落的布局沿着一条长街展开。","why":"Once excavated, the phrase can name the whole arrangement rather than only the spot.","whyCN":"发掘之后，这个短语可以指整套布局，而不只是那个地点。"},{"no":"08","title":"A long-established community in metaphor","titleCN":"历史悠久、沿袭旧制的社区（比喻）","definition":"a living community described as if it were very old and set in its ways","definitionCN":"被形容为年代久远、固守旧习的现实社区","example":"The firm behaves like an ancient settlement, jealous of newcomers.","exampleCN":"这家公司行事像一座古代聚落，对新来者充满戒心。","why":"The metaphor borrows age, walls and suspicion of outsiders from the literal settlement.","whyCN":"这个比喻从字面的聚落借来年岁、围墙与对外人的戒心。"}],"etymology":{"intro":{"en":"Ancient settlement joins a Latin-derived adjective of 'before' to an Old English noun of sitting down. Dates are approximate.","cn":"ancient settlement 把拉丁来源的「在前」形容词与古英语的「坐下安置」名词连在一起。年代均为约数。"},"items":[{"era":"LATIN ANTE","en":"Latin ante meant 'before, in front of'; the adjective for what belongs to former times was built on it.","cn":"拉丁 ante 意为「在前、在……之前」，指属于往昔的形容词即由它构成。"},{"era":"VULGAR LATIN ANTEANUS","en":"A spoken-Latin form reconstructed as anteanus 'belonging to before' stands behind Old French ancien.","cn":"一个被重构为 anteanus「属于以前的」的口语拉丁形式，是古法语 ancien 的前身。"},{"era":"OLD ENGLISH SETL","en":"Old English setl meant 'seat, sitting place'; the verb setlan 'to place, settle' came from it.","cn":"古英语 setl 意为「座位、坐处」；动词 setlan「安置、定居」即由此而来。"},{"era":"LATIN -MENTUM","en":"The noun ending -ment came from Latin -mentum through French, naming a result or an instrument.","cn":"名词词尾 -ment 经法语来自拉丁 -mentum，指结果或工具。"},{"era":"THE PHRASE","en":"English simply joins the two words; 'ancient settlement' is a descriptive label of modern archaeology, not an inherited phrase.","cn":"英语只是把两个词连起来；ancient settlement 是现代考古学的描述性标签，并非承袭的短语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first use and reconstruction): the Vulgar Latin form anteanus is a reconstruction marked with an asterisk in etymological writing, and the phrase has no recorded first citation.","cn":"来源不确定（首见使用与重构）：口语拉丁形式 anteanus 在词源写作中以星号标为重构；这个短语没有可考的最早书证。"}]},"similar":{"note":{"en":"Group one holds words that look like ancient or settlement but come from other stems; group two holds other names for places people lived in.","cn":"第一组是与 ancient、settlement 形近却另有词干的词；第二组是其他指人类居住处的名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"antique","ipa":"/ænˈtiːk/","tag":"old object, not old place","definition":"From Latin antiquus 'former, old', a related but separate formation; it usually describes objects.","definitionCN":"来自拉丁 antiquus「昔日的、旧的」，相关但另有构词；通常形容器物。"},{"word":"ancestor","ipa":"/ˈæn.ses.tər/","tag":"person, not place","definition":"From Latin antecessor 'one who goes before', through French; it names a forebear, not a settlement.","definitionCN":"来自拉丁 antecessor「先行者」，经法语而来；指祖先，不是聚落。"},{"word":"sediment","ipa":"/ˈsed.ɪ.ment/","tag":"sitting, not settling","definition":"From Latin sedimentum, based on sedere 'to sit'; it names material that has settled in water.","definitionCN":"来自拉丁 sedimentum，基于 sedere「坐」；指在水中沉积的物质。"},{"word":"settler","ipa":"/ˈset.lər/","tag":"a person","definition":"Settle plus -er 'one who does'; it names a person who settles, not the place.","definitionCN":"settle 加 -er「做……的人」；指定居者，而非地点。"}]},{"heading":"NEAR MEANING","entries":[{"word":"village","ipa":"/ˈvɪl.ɪdʒ/","tag":"living community","definition":"A small community and its houses, whether old or new.","definitionCN":"小社群及其房屋，不论古今。"},{"word":"hamlet","ipa":"/ˈhæm.lət/","tag":"very small group","definition":"A very small group of houses, smaller than a village.","definitionCN":"比村庄更小的几户人家。"},{"word":"colony","ipa":"/ˈkɒl.ə.ni/","tag":"planted settlement","definition":"A settlement planted by migrants, often with links to a parent state.","definitionCN":"由移民建立、常与母国相连的聚落。"},{"word":"site","ipa":"/saɪt/","tag":"place in research","definition":"A place treated as an object of study, which may hold a settlement without being one.","definitionCN":"作为研究对象的场所，可能含有聚落遗址却本身不等于聚落。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real word histories, the archaeological vocabulary and the mound image.","cn":"正常联想：两条真实的词史、考古词汇，以及土丘意象。"},"normal":[{"en":"Ancient comes from Latin ante 'before' through Old French ancien.","cn":"ancient 来自拉丁 ante「在前」，经古法语 ancien。"},{"en":"Settle comes from Old English setl 'seat' and setlan 'to place'.","cn":"settle 来自古英语 setl「座位」与 setlan「安置」。"},{"en":"-ment is Latin -mentum, naming a result.","cn":"-ment 是拉丁 -mentum，指结果。"},{"en":"Real terms: ancient settlement site, ancient settlement mound.","cn":"真实术语：古代聚落遗址、古代聚落土丘。"},{"en":"A settlement is a place, not a person; a settler is the person.","cn":"settlement 是地点，不是人；settler 才是人。"}],"abstract":[{"en":"Picture a low wall around a dozen mud houses with one well at the centre.","cn":"想象一道矮墙围住十几座土坯房，中央一口井。"},{"en":"Picture a mound in a field that is all that remains of a busy street.","cn":"想象田野里一座土丘，那是一条热闹街道的全部残留。"},{"en":"Picture a firm with old walls and a gate that watches newcomers.","cn":"想象一家公司有旧墙与一扇盯着新人的门。"}]},"examples":[{"en":"The ancient settlement was abandoned after the river changed course.","cn":"河流改道后，这处古代聚落被废弃。"},{"en":"Aerial survey revealed the plan of the ancient settlement.","cn":"航拍调查显示了这处古代聚落的平面。"},{"en":"The ancient settlement kept grain in pits lined with straw.","cn":"这处古代聚落把谷物存放在铺草的坑里。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「ancient（古代）＋settlement（定居点）」——古代人住下来的地方 → 古代聚落","word":"ancient settlement"},"root":"ancient 出拉丁 ante「在前」，经口语拉丁重构形式 anteanus 与古法语 ancien；settlement 出古英语 setl「座位」与 setlan「安置」，加拉丁 -mentum 经法语的名词词尾。","sensesIntro":{"en":"Eight senses move from a distant lived place to prehistoric and farming villages, larger planned settlements, archaeological sites, chosen locations, excavated layouts and a metaphor for an old community.","cn":"八个义项从遥远的居住地出发，经过史前村落与农业村落、较大的规划聚落、考古遗址、选址、发掘后的布局，最后是旧社区的比喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a walled group of mud houses around one well on a river terrace.","cn":"核心意象：河谷台地上一圈土坯房围着一口井，外有矮墙。"},"chain":["BEFORE","SEAT","DWELLING","WALL","REMAINS","OLD COMMUNITY"],"branches":[{"senses":"01 · 06","en":"PLACE CHOSEN: a distant dwelling place is also a location chosen for water or defence.","cn":"选定的地点：遥远的居住处同时也是因水源或防御而选的位置。"},{"senses":"02 · 03","en":"FIRST LIVING: prehistory and early farming name the earliest forms of the place.","cn":"最早的居住：史前与早期农业构成这处地点最早的形式。"},{"senses":"04","en":"TOWNWARD: size and planning push the phrase beyond a mere village.","cn":"向城而行：规模与规划把这个短语推过纯村落的界限。"},{"senses":"05 · 07","en":"RESEARCH UNIT: the site and its excavated layout are archaeology's objects.","cn":"研究单元：遗址及其发掘布局是考古学的对象。"},{"senses":"08","en":"OLD WALLS: a living community borrows age and suspicion of outsiders.","cn":"旧墙：现实社区借用了年岁与对外人的戒心。"}]},"affixes":{"intro":{"en":"The phrase combines a Latin 'before' adjective with an Old English 'seat' noun and a Latin result suffix.","cn":"这个短语把拉丁「在前」形容词、古英语「座位」名词与拉丁结果后缀合在一起。"},"latinIntro":{"en":"Latin ante gives ancient and ancestor; Old English setl gives settle, settlement and settler; Latin -mentum gives -ment.","cn":"拉丁 ante 产生 ancient 与 ancestor；古英语 setl 产生 settle、settlement 与 settler；拉丁 -mentum 产生 -ment。"},"items":[{"word":"ante","structure":"Latin preposition and prefix, 'before'","meaning":"before, in front of","meaningCN":"在前；在……之前","example":"Ante is the base of the adjective.","exampleCN":"ante 是这个形容词的基底。"},{"word":"anteanus","structure":"Vulgar Latin adjective, reconstructed","meaning":"belonging to before","meaningCN":"属于以前的","example":"The form is marked as a reconstruction.","exampleCN":"这个形式被标为重构。"},{"word":"ancient","structure":"anteanus through Old French ancien","meaning":"of the distant past","meaningCN":"古代的","example":"The ancient wall still stands.","exampleCN":"古墙仍在。"},{"word":"setl","structure":"Old English noun, 'seat'","meaning":"a sitting place","meaningCN":"座位；坐处","example":"Setl is the base of settle.","exampleCN":"setl 是 settle 的基底。"},{"word":"setlan","structure":"Old English verb, 'to place'","meaning":"to place, settle","meaningCN":"安置；定居","example":"The verb gave English settle.","exampleCN":"这个动词产生英语 settle。"},{"word":"settle","structure":"Old English setlan","meaning":"to make a home in a place","meaningCN":"定居；安顿","example":"They settled beside the well.","exampleCN":"他们在井边定居。"},{"word":"-ment","structure":"Latin -mentum through French","meaning":"result or instrument","meaningCN":"结果或工具","example":"Settlement uses this ending.","exampleCN":"settlement 用了这个词尾。"},{"word":"settlement","structure":"settle + -ment","meaning":"a place or act of settling","meaningCN":"聚落；定居","example":"The settlement grew along one street.","exampleCN":"聚落沿一条街扩展。"},{"word":"settler","structure":"settle + -er","meaning":"a person who settles","meaningCN":"定居者","example":"The first settlers dug the well.","exampleCN":"最早的定居者挖了那口井。"},{"word":"ancestor","structure":"Latin antecessor 'one who goes before'","meaning":"a forebear","meaningCN":"祖先","example":"Ancestor shares the 'before' idea.","exampleCN":"ancestor 共享「在前」之意。"}],"latinEntries":[{"word":"ante","structure":"ante (preposition and prefix)","meaning":"before, in front of","meaningCN":"在前；在……之前"},{"word":"anteanus","structure":"anteanus (adj.; Vulgar Latin, reconstructed)","meaning":"belonging to before","meaningCN":"属于以前的"},{"word":"mentum","structure":"mentum (n., second declension; suffix -mentum)","meaning":"result or instrument","meaningCN":"结果或工具"}],"derivatives":[{"word":"settlement","pos":"n.","zh":"settle（定居）+ -ment（拉丁 -mentum，结果名词）→ 聚落；定居点"},{"word":"settler","pos":"n.","zh":"settle（定居）+ -er（施事后缀）→ 定居者"},{"word":"settled","pos":"adj.","zh":"settle（安顿）+ -ed（已完成的）→ 已定居的；安定的"},{"word":"anciently","pos":"adv.","zh":"ancient（古代的）+ -ly（方式副词）→ 在古代"},{"word":"ancientness","pos":"n.","zh":"ancient（古代的）+ -ness（性质名词）→ 古老；年代久远"},{"word":"ancient site","pos":"n.","zh":"ancient（古代的）+ site（地点）→ 古遗址"},{"word":"ancient settlement mound","pos":"n.","zh":"ancient settlement + mound（土丘）→ 古代聚落土丘"}]}},{"word":"settlement","ipa_uk":"/ˈset.əl.mənt/","ipa_us":"/ˈset.əl.mənt/","definition_zh":"聚落；定居；和解；结算；沉降","definition_en":"a place where people have made homes; also the act of settling, an agreement, or the payment of an account","core_image":"河谷边原本零散的几户人家，几年间沿着小路连成一片新屋，烟囱开始成排冒烟","scene":"河谷边原本零散的几户人家，几年间沿着小路连成一片新的定居点。Over a few years, the scattered households along the valley path grew into a new settlement.","sceneCN":"这里 settlement 指「人们定居形成的聚落」（第 1 个义项：聚落、定居点）；句意为原本零散分布的几户人家，几年间沿着河谷小路连成一片新的聚落。可辨识物件：几户人家、小路、河谷、新屋。","pos":[{"tag":"n.","zh":"聚落；定居；和解协议；结算；沉降"}],"collocations":[{"phrase":"human settlement","zh":"人类聚落"},{"phrase":"reach a settlement","zh":"达成和解"},{"phrase":"settlement agreement","zh":"和解协议"},{"phrase":"financial settlement","zh":"财务结算"},{"phrase":"ground settlement","zh":"地基沉降"},{"phrase":"refugee settlement","zh":"难民安置"}],"forms":[{"label":"复数","form":"settlements"},{"label":"动词","form":"settle"},{"label":"过去式","form":"settled"},{"label":"现在分词","form":"settling"},{"label":"形容词","form":"settled"},{"label":"复合词（社区服务中心）","form":"settlement house"}],"derivatives":[{"word":"settler","pos":"n.","zh":"settle（定居）+ -er（施事后缀）→ 定居者；拓荒者"},{"word":"settled","pos":"adj.","zh":"settle（安顿）+ -ed（已完成的）→ 安定的；已定居的"},{"word":"settling","pos":"n.","zh":"settle（沉降）+ -ing（动作名词）→ 沉降；安顿"},{"word":"settlement house","pos":"n.","zh":"settlement + house（屋舍）→ 社区服务中心"},{"word":"settlement pattern","pos":"n.","zh":"settlement + pattern（形态）→ 聚落分布形态"},{"word":"out-of-court settlement","pos":"n.","zh":"out-of-court（庭外）+ settlement → 庭外和解"},{"word":"settlement date","pos":"n.","zh":"settlement + date（日期）→ 结算日"}],"senses":[{"no":"01","title":"A place where people live","titleCN":"聚落；定居点","definition":"a group of homes and other buildings where people have settled","definitionCN":"人们定居形成的房屋与其他建筑的集合","example":"The settlement grew along the river path.","exampleCN":"这个聚落沿着河边小路扩展。","why":"The noun first names the act of settling, then the result: a place that has been settled.","whyCN":"这个名词先指「安顿」这一动作，再指结果：被安顿下来的地方。"},{"no":"02","title":"The act of making a home","titleCN":"定居；拓居","definition":"the process of moving to a place and making a permanent home there","definitionCN":"迁到某地并永久安家的过程","example":"Settlement of the valley began in the ninth century.","exampleCN":"这条河谷的定居始于九世纪。","why":"When the focus is on the process rather than the place, the same noun names the movement.","whyCN":"当焦点在过程而非地点时，同一个名词就指这一迁居过程。"},{"no":"03","title":"An agreement ending a dispute","titleCN":"和解；和解协议","definition":"an agreement that resolves a disagreement without a trial","definitionCN":"不经审判而解决分歧的协议","example":"The two families reached a settlement over the boundary.","exampleCN":"两家就地界达成了和解。","why":"A dispute is 'settled' when it is put to rest, and the noun names the agreement that does it.","whyCN":"争端「被安顿」下来即告了结，名词就指完成这件事的协议。"},{"no":"04","title":"The resolving of a problem","titleCN":"解决；处理","definition":"the act of dealing with a question or difficulty so that it is closed","definitionCN":"把问题或困难处理完毕的动作","example":"The settlement of the claim took three months.","exampleCN":"这桩索赔的处理用了三个月。","why":"This sense keeps the older idea of putting something in a fixed place, applied to a matter rather than a person.","whyCN":"这个义项保留「把某物放到固定位置」的旧意象，只是对象从事变成了事情。"},{"no":"05","title":"Payment of an account","titleCN":"清偿；结算","definition":"the payment of money owed, or the clearing of accounts between parties","definitionCN":"偿付欠款或各方之间结清账目","example":"Settlement of the invoice is due at the end of the month.","exampleCN":"发票款项应在月底结清。","why":"Accounts are 'settled' when nothing remains outstanding, the same image of coming to rest.","whyCN":"账目在不再有余欠时「结清」，仍是「归于静止」的同一意象。"},{"no":"06","title":"Sinking of the ground","titleCN":"沉降","definition":"the gradual downward movement of ground or a building's foundations","definitionCN":"地面或建筑地基逐渐下移","example":"Ground settlement cracked the pavement along the street.","exampleCN":"地面沉降使沿街路面开裂。","why":"The physical sense uses the verb's 'sink down' meaning, which comes from the same Old English root as 'take a seat'.","whyCN":"物理义用的是动词「向下安顿」之义，与「落座」出自同一古英语词根。"},{"no":"07","title":"Placing people in a new area","titleCN":"安置；定居安排","definition":"the organized movement of people, such as refugees, into permanent housing","definitionCN":"有组织地把难民等人口迁入永久住所","example":"The settlement of displaced families took two winters.","exampleCN":"安置流离失所的家庭用了两个冬天。","why":"Here the noun names an official process, with the place and the people both implied.","whyCN":"这里名词指官方的处理流程，地点与人都隐含其中。"},{"no":"08","title":"A community centre","titleCN":"社区服务中心（英式）","definition":"a neighbourhood centre offering social and educational services, in the phrase settlement house","definitionCN":"提供社会与教育服务的社区中心，这一说法专指此类机构","example":"The old settlement on the corner runs evening classes.","exampleCN":"街角那家老社区中心开设夜校课程。","why":"The British sense comes from the idea of workers 'settling' in a poor district to live and help there.","whyCN":"英式义来自工作者「安顿」在贫困街区、就地生活并帮助当地的想法。"}],"etymology":{"intro":{"en":"Settlement is settle plus the Latin-derived noun ending -ment, and settle goes back to an Old English word for a seat. Dates are approximate.","cn":"settlement 由 settle 加拉丁来源的名词词尾 -ment 构成，而 settle 可追到古英语的「座位」一词。年代均为约数。"},"items":[{"era":"OLD ENGLISH SETL","en":"Setl meant 'seat, sitting place', from a Germanic noun for sitting; the same root lies behind sit and seat.","cn":"setl 意为「座位、坐处」，来自日耳曼语的「坐」名词；sit 与 seat 也出自同一词根。"},{"era":"OLD ENGLISH SETLAN","en":"The verb setlan meant 'to place, set, settle', and it also gave the modern sense of ground sinking.","cn":"动词 setlan 意为「安置、放定、定居」，也产生了现代「地面沉降」之义。"},{"era":"MIDDLE ENGLISH SETTLEMENT","en":"The noun settlement appears in Middle English, at first for the act of setting or coming to rest.","cn":"名词 settlement 见于中古英语，最初指安置或静止下来的动作。"},{"era":"LEGAL AND FINANCIAL SENSES","en":"From the seventeenth century the word named the ending of a dispute and the clearing of an account, both images of coming to rest.","cn":"从 17 世纪起，这个词指争端的了结与账目的结清，两者都是「归于静止」的意象。"},{"era":"PLACE SENSE","en":"The sense of a colony or village settled by people became common in the eighteenth and nineteenth centuries.","cn":"指人们建立的殖民地或村落之义在 18 与 19 世纪变得常见。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first dates and deeper root): the earliest uses of each sense are not precisely dated, and the pre-Germanic origin of setl is reconstructed rather than recorded.","cn":"来源不确定（首见年代与更深词根）：各义项的最早使用没有确切年代；setl 的日耳曼语之前来源属重构而非有记录的形式。"}]},"similar":{"note":{"en":"Group one holds words from the same settle family or from a sitting root; group two holds words for a place, an agreement and a payment.","cn":"第一组是同出 settle 词族或「坐」词根的词；第二组是指地点、协议与付款的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"settler","ipa":"/ˈset.lər/","tag":"person, not place","definition":"Settle plus -er 'one who does'; a settler is a person, a settlement is the place.","definitionCN":"settle 加 -er「做……的人」；settler 是人，settlement 是地点。"},{"word":"sediment","ipa":"/ˈsed.ɪ.ment/","tag":"Latin sitting root","definition":"From Latin sedimentum, based on sedere 'to sit'; it names material that has settled, not a village.","definitionCN":"来自拉丁 sedimentum，基于 sedere「坐」；指沉积下来的物质，不是村落。"},{"word":"settling","ipa":"/ˈset.lɪŋ/","tag":"action, not result","definition":"The participle or gerund of settle, naming the process rather than the place or agreement.","definitionCN":"settle 的分词或动名词，指过程，而非地点或协议。"},{"word":"set","ipa":"/set/","tag":"same seat image, wider use","definition":"From the same Germanic sitting stock; it means to put something in place, a much wider verb.","definitionCN":"同出日耳曼「坐」词族；意为把某物放定，用法宽得多。"}]},{"heading":"NEAR MEANING","entries":[{"word":"village","ipa":"/ˈvɪl.ɪdʒ/","tag":"dwelling group","definition":"A small community seen as a social unit, while settlement stresses that it was founded.","definitionCN":"作为社会单元的小社群，而 settlement 强调其被建立。"},{"word":"colony","ipa":"/ˈkɒl.ə.ni/","tag":"planted place","definition":"A settlement founded by migrants, often tied to a parent country.","definitionCN":"由移民建立、常与母国相连的聚落。"},{"word":"agreement","ipa":"/əˈɡriː.mənt/","tag":"general accord","definition":"Any arrangement reached by parties; a settlement specifically ends a dispute.","definitionCN":"各方达成的任何安排；settlement 特指结束争端。"},{"word":"payment","ipa":"/ˈpeɪ.mənt/","tag":"money handed over","definition":"The handing over of money, while settlement stresses that the account is closed.","definitionCN":"付款行为，而 settlement 强调账目结清。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Old English seat word, the many senses of 'coming to rest', and the settlement house.","cn":"正常联想：古英语「座位」词、各义项共有的「归于静止」意象，以及社区服务中心。"},"normal":[{"en":"Old English setl 'seat' also lies behind sit and seat.","cn":"古英语 setl「座位」也是 sit 与 seat 的来源。"},{"en":"Every sense shares the image of something coming to rest.","cn":"每个义项都共享「某物安定下来」的意象。"},{"en":"-ment is Latin -mentum, marking a result.","cn":"-ment 是拉丁 -mentum，标记结果。"},{"en":"A settlement is a place; a settler is a person.","cn":"settlement 是地点；settler 是人。"},{"en":"Settlement house is the British community-centre sense.","cn":"settlement house 是英式社区服务中心义。"}],"abstract":[{"en":"Picture scattered households joining into one row of smoking chimneys.","cn":"想象零散的几户人家连成一排冒烟的烟囱。"},{"en":"Picture a dispute laid down like a heavy box set on the floor.","cn":"想象一桩争端像重箱被放到地上，不再被搬动。"},{"en":"Picture an invoice with a line drawn through it and the word closed beside it.","cn":"想象一张发票被划掉，旁边写着「已结清」。"}]},"examples":[{"en":"The settlement expanded along the old road.","cn":"这个聚落沿旧大道扩展。"},{"en":"The parties reached a settlement before the trial began.","cn":"各方在开庭前达成了和解。"},{"en":"Ground settlement damaged the row of shops.","cn":"地面沉降损坏了那排店铺。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「settle（安顿）＋ment（结果）」——人安顿下来形成的地方 → 聚落；事情安顿下来 → 和解","word":"settlement"},"root":"settle 出古英语 setl「座位」与 setlan「安置」，与 sit、seat 同一日耳曼「坐」词根；-ment 出拉丁 -mentum，经法语，指结果或工具。","sensesIntro":{"en":"Eight senses share one image of coming to rest: a place founded, a people moved in, a dispute ended, a problem closed, an account cleared, ground sinking, refugees housed, and a community centre.","cn":"八个义项共享「归于静止」的意象：建立的地方、迁入的人群、结束的争端、处理完的问题、结清的账目、下沉的地面、被安置的难民，以及社区中心。"},"semanticMap":{"core":{"en":"CORE IMAGE: something heavy set down and left at rest, whether a house, a quarrel or an account.","cn":"核心意象：沉重之物被放下并不再移动，无论是一间屋、一场争执还是一笔账。"},"chain":["SEAT","PLACE DOWN","HOME","AGREEMENT","ACCOUNT","SINKING"],"branches":[{"senses":"01 · 02","en":"TAKING A SEAT: settling means coming to sit in one place, and the place is the result.","cn":"落座：定居就是在一个地方坐下来，那个地方就是结果。"},{"senses":"03 · 04","en":"PUT TO REST: a dispute or question is settled when it stops moving.","cn":"归于平息：争端或问题不再变动时即被解决。"},{"senses":"05","en":"CLEARED ACCOUNT: money owed is settled when nothing remains.","cn":"账目结清：欠款在无所剩余时被结清。"},{"senses":"06","en":"SINKING GROUND: the same verb describes earth moving down to rest.","cn":"下沉的地面：同一动词也描述泥土向下安顿。"},{"senses":"07 · 08","en":"ORGANIZED PLACE: refugees are settled, and a settlement house settles helpers in a district.","cn":"有组织的安置：难民被安置，社区中心则让服务者在一区安顿。"}]},"affixes":{"intro":{"en":"Settlement is an Old English verb with a Latin-derived noun ending, and its family covers sitting, founding and clearing.","cn":"settlement 是古英语动词加拉丁来源名词词尾，其词族涵盖落座、建立与结清。"},"latinIntro":{"en":"Old English setl gives settle, settlement, settler and seat; Latin -mentum gives the noun ending; Latin sedere 'to sit' is a cognate, not the direct source.","cn":"古英语 setl 产生 settle、settlement、settler 与 seat；拉丁 -mentum 提供名词词尾；拉丁 sedere「坐」是同源旁证，并非直接来源。"},"items":[{"word":"setl","structure":"Old English noun, 'seat'","meaning":"a sitting place","meaningCN":"座位；坐处","example":"Setl is the base of the family.","exampleCN":"setl 是这个词族的基底。"},{"word":"setlan","structure":"Old English verb, 'to place'","meaning":"to place, settle","meaningCN":"安置；定居","example":"Setlan gave the modern verb settle.","exampleCN":"setlan 产生现代动词 settle。"},{"word":"settle","structure":"Old English setlan","meaning":"to make a home; to come to rest","meaningCN":"定居；安顿；沉降","example":"They settled by the river.","exampleCN":"他们在河边定居。"},{"word":"-ment","structure":"Latin -mentum through French","meaning":"result or instrument","meaningCN":"结果或工具","example":"Settlement uses this ending.","exampleCN":"settlement 用了这个词尾。"},{"word":"settlement","structure":"settle + -ment","meaning":"a place, act, agreement or clearance","meaningCN":"聚落；定居；和解；结算","example":"The settlement grew quickly.","exampleCN":"这个聚落发展很快。"},{"word":"settler","structure":"settle + -er","meaning":"a person who settles","meaningCN":"定居者","example":"The settlers built the first mill.","exampleCN":"定居者建了第一座磨坊。"},{"word":"settled","structure":"settle + -ed","meaning":"established and stable","meaningCN":"安定的；已定居的","example":"A settled community keeps its records.","exampleCN":"安定的社区会保存记录。"},{"word":"settling","structure":"settle + -ing","meaning":"the process of sinking or settling","meaningCN":"沉降；安顿","example":"Settling of the subsoil continued for years.","exampleCN":"底土的沉降持续了多年。"},{"word":"settlement house","structure":"settlement + house","meaning":"a community centre","meaningCN":"社区服务中心","example":"The settlement house runs a night school.","exampleCN":"社区中心开设夜校。"},{"word":"seat","structure":"Old English setl, same root","meaning":"a place to sit","meaningCN":"座位","example":"Seat and settle share the root.","exampleCN":"seat 与 settle 共享词根。"}],"latinEntries":[{"word":"mentum","structure":"mentum (n., second declension; suffix -mentum)","meaning":"result or instrument","meaningCN":"结果或工具"},{"word":"sedere","structure":"sedere, sedi, sessum (verb, second conjugation)","meaning":"to sit (cognate, not the direct source)","meaningCN":"坐（同源旁证，并非直接来源）"}],"derivatives":[{"word":"settler","pos":"n.","zh":"settle（定居）+ -er（施事后缀）→ 定居者；拓荒者"},{"word":"settled","pos":"adj.","zh":"settle（安顿）+ -ed（已完成的）→ 安定的；已定居的"},{"word":"settling","pos":"n.","zh":"settle（沉降）+ -ing（动作名词）→ 沉降；安顿"},{"word":"settlement house","pos":"n.","zh":"settlement + house（屋舍）→ 社区服务中心"},{"word":"settlement pattern","pos":"n.","zh":"settlement + pattern（形态）→ 聚落分布形态"},{"word":"out-of-court settlement","pos":"n.","zh":"out-of-court（庭外）+ settlement → 庭外和解"},{"word":"settlement date","pos":"n.","zh":"settlement + date（日期）→ 结算日"}]}},{"word":"settlement pattern","ipa_uk":"/ˈset.əl.mənt ˈpæt.ən/","ipa_us":"/ˈset.əl.mənt ˈpæt.ɚn/","definition_zh":"聚落分布形态；聚落格局","definition_en":"the way settlements are arranged across a landscape, studied in geography and archaeology","core_image":"测绘地图上，村落沿河谷排成一串，间距几乎相等，像被尺子量过","scene":"测绘地图摊在桌上，村落沿河谷排成一串，间距几乎相等。On the survey map, a regular settlement pattern showed villages spaced along the valley.","sceneCN":"这里 settlement pattern 指「聚落在空间上的分布形态」（第 1 个义项：聚落分布形态）；句意为桌上的测绘地图呈现出规则的聚落分布形态，村落沿河谷等距排开。可辨识物件：测绘地图、河谷、村落点、比例尺。","pos":[{"tag":"n.","zh":"聚落分布形态；聚落格局"}],"collocations":[{"phrase":"dispersed settlement pattern","zh":"分散聚落形态"},{"phrase":"nucleated settlement pattern","zh":"集中聚落形态"},{"phrase":"regional settlement pattern","zh":"区域聚落格局"},{"phrase":"settlement pattern analysis","zh":"聚落形态分析"},{"phrase":"historic settlement pattern","zh":"历史聚落格局"},{"phrase":"rural settlement pattern","zh":"乡村聚落形态"}],"forms":[{"label":"复数","form":"settlement patterns"},{"label":"相关名词（聚落）","form":"settlement"},{"label":"相关名词（模式）","form":"pattern"},{"label":"形容词（有图案的）","form":"patterned"},{"label":"相关名词（格局化）","form":"patterning"},{"label":"复合词（聚落形态分析）","form":"settlement pattern analysis"}],"derivatives":[{"word":"settlement","pos":"n.","zh":"settle（定居）+ -ment（拉丁 -mentum，结果名词）→ 聚落；定居"},{"word":"patterned","pos":"adj.","zh":"pattern（图案）+ -ed（具有的）→ 有图案的；有规律的"},{"word":"patterning","pos":"n.","zh":"pattern（模式）+ -ing（动作名词）→ 格局化；图案配置"},{"word":"settlement pattern analysis","pos":"n.","zh":"settlement pattern + analysis（分析）→ 聚落形态分析"},{"word":"nucleated settlement","pos":"n.","zh":"nucleated（聚集成核的）+ settlement → 集中聚落"},{"word":"dispersed settlement","pos":"n.","zh":"dispersed（分散的）+ settlement → 分散聚落"}],"senses":[{"no":"01","title":"The arrangement of settlements","titleCN":"聚落分布形态","definition":"the way villages, towns and farms are arranged across an area","definitionCN":"村落、城镇与农场在一片区域中的排列方式","example":"The survey described a settlement pattern of villages along the river.","exampleCN":"这次调查描述了村落沿河分布的聚落形态。","why":"The phrase takes the places and adds a word for repeated arrangement, so it names layout rather than any single place.","whyCN":"这个短语在地点之上加了表示重复排列的词，命名的是布局，而非单个地点。"},{"no":"02","title":"A hierarchy of sizes","titleCN":"聚落等级体系","definition":"the ranking of settlements by size, function or services within a region","definitionCN":"区域内聚落按规模、功能或服务的等级排列","example":"The settlement pattern ran from hamlets up to one market town.","exampleCN":"这一聚落格局从小村一直排到一个集镇。","why":"Arrangement includes rank: a region's places are not only spread out but ordered.","whyCN":"排列包含等级：区域内的地点不仅散开，还被排出高低。"},{"no":"03","title":"A regular spatial order","titleCN":"空间排列规律","definition":"a repeated spacing or alignment that can be measured and mapped","definitionCN":"可测量、可制图的重复间距或对齐关系","example":"The settlement pattern showed houses at intervals of about one kilometre.","exampleCN":"聚落形态显示房屋间隔约一公里。","why":"Pattern implies repetition, so the phrase is used when spacing itself is the object of study.","whyCN":"后半部分含有重复之意，因此当研究对象是间距本身时就用这个短语。"},{"no":"04","title":"Nucleated or dispersed types","titleCN":"集中或分散的聚落类型","definition":"the contrast between clustered villages and scattered farmsteads","definitionCN":"聚集村落与分散农舍之间的对比","example":"The valley's settlement pattern is dispersed, with no single centre.","exampleCN":"这条河谷的聚落形态是分散的，没有单一中心。","why":"Two basic types dominate the literature, and the phrase names whichever type a region shows.","whyCN":"文献中两种基本类型占主导，这个短语指某区域呈现的那一种。"},{"no":"05","title":"A historical geography term","titleCN":"历史地理中的聚落格局","definition":"the long-run arrangement of settlement recorded in maps, taxes and place names","definitionCN":"由地图、税册与地名记录下来的长期聚落布置","example":"Tax rolls let historians reconstruct the medieval settlement pattern.","exampleCN":"税册让历史学家重建中世纪的聚落格局。","why":"Historical geography uses the phrase for arrangements that can no longer be seen on the ground.","whyCN":"历史地理学用这个短语指地面上已看不见的旧日布置。"},{"no":"06","title":"Fabric in conservation planning","titleCN":"保护规划中的聚落肌理","definition":"the existing arrangement of buildings and plots that planning seeks to respect","definitionCN":"规划所要尊重的现有建筑与地块布置","example":"The plan protects the historic settlement pattern around the green.","exampleCN":"规划保护绿地周围的历史聚落肌理。","why":"Planning borrows the term because new buildings must fit an inherited arrangement.","whyCN":"规划借用这个术语，因为新建筑必须嵌入承袭下来的布置。"},{"no":"07","title":"Any distribution in metaphor","titleCN":"分布格局（比喻）","definition":"the spread of anything across a space, described as if it were settlements","definitionCN":"任何事物在空间中的分布，被当作聚落来描述","example":"The settlement pattern of the fungus followed the fallen logs.","exampleCN":"这种真菌的分布格局沿着倒木展开。","why":"The metaphor keeps 'spread across a surface', which is the phrase's core.","whyCN":"这个比喻保留「在一表面上散布」这一核心意思。"},{"no":"08","title":"A mapped or statistical expression","titleCN":"地图与统计中的表达","definition":"the representation of such an arrangement in maps, counts or models","definitionCN":"这种排列在地图、计数或模型中的呈现","example":"The report plotted the settlement pattern as points and densities.","exampleCN":"报告把聚落形态绘成点与密度。","why":"Once arrangement is measured, it can be expressed as data, and the phrase follows the data.","whyCN":"排列一旦可测，就能表达为数据，这个短语也随之进入数据表达。"}],"etymology":{"intro":{"en":"Settlement pattern joins an Old English settling noun to a word that reached English from Latin patronus by way of French. Dates are approximate.","cn":"settlement pattern 把古英语的「定居」名词与一个经法语来自拉丁 patronus 的词连在一起。年代均为约数。"},"items":[{"era":"LATIN PATER","en":"Pater meant 'father'; patronus 'protector, patron' was built from it, and the family includes paternal and patron.","cn":"pater 意为「父亲」，patronus「保护人、庇护者」由它构成，词族还包括 paternal 与 patron。"},{"era":"LATIN PATRONUS","en":"Patronus named a protector or a person of standing who supported others; the word carried ideas of authority and example.","cn":"patronus 指保护人或支持他人的有地位者，词中带有权威与范例的意味。"},{"era":"OLD FRENCH PATRON","en":"Old French patron developed the sense 'model, example to be copied', especially in craft work.","cn":"古法语 patron 发展出「范本、可照抄的样例」义，尤用于手艺制作。"},{"era":"ENGLISH PATTERN","en":"English pattern, from the same French word, named a model or a repeated design; pattern and patron are doublets.","cn":"英语 pattern 来自同一个法语词，指范本或重复的纹样；pattern 与 patron 是同源异形词。"},{"era":"THE PHRASE","en":"Geography and archaeology joined settlement to pattern in the twentieth century to name the arrangement of places across a region.","cn":"地理学与考古学在 20 世纪把 settlement 与 pattern 连起来，指一个区域内各地点的排列。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first use and semantic bridge): the exact route from 'patron' to 'model' is not fully documented, and the phrase has no recorded first citation.","cn":"来源不确定（首见使用与语义过渡）：从「保护人」到「范本」的确切演变缺乏完整记载，这个短语也没有可考的最早书证。"}]},"similar":{"note":{"en":"Group one holds words from the same Latin father root with other uses; group two holds words for layout and distribution.","cn":"第一组是同出拉丁「父亲」词根、用途不同的词；第二组是表布局与分布的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"patron","ipa":"/ˈpeɪ.trən/","tag":"doublet, a person","definition":"The same Latin source as pattern, but it means a supporter or customer, not a design.","definitionCN":"与 pattern 同出拉丁来源，但指支持者或顾客，不是纹样。"},{"word":"paternity","ipa":"/pəˈtɜː.nə.ti/","tag":"father root","definition":"From Latin pater 'father'; it names fatherhood, with no link to arrangement.","definitionCN":"来自拉丁 pater「父亲」；指父身份，与排列无关。"},{"word":"patter","ipa":"/ˈpæt.ər/","tag":"sound word, not pattern","definition":"Probably imitative of quick light sounds; it has nothing to do with Latin patronus.","definitionCN":"大概模仿轻快连续的声音；与拉丁 patronus 无关。"},{"word":"paten","ipa":"/ˈpeɪ.tən/","tag":"dish, not design","definition":"From Latin patena 'shallow dish'; it sounds like pattern but names a plate.","definitionCN":"来自拉丁 patena「浅盘」；读音近似 pattern，却指盘子。"}]},{"heading":"NEAR MEANING","entries":[{"word":"layout","ipa":"/ˈleɪ.aʊt/","tag":"arrangement","definition":"The way parts are placed, often within one building or page.","definitionCN":"各部分放置的方式，常用于一栋建筑或一页之内。"},{"word":"distribution","ipa":"/ˌdɪs.trɪˈbjuː.ʃən/","tag":"spread","definition":"The spread of items over an area, which is what the phrase measures.","definitionCN":"事物在一片区域上的散布，正是该短语所测量的对象。"},{"word":"arrangement","ipa":"/əˈreɪndʒ.mənt/","tag":"general order","definition":"Any ordered placing, with no suggestion of repetition.","definitionCN":"任何有秩序的放置，不含重复之意。"},{"word":"spatial order","ipa":"/ˈspeɪ.ʃəl ˈɔː.dər/","tag":"geographical order","definition":"The ordering of things in space, close to the phrase but more abstract.","definitionCN":"事物在空间中的秩序，含义接近但更抽象。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real doublet patron and pattern, the map image and the two basic types.","cn":"正常联想：真实存在的同源异形词 patron 与 pattern、地图意象，以及两种基本类型。"},"normal":[{"en":"Pattern and patron are doublets from Latin patronus.","cn":"pattern 与 patron 是拉丁 patronus 的同源异形词。"},{"en":"Latin pater 'father' is behind patronus.","cn":"拉丁 pater「父亲」是 patronus 的基底。"},{"en":"Real types: nucleated settlement, dispersed settlement.","cn":"真实类型：集中聚落、分散聚落。"},{"en":"The phrase measures spacing across a region, not one place.","cn":"这个短语测量的是区域内的间距，而非单个地点。"},{"en":"Planning uses it for inherited fabric that new work must respect.","cn":"规划用它指新建筑必须尊重的既有肌理。"}],"abstract":[{"en":"Picture dots on a map spaced like beads on a string.","cn":"想象地图上的点像串珠一样等距排开。"},{"en":"Picture a ruler laid across a valley to measure the gaps between villages.","cn":"想象一把尺横过河谷，量村落之间的间隔。"},{"en":"Picture an old cloth whose weave new patches must match.","cn":"想象一块旧布，新补丁必须顺着它的织纹。"}]},"examples":[{"en":"The regional settlement pattern shifted from farms to villages.","cn":"区域聚落形态从农舍转向村落。"},{"en":"A dispersed settlement pattern leaves few shared services.","cn":"分散的聚落形态使共享服务很少。"},{"en":"The plan protects the settlement pattern around the old green.","cn":"规划保护旧绿地周围的聚落格局。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「settlement（聚落）＋pattern（图案）」——聚落在地图上排出的图案 → 聚落形态","word":"settlement pattern"},"root":"settlement 出古英语 setl「座位」与 setlan「安置」，加拉丁 -mentum；pattern 出拉丁 patronus「保护人」（源自 pater「父亲」），经古法语 patron「范本」，与 patron 为同源异形词。","sensesIntro":{"en":"Eight senses begin with the arrangement of places, then add hierarchy, measurable spacing, nucleated and dispersed types, historical reconstruction, conservation fabric, metaphor and mapped data.","cn":"八个义项从地点的排列出发，随后是等级、可测间距、集中与分散类型、历史重建、保护肌理、比喻，以及地图化的数据。"},"semanticMap":{"core":{"en":"CORE IMAGE: dots on a map spaced like beads, and a ruler measuring the gaps.","cn":"核心意象：地图上像串珠般排开的点，以及一把量间距的尺。"},"chain":["FATHER","PATRON","MODEL","REPEATED DESIGN","PLACES ON A MAP","MEASURED SPACING"],"branches":[{"senses":"01 · 03","en":"MAP ARRANGEMENT: places plus repetition give a measurable layout.","cn":"地图排列：地点加重复构成可测布局。"},{"senses":"02","en":"RANK: the layout also orders places by size and service.","cn":"等级：布局同时按规模与服务给地点排序。"},{"senses":"04","en":"TWO TYPES: clustered and scattered are the basic contrast.","cn":"两种类型：聚集与分散构成基本对照。"},{"senses":"05 · 06","en":"PAST AND PLAN: historical maps reconstruct it, and planning protects its fabric.","cn":"过去与规划：历史地图重建它，规划保护它的肌理。"},{"senses":"07 · 08","en":"BEYOND PLACES: the metaphor and mapped data extend 'spread' to anything.","cn":"超出地点之外：比喻与地图数据把「散布」扩展到任何对象。"}]},"affixes":{"intro":{"en":"The phrase combines an Old English settling noun with a Latin-derived word for model; its endings follow those two stocks.","cn":"这个短语把古英语的「定居」名词与拉丁来源的「范本」词合在一起，词缀沿这两条来源展开。"},"latinIntro":{"en":"Latin pater gives patronus, patron, pattern and paternal; Old English setl gives settle and settlement.","cn":"拉丁 pater 产生 patronus、patron、pattern 与 paternal；古英语 setl 产生 settle 与 settlement。"},"items":[{"word":"pater","structure":"Latin noun, 'father'","meaning":"father","meaningCN":"父亲","example":"Pater is the base of patronus.","exampleCN":"pater 是 patronus 的基底。"},{"word":"patronus","structure":"pater + -onus, 'protector'","meaning":"a protector, a patron","meaningCN":"保护人；庇护者","example":"Patronus gave both patron and pattern.","exampleCN":"patronus 同时产生 patron 与 pattern。"},{"word":"patron","structure":"Latin patronus through French","meaning":"a supporter or customer","meaningCN":"赞助人；顾客","example":"The patron funded the survey.","exampleCN":"赞助人出资做了这次测绘。"},{"word":"pattern","structure":"Old French patron 'model'","meaning":"a repeated design or arrangement","meaningCN":"图案；模式","example":"The pattern repeats every kilometre.","exampleCN":"这个格局每一公里重复一次。"},{"word":"patterned","structure":"pattern + -ed","meaning":"marked with a pattern","meaningCN":"有图案的；有规律的","example":"A patterned spread appeared on the map.","exampleCN":"地图上出现了有规律的分布。"},{"word":"patterning","structure":"pattern + -ing","meaning":"the forming of a pattern","meaningCN":"格局化；图案配置","example":"Patterning of the valley took centuries.","exampleCN":"河谷格局的形成历经数百年。"},{"word":"settle","structure":"Old English setlan","meaning":"to make a home","meaningCN":"定居；安顿","example":"People settled along the path.","exampleCN":"人们沿小路定居。"},{"word":"settlement","structure":"settle + -ment","meaning":"a place or act of settling","meaningCN":"聚落；定居","example":"The settlement lay by the river.","exampleCN":"聚落位于河边。"},{"word":"settlement pattern","structure":"settlement + pattern","meaning":"the arrangement of settlements","meaningCN":"聚落分布形态","example":"The map showed a regular settlement pattern.","exampleCN":"地图显示出规则的聚落形态。"}],"latinEntries":[{"word":"pater","structure":"pater, patris (m., third declension)","meaning":"father","meaningCN":"父亲"},{"word":"patronus","structure":"patronus, patroni (m., second declension)","meaning":"protector, patron","meaningCN":"保护人；庇护者"}],"derivatives":[{"word":"settlement","pos":"n.","zh":"settle（定居）+ -ment（拉丁 -mentum，结果名词）→ 聚落；定居"},{"word":"patterned","pos":"adj.","zh":"pattern（图案）+ -ed（具有的）→ 有图案的；有规律的"},{"word":"patterning","pos":"n.","zh":"pattern（模式）+ -ing（动作名词）→ 格局化；图案配置"},{"word":"settlement pattern analysis","pos":"n.","zh":"settlement pattern + analysis（分析）→ 聚落形态分析"},{"word":"nucleated settlement","pos":"n.","zh":"nucleated（聚集成核的）+ settlement → 集中聚落"},{"word":"dispersed settlement","pos":"n.","zh":"dispersed（分散的）+ settlement → 分散聚落"}]}}]);
